        'needs_db_verify' => 'ஒருங்கிணைப்பு அட்டவணைகள் இன்னும் தரவுத்தளத்தில் இல்லை. இணைப்பைச் சேர்க்கும் முன் System-இல் தரவுத்தள சரிபார்ப்பை இயக்கவும்.',
