        'inactive_label' => 'முடக்கம்',
        'inbound_badge' => 'புதுப்பிப்புகள் இயக்கத்தில்',
        'help_link' => '{name}-ஐ எவ்வாறு அமைப்பது',
        'mapping_help_link' => 'இவை என்ன என்று தெரியவில்லையா?',
        'mapping_title' => 'மேப்பிங்',
        'mapping_intro' => 'ஒவ்வொரு விதியிலும் project key-ஐ தட்டச்சு செய்ய வேண்டியதில்லை என்பதற்காக, உங்கள் மதிப்புகள் {name}-இல் எதைக் குறிக்கின்றன என்பதை முடிவு செய்யுங்கள். வெறுமையாக விட்டவை அனுப்பப்படாது.',
        'map_projects' => 'எந்த project-இல் issues செல்லும்',
        'map_projects_hint' => 'இயல்புநிலையை அமைத்து, தேவையான இடங்களில் விதிவிலக்குகளைச் சேர்க்கவும். மிகவும் குறிப்பிட்ட விதியே வெல்லும்: துறை நிறுவனத்தை வெல்லும், நிறுவனம் இயல்புநிலையை வெல்லும்.',
        'map_group_default' => 'இயல்புநிலை',
        'map_group_dept' => 'துறை வாரியான விதிவிலக்குகள் — கீழே உள்ள அனைத்தையும் இவை வெல்லும்',
        'map_group_company' => 'நிறுவன வாரியான விதிவிலக்குகள்',
        'map_types' => 'டிக்கெட் வகை issue வகையாக மாறுகிறது',
        'map_types_hint' => 'Issue வகைகள் project-க்கு project மாறுபடும்; எனவே இவை உங்கள் இயல்புநிலை project-இலிருந்து வரும் பரிந்துரைகள் — எந்த மதிப்பையும் தட்டச்சு செய்யலாம்.',
        'map_priorities' => 'முன்னுரிமை',
        'map_priorities_hint' => 'இங்கே வேண்டுமென்றே இயல்புநிலை இல்லை: ஒவ்வொரு issue-ஐயும் அவசரம் எனக் குறிப்பது யாருக்கும் உதவாது. மேப் செய்யப்படாத முன்னுரிமை விளக்கத்தில் உரையாக இன்னும் தோன்றும். ஒரு project முன்னுரிமையை நிராகரித்தால் issue முன்னுரிமை இல்லாமல் எழுப்பப்படும்.',
        'map_default' => 'மற்ற அனைத்தும்',
        'map_none' => 'மேப் செய்யப்படவில்லை',
        'map_saved' => 'மேப்பிங் சேமிக்கப்பட்டது',
        'map_needs_verify' => 'முதலில் தரவுத்தள சரிபார்ப்பை இயக்கவும் — இந்த நிறுவலில் மேப்பிங் அட்டவணை இன்னும் இல்லை.',
        'map_load_failed' => 'மேப்பிங்கை ஏற்ற முடியவில்லை.',
        'attach_label' => 'டிக்கெட்டின் இணைப்புகளை {name}-க்கு அனுப்பு',
        'attach_hint' => 'பிழை அறிக்கையில் ஸ்கிரீன்ஷாட்டே பெரும்பாலும் அறிக்கையாக இருக்கும். மின்னஞ்சலில் பதிக்கப்பட்ட படங்கள் — கையொப்பங்கள், லோகோக்கள், tracking pixels — ஒருபோதும் அனுப்பப்படாது; யாரோ வேண்டுமென்றே இணைத்த கோப்புகள் மட்டுமே. பெரிய கோப்புகள் எழுப்புதலைத் தோல்வியடையச் செய்யாமல் தவிர்க்கப்படும்; எதுவும் அனுப்பப்படும் முன் எப்போதும் பட்டியலைப் பார்ப்பீர்கள்.',
        'inbound_label' => '{name}-இலிருந்து புதுப்பிப்புகளை ஏற்று',
        'inbound_hint' => '{name}-இல் எழுதப்படும் கருத்துகள் இணைக்கப்பட்ட டிக்கெட்டில் உள் குறிப்புகளாக வரும். அவை கோரிக்கையாளருக்கு ஒருபோதும் காட்டப்படாது. இதை இயக்கிய பிறகான முதல் சரிபார்ப்பு எதையும் இறக்குமதி செய்யாது — தொடக்கப் புள்ளியை மட்டுமே குறிக்கும்; எனவே இதை இயக்குவதால் பழைய கருத்துகளின் குவியல் திரும்பி வராது.',
        'test' => 'சோதி',
        'save_failed' => 'இணைப்பைச் சேமிக்க முடியவில்லை.',
        'saved' => 'இணைப்பு சேமிக்கப்பட்டது.',
        'deleted' => 'இணைப்பு நீக்கப்பட்டது.',
        'delete_title' => 'இணைப்பை நீக்கு',
        'confirm_delete' => 'இந்த இணைப்பை நீக்கவா?',
        'confirm_delete_named' => '“{name}” இணைப்பை நீக்கவா? அதில் உள்ள issues-உடன் ஏற்கனவே இணைக்கப்பட்ட டிக்கெட்டுகள் தங்கள் இணைப்புகளை வைத்திருக்கும்.',
        'slack_blurb' => 'Slack சேனலில் உள்ள செய்தியை டிக்கெட்டாக மாற்றி, thread-ஐ விட்டு வெளியேறாமல் இன்பாக்ஸிலிருந்தே பதிலளிக்கவும்.',
        'configured' => 'அமைக்கப்பட்டது',
        'not_configured' => 'அமைக்கப்படவில்லை',
        'tika_blurb' => 'PDF-கள், பழைய Office கோப்புகள் மற்றும் ஸ்கேன் செய்த ஆவணங்களுக்குள் இருக்கும் உரையைப் படிக்கவும், அவற்றைத் தேட முடியும்.',
        'tika_intro' => 'FreeITSM-ஐ ஆவணம் படிக்கும் சேவையுடன் இணைக்கிறது. Word, Excel, PowerPoint மற்றும் எளிய உரைக் கோப்புகள் இதில்லாமலேயே ஏற்கனவே தேடப்படுகின்றன; FreeITSM தானாகப் படிக்க முடியாத வடிவங்களை Tika சேர்க்கிறது.',
        'tika_security_title' => 'நெட்வொர்க்கிலிருந்து விலக்கி வைக்கவும்',
        'tika_security_body' => 'Tika-வுக்கு கடவுச்சொல்லோ எந்த வகை அங்கீகாரமோ இல்லை: அதை அடையக்கூடிய எவரும் அனுப்பப்படும் எந்தக் கோப்பையும் படிக்க முடியும். இந்தச் சேவையகம் மட்டுமே அதனுடன் பேசும்படி இயக்கவும் — 127.0.0.1-உடன் இணைத்து, அல்லது தனிப்பட்ட container நெட்வொர்க்கில் — அதன் port-ஐ இணையத்தில் ஒருபோதும் திறக்க வேண்டாம்.',
        'tika_connection' => 'இணைப்பு',
        'tika_url_label' => 'முகவரி',
        'tika_url_hint' => 'எடுத்துக்காட்டாக http://127.0.0.1:9998. ஆவணம் படிப்பதை நிறுத்த இதை காலியாக விடவும்; PDF-கள் படிக்க முடியாதவை எனப் பட்டியலிடப்படும்.',
        'tika_timeout_label' => 'நேர வரம்பு (வினாடிகள்)',
        'tika_timeout_hint' => 'ஒரு ஆவணத்துக்காக எவ்வளவு நேரம் காத்திருக்க வேண்டும். ஸ்கேன் செய்த பக்கங்கள் சாதாரண உரையை விட மிகவும் அதிக நேரம் எடுக்கும்.',
        'tika_test' => 'இணைப்பைச் சோதி',
        'tika_test_ok' => 'இணைக்கப்பட்டது. {detail}',
        'tika_test_bad' => 'அதை அடைய முடியவில்லை. {detail}',
        'tika_saved' => 'சேமிக்கப்பட்டது. புதிய இணைப்புகள் இனி படிக்கப்படும்.',
        'tika_saved_off' => 'சேமிக்கப்பட்டது. ஆவணம் படிப்பது நிறுத்தப்பட்டுள்ளது.',
        'tika_requeued' => 'முன்பு படிக்க முடியாத {n} இணைப்புகள் வரிசையில் சேர்க்கப்பட்டுள்ளன.',
        'tika_pending' => '{n} இணைப்புகள் படிக்கப்படக் காத்திருக்கின்றன.',
        'tika_formats' => 'எவை படிக்கப்படுகின்றன',
        'tika_without' => 'Tika இல்லாமலேயே ஏற்கனவே படிக்கப்படுபவை',
        'tika_with' => 'Tika சேர்ப்பவை',
        'tika_legacy_office' => 'பழைய Office கோப்புகள் (.doc, .xls, .ppt)',
        'tika_scanned' => 'ஸ்கேன் செய்த ஆவணங்கள் மற்றும் உரையின் புகைப்படங்கள், எழுத்து அறிதல் மூலம்',
        'tika_running' => 'ஒன்றை இயக்குதல்',
        'tika_running_body' => 'FreeITSM, Tika-வை நிறுவவோ நிர்வகிக்கவோ செய்யாது. உங்களுக்கு ஏற்ற இடத்தில் நீங்களே இயக்கி, அதன் முகவரியை மேலே உள்ளிடுங்கள். Docker மூலம் அது ஒரே கட்டளை:',
        'tika_image_note' => '-full image-ஐப் பயன்படுத்துங்கள். சிறியதில் எழுத்து அறிதல் இல்லை, எனவே ஸ்கேன் செய்த ஆவணங்கள் காலியாக வரும்.',
        'slack_workspaces' => 'Slack workspaces',
        'slack_workspaces_desc' => 'ஒவ்வொன்றும் உங்கள் சொந்த workspace-இல் நிறுவும் ஒரு Slack app. உங்கள் Slack போக்குவரத்தை FreeITSM ஒருபோதும் பார்ப்பதில்லை — app நேரடியாக இந்தச் சேவையகத்துடன் பேசுகிறது.',
        'slack_col_channel' => 'கண்காணிப்பது',
        'slack_any_channel' => 'அழைக்கப்பட்ட எந்தச் சேனலும்',
        'slack_empty' => 'இன்னும் Slack workspaces இல்லை. ஒன்றைச் சேர்த்து, பிறகு Slack-இலிருந்து அதன் app-ஐ எடுத்துக்கொள்ளுங்கள்.',
        'slack_needs_setup' => 'அமைப்பு தேவை',
        'slack_add_title' => 'Slack workspace-ஐச் சேர்',
        'slack_edit_title' => 'Slack workspace-ஐத் திருத்து',
        'slack_name_hint' => 'இந்தப் பட்டியலிலும், நீங்கள் உருவாக்கும் Slack app-இன் பெயராகவும் மட்டுமே பயன்படுத்தப்படும்.',
        'slack_name_required' => 'இந்த workspace-க்கு ஒரு பெயரை வழங்கவும்.',
        'slack_unchanged' => 'மாற்றப்படவில்லை — வைத்திருக்க வெறுமையாக விடவும்',
        'slack_bot_token' => 'Bot user OAuth token',
        'slack_bot_token_hint' => 'உங்கள் Slack app-இல், OAuth &amp; Permissions கீழ் இருக்கும். xoxb- என்று தொடங்கும். app-ஐ நிறுவிய பிறகே கிடைக்கும், எனவே முதல் சேமிப்பில் வெறுமையாக விடவும்.',
        'slack_signing_secret' => 'Signing secret',
        'slack_signing_secret_hint' => 'உங்கள் Slack app-இல், Basic Information கீழ் இருக்கும். ஒரு செய்தி உண்மையிலேயே Slack-இலிருந்து வந்தது என்பதை FreeITSM இதன் மூலமே உறுதி செய்கிறது; எனவே இது அமைக்கப்படும் வரை எதுவும் ஏற்கப்படாது.',
        'slack_watch_channel' => 'இந்தச் சேனலை மட்டும் கண்காணி',
        'slack_watch_channel_hint' => 'C08ABCDEF போன்ற Slack சேனல் ID. app அழைக்கப்பட்ட ஒவ்வொரு சேனலிலிருந்தும் டிக்கெட் எழுப்ப வெறுமையாக விடவும் — பரபரப்பான சேனலில் அது ஒவ்வொரு செய்திக்கும் ஒரு டிக்கெட் என்று பொருள், எனவே பெரும்பாலானோர் இங்கே ஒரு உதவிச் சேனலைக் குறிப்பிடுகிறார்கள்.',
        'slack_company_shared' => 'பகிரப்பட்டது — அனுப்புநரைப் பொறுத்து',
        'slack_company_hint' => 'இந்த workspace-ஐ ஒரு நிறுவனத்துடன் பிணைக்கவும், அல்லது பகிரப்பட்டதாக விட்டு அனுப்புநர் முடிவு செய்யட்டும்.',
        'slack_delete_confirm' => '“{name}” Slack workspace-ஐ நீக்கவா? அதிலிருந்து ஏற்கனவே எழுப்பப்பட்ட டிக்கெட்டுகள் தங்கள் வரலாற்றை வைத்திருக்கும்; புதிய செய்திகள் மட்டும் வருவது நிற்கும்.',
        'slack_diag_title' => 'Slack நலச் சோதனை',
        'slack_diag_desc' => 'அமைதியாகத் தவறாக இருக்கக்கூடிய அனைத்தையும் சரிபார்க்கிறது — token வேலை செய்கிறதா என்பதை மட்டுமல்ல. ஒவ்வொரு முடிவும் என்ன செய்ய வேண்டும் என்று கூறுகிறது.',
        'slack_diag_running' => 'சரிபார்க்கிறது — இது Slack-உடனும் உங்கள் சொந்தப் பொது முகவரியுடனும் பேசுகிறது, எனவே சில வினாடிகள் காத்திருக்கவும்…',
        'slack_diag_rerun' => 'மீண்டும் இயக்கு',
        'slack_diag_all_ok' => 'அனைத்தும் சரியாக உள்ளது. கண்காணிக்கப்படும் Slack சேனலில் இடப்படும் செய்திகள் டிக்கெட்டுகளாகும், பதில்கள் thread-க்குள் திரும்பச் செல்லும்.',
        'slack_diag_some_warn' => 'இயங்குகிறது, ஆனால் தெரிந்துகொள்ள வேண்டிய ஒன்று உள்ளது. கீழே உள்ள எதுவும் டிக்கெட்டுகள் வருவதைத் தடுக்காது, ஆனால் படிப்பது நல்லது.',
        'slack_diag_some_fail' => 'ஏதோ தவறாக உள்ளது, செய்திகள் வராது. தோல்வியடைந்த சரிபார்ப்புகள் என்ன செய்ய வேண்டும் என்று கீழே கூறுகின்றன.',
        'slack_app_title' => 'Slack app',
        'slack_copy_manifest' => 'manifest-ஐ நகலெடு',
        'slack_scopes_heading' => 'app என்ன செய்ய அனுமதிக்கப்படுகிறது',
        'slack_scopes_desc' => 'app-ஐ ஒப்புதல் அளிக்கும்போது உங்கள் Slack நிர்வாகி இந்தப் பட்டியலைப் பார்ப்பார். இங்குள்ள எதுவும் சேனல்களை உருவாக்கவோ, மக்களை அழைக்கவோ, அழைக்கப்படாத இடத்தில் இடுகையிடவோ அனுமதிக்காது.',
        'slack_step1' => 'Slack-இல் <strong>api.slack.com/apps</strong>-க்குச் சென்று <strong>Create New App → From a manifest</strong>-ஐத் தேர்ந்தெடுக்கவும். சேவை மையம் இருக்க வேண்டிய workspace-ஐத் தேர்வு செய்யவும்.',
        'slack_step2' => 'இந்த manifest-ஐ ஒட்டவும். இது பெயர், அனுமதிகள் மற்றும் Slack செய்திகளை அனுப்பும் முகவரியை அமைக்கிறது, எனவே கையால் தேர்வு செய்ய எதுவும் இல்லை.',
        'slack_step3' => '<strong>Install to Workspace</strong>-ஐக் கிளிக் செய்து ஒப்புதல் அளிக்கவும். பிறகு <strong>Bot User OAuth Token</strong> மற்றும் <strong>Signing Secret</strong>-ஐ இங்குள்ள திருத்தும் படிவத்தில் நகலெடுக்கவும் — Slack token-ஐ மீண்டும் காட்டாது. <strong>Slack மஞ்சள் &ldquo;Reinstall to Workspace&rdquo; பேனரைக் காட்டினால், முதலில் அதைக் கிளிக் செய்யவும்</strong> — இல்லையெனில் token-இல் பெரும்பாலான அனுமதிகள் இருக்காது, டிக்கெட்டுகள் அனுப்புநரின் பெயர் இல்லாமல் வரும்.',
        'slack_step4' => 'கீழே உள்ள request URL, <strong>Event Subscriptions</strong> கீழ் Slack காட்டுவதுடன் பொருந்துகிறதா என்று சரிபாருங்கள். app-ஐச் சேமிக்கும் நொடியிலேயே Slack அதைச் சரிபார்க்கும், எனவே இந்தச் சேவையகம் இணையத்திலிருந்து அடையக்கூடியதாக இருக்க வேண்டும்.',
        'slack_step5' => 'Slack-இல், app கண்காணிக்க வேண்டிய சேனலுக்கு அதை அழைக்கவும்: <strong>/invite @YourApp</strong>. அது இல்லாத சேனலை அதனால் படிக்க முடியாது.',
    ],
    'branding' => [
        'title' => 'பிராண்டிங்',
        'subtitle' => 'நிறுவன லோகோ, மக்கள் வந்து சேரும் பக்கம், வரைபடங்கள் மற்றும் ஏற்றுமதி ஆவணங்களில் பயன்படுத்தப்படும் இயல்புநிலை header/footer உரை ஆகியவற்றை அமைக்கவும்',
        'system_name_heading' => 'அமைப்பின் பெயர்',
        'back_link_heading' => 'உங்கள் தளத்துக்கான இணைப்பு',
        'back_link_desc' => 'திரையின் மேலே உங்கள் சொந்தத் தளத்துக்குத் திரும்பும் இணைப்பு - மக்கள் FreeITSM-க்கு வரும் இன்ட்ராநெட் அல்லது இணையதளம். இணைப்பு வேண்டாம் என்றால் இரண்டு பெட்டிகளையும் வெறுமையாக விடவும்.',
        'back_link_label' => 'இணைப்பு உரை',
        'back_link_label_ph' => 'இன்ட்ராநெட்டுக்குத் திரும்பு',
        'back_link_url' => 'முகவரி',
        'back_link_where' => 'எங்கே காட்டுவது',
        'back_link_where_portal' => 'சுய-சேவை போர்டல்',
