        'back_link_where_both' => 'இரண்டிலும்',
        'system_name_desc' => 'ஒவ்வொரு பக்கத் தலைப்பின் முதல் பகுதி - ஒவ்வொரு தொகுதியின் ஒவ்வொரு பக்கத்திலும் உலாவி tab-இலும் புக்மார்க்குகளிலும் தோன்றும் பெயர். "Service Desk" பயன்படுத்த வெறுமையாக விடவும்.',
        'landing_heading' => 'மக்கள் தொடங்கும் இடம்',
        'landing_desc' => 'உள்நுழையாமல் FreeITSM-ஐத் திறக்கும் ஒருவர் அனுப்பப்படும் இடம்.',
        'landing_analyst' => 'பகுப்பாய்வாளர் உள்நுழைவு',
        'landing_portal' => 'சுய-சேவை போர்டல்',
        'landing_note' => 'இரண்டு உள்நுழைவுப் பக்கங்களும் ஒன்றுக்கொன்று இணைக்கப்பட்டுள்ளன, எனவே நீங்கள் தேர்ந்தெடுக்காததிலிருந்து யாரும் பூட்டப்பட மாட்டார்கள். பகுப்பாய்வாளர்கள் விருப்பத்தேர்வுகளில் தங்களுக்காக இதை மாற்றிக்கொள்ளலாம்.',
        'files_heading' => 'Files டெஸ்க்டாப்',
