    'status_portal' => [
        'heading' => 'போர்டலில் சேவை நிலை',
        'intro' => 'எந்தெந்த சேவைகள் சீராக உள்ளன என்பதை இறுதிப் பயனர்கள் ஏற்கனவே சுய-சேவை போர்டலில் பார்க்கிறார்கள். செயலிழப்புக்குப் பின்னால் உள்ள <strong>சம்பவங்களையும்</strong>, உங்கள் குழு வெளிப்புறமாகக் குறித்த புதுப்பிப்புகளையும் அவர்கள் காணலாமா என்பதை இது தீர்மானிக்கிறது.',
        'warning' => '<strong>இதை இயக்கும் முன் இதைப் படியுங்கள்.</strong> சம்பவத் தலைப்புகள் உங்கள் குழுவுக்காக எழுதப்பட்டவை, வாடிக்கையாளர்களுக்காக அல்ல &mdash; இறுதிப் பயனர்கள் படிக்கத் தொடங்கும் முன் உங்கள் தலைப்புகள் என்ன சொல்கின்றன என்பதைச் சரிபாருங்கள். <strong>வெளிப்புறம்</strong> எனத் தெளிவாகக் குறிக்கப்பட்ட புதுப்பிப்புகள் மட்டுமே காட்டப்படும்; இந்த வசதி வருவதற்கு முன் எழுதப்பட்ட அனைத்தும் உள்ளகமானவை, அவை உள்ளகமாகவே இருக்கும்.',
        'panel_heading' => 'போர்டல் எதைக் காட்டுகிறது',
        'enable_label' => 'சம்பவங்களையும் அவற்றின் வெளிப்புறப் புதுப்பிப்புகளையும் சுய-சேவை போர்டலில் காட்டு',
        'enable_hint' => 'இயல்பாக முடக்கப்பட்டிருக்கும். இது முடக்கத்தில் இருக்கும்போது, போர்டல் முன்பு போலவே சேவை நிலையை மட்டுமே காட்டும்.',
        'mode_open' => 'இப்போது நடப்பவை மட்டும்',
        'mode_open_desc' => 'மிகவும் எளிமையான பக்கம். செயலிழப்பு தீர்க்கப்பட்ட உடனே மறைந்துவிடும், எனவே ஒரு மணி நேரத்துக்கு முன் பாதிக்கப்பட்டவருக்கு அது சரிசெய்யப்பட்டது என்ற உறுதிப்படுத்தல் கிடைக்காது.',
        'mode_recent' => 'இப்போது நடப்பவை, மேலும் கடந்த இவ்வளவு காலத்தில் தீர்க்கப்பட்டவை',
        'mode_recent_days' => 'நாட்கள்',
        'mode_recent_desc' => 'பரிந்துரைக்கப்படுவது. தீர்க்கப்பட்ட பதிவு நிலைப் பக்கத்தில் மிகவும் நம்பிக்கை தருவது, பெரும்பாலானோர் நிலைப் பக்கம் என்பதன் மூலம் எதிர்பார்ப்பதும் இதுவே.',
        'mode_all' => 'எல்லாமே, எப்போதும்',
        'mode_all_desc' => 'முழு வரலாறு, சுருக்கப்பட்ட நிலையில். மிகவும் வெளிப்படையானது, பொது நிலைப் பக்கத்துக்கு மிக நெருக்கமானது &mdash; ஆனால் அமைதியான போர்டலில் அது இனி பிரச்சனை இல்லாதவற்றின் நீண்ட பட்டியலாகிவிடும்.',
