    'portal_profile' => [
        'heading' => 'போர்டல் சுயவிவரம்',
        'intro' => 'சுய-சேவை போர்டலில் <strong>என் கணக்கு</strong> பகுதியில் மக்கள் தங்களைப் பற்றி எதை மாற்றலாம் என்பது. நீங்கள் தேர்வுசெய்யாமல் விடும் எதுவும் அவர்களுக்குக் காட்டப்படவே படாது.',
        'fields_heading' => 'மக்கள் எதை மாற்றலாம்',
        'fields_desc' => 'இவை போர்டலில் உள்நுழையும் அனைவருக்கும் பொருந்தும். டைரக்டரியிலிருந்து புதுப்பித்து வைக்கப்படும் ஒருவர், அந்த டைரக்டரிக்குச் சொந்தமான விவரத்தை மாற்ற முடியாது; கீழே உள்ள பகுதி அவர்களின் முகவரிப் புத்தகம் அந்த மாற்றத்தை ஏற்க அனுமதித்தால் மட்டுமே முடியும்.',
        'always' => 'எப்போதும்',
        'never' => 'ஒருபோதும் இல்லை',
        'f_preferred_name' => 'விருப்பப் பெயர்',
        'f_preferred_name_desc' => 'போர்டலும் உங்கள் மின்னஞ்சல்களும் அவர்களை எப்படி அழைக்கின்றன என்பது. எப்போதும் அவர்களின் தேர்வே.',
        'f_job_title' => 'பணிப் பதவி',
        'f_job_title_desc' => 'பதவி உயர்வுக்குப் பிறகு, யாரும் சர்வீஸ் டெஸ்க்கிடம் சொல்லாதபோது பயனுள்ளது.',
        'f_office' => 'அலுவலகம் அல்லது இடம்',
        'f_office_desc' => 'அவர்கள் அமரும் இடம். டிக்கெட்டில் உள்ள சொத்துத் தேர்வி இதன் மூலம் தேடுகிறது, இதை யாரும் கையால் நிரப்புவதில்லை.',
        'f_phone' => 'தொலைபேசி',
        'f_phone_desc' => 'சர்வீஸ் டெஸ்க் திரும்ப அழைக்கும் எண்.',
        'f_mobile' => 'மொபைல்',
        'f_mobile_desc' => 'அவர்கள் தங்கள் இருக்கையில் இல்லாதபோது திரும்ப அழைப்பதற்காக.',
        'f_department' => 'துறை',
        'f_department_desc' => 'உங்கள் குழு பராமரிக்கும் நிறுவன அமைப்பு சார்ந்த தகவல். அறிக்கைகளும் சொத்துத் தேடலும் மக்களை இதன்படி குழுவாக்குகின்றன.',
        'f_employee_id' => 'பணியாளர் ID',
        'f_employee_id_desc' => 'மற்றொரு அமைப்பில் அவர்கள் யார் என்பது பற்றிய ஒரு கூற்று - HR உடன் மக்களைப் பொருத்த பயன்படுத்தப்படும் விசை இதுவே.',
        'f_manager_id' => 'மேலாளர்',
        'f_manager_id_desc' => 'யாரும் தங்கள் சொந்த ஒப்புதல் அளிப்பவரைத் தேர்ந்தெடுக்க முடியக்கூடாது.',
        'f_email' => 'மின்னஞ்சல் முகவரி',
        'f_email_desc' => 'இதைக் கொண்டே அவர்கள் உள்நுழைகிறார்கள். இதை மாற்றுவது சர்வீஸ் டெஸ்க்கின் வேலை.',
        'directory_heading' => 'முகவரிப் புத்தகத்திலிருந்து வரும் நபர்கள்',
        'directory_desc' => 'CardDAV முகவரிப் புத்தகத்திலிருந்து இறக்குமதி செய்யப்பட்டவர்கள் பொதுவாக இங்கே இந்த விவரங்களை மாற்ற முடியாது, ஏனெனில் அடுத்த இறக்குமதி பழைய மதிப்பையே திருப்பிவிடும். LDAP அல்லது Active Directory-இலிருந்து இறக்குமதி செய்யப்பட்டவர்கள் ஒருபோதும் மாற்ற முடியாது: அந்த டைரக்டரிக்கே அவர்கள் சொந்தம்.',
        'ab_label' => 'இவற்றையும் மாற்ற அனுமதி, அவர்களின் மாற்றத்தை முகவரிப் புத்தகத்துக்கு அனுப்பு',
        'ab_desc' => 'இயல்பாக முடக்கப்பட்டிருக்கும். இது உங்கள் வாடிக்கையாளர்களை உங்கள் முகவரிப் புத்தகத்தில் எழுத அனுமதிக்கிறது, எனவே இது உங்கள் முடிவு. <strong>மாற்றங்களைத் திருப்பி எழுது</strong> இயக்கப்பட்ட முகவரிப் புத்தகங்களில் மட்டுமே எழுதப்படும். முகவரிப் புத்தகம் ஏற்றுக்கொண்ட பின்னரே அவர்களின் மாற்றம் சேமிக்கப்படும், ஒவ்வொரு எழுத்தும் முகவரிப் புத்தகத்தின் எழுத்துப் பதிவில் இருக்கும்.',
        'ab_none' => 'இந்த அமைப்பில் CardDAV முகவரிப் புத்தகங்கள் எதுவும் இல்லை, எனவே இது இன்னும் எதுவும் செய்யாது.',
        'ab_no_writeback' => 'எந்த முகவரிப் புத்தகத்திலும் மாற்றங்களைத் திருப்பி எழுது இயக்கப்படவில்லை, எனவே இது இன்னும் எதுவும் செய்யாது.',
        'ab_books' => 'பொருந்தும் இடங்கள்: {list}.',
        'ab_manage' => 'முகவரிப் புத்தகங்களை நிர்வகி',
        'ab_warn' => 'இந்த முகவரிப் புத்தகங்களில் உள்ள தங்கள் சொந்த அட்டையில் வாடிக்கையாளர்கள் தங்கள் பணிப் பதவி, அலுவலகம் மற்றும் எண்களை மாற்ற முடியும்.',
        'saved' => 'சேமிக்கப்பட்டது',
        'save_failed' => 'சேமிக்க முடியவில்லை',
        'load_failed' => 'தற்போதைய அமைப்புகளை ஏற்ற முடியவில்லை, எனவே படிவம் பூட்டப்பட்டுள்ளது.',
    ],
    'search' => [
        'heading' => 'தேடல்',
        'intro' => 'தேடல் இன்டெக்ஸில் உள்ளவை. இது தானாகவே புதுப்பித்துக்கொள்ளும், எனவே கீழே உள்ள தரவுத்தள அமைப்புகளை மாற்றிய பின், அல்லது இது சரியாக இல்லை என்று சந்தேகித்தால் மட்டுமே மீண்டும் உருவாக்க வேண்டும்.',
        'rebuild' => 'இன்டெக்ஸை மீண்டும் உருவாக்கு',
        'index_heading' => 'இன்டெக்ஸ்',
        'rows' => 'பதிவுகள்',
        'tickets' => 'டிக்கெட்டுகள் இன்டெக்ஸ் செய்யப்பட்டன',
        'articles' => 'கட்டுரைகள் இன்டெக்ஸ் செய்யப்பட்டன',
        'last_indexed' => 'கடைசியாகப் புதுப்பிக்கப்பட்டது',
