    'debug' => [
        'heading' => 'பிழைத்திருத்தக் கருவிகள்',
        'intro' => 'தனித்தனியாக இயங்கும் கண்டறிதல்களின் தொகுப்பு. ஏதாவது வேலை செய்யாதபோது, தொடர்புடைய கருவியை இயக்கி வெளியீட்டை ஆதரவுக்கு அனுப்பவும் — ஒவ்வொரு கண்டறிதலும் முன்னும் பின்னும் கேட்காமலே காரணத்தைக் கண்டறிய போதுமான சூழல் மற்றும் இயக்கநேர விவரங்களைச் சேகரிக்கிறது.',
        'how_label' => 'எப்படிப் பயன்படுத்துவது:',
        'how_text' => 'எந்தக் கண்டறிதலை இயக்க வேண்டும் என்பதை ஆதரவு உங்களுக்குச் சொல்லும் (எ.கா. "D001-ஐ இயக்குங்கள்"). {run} என்பதைக் கிளிக் செய்து, வெளியீடு தோன்றும் வரை காத்திருந்து, பிறகு {copy} என்பதைக் கிளிக் செய்து முழு அறிக்கையையும் உங்கள் பதிலில் ஒட்டவும். கண்டறிதல்கள் பெரும்பாலும் படிக்க-மட்டுமே — தரவுத்தளத்தில் எழுதுபவை அட்டையிலேயே அதைச் சொல்லும்.',
        'checks_label' => 'எதைச் சரிபார்க்கிறது',
