        'copy' => 'நகலெடு',
        'copied' => 'நகலெடுக்கப்பட்டது',
        'output_running' => 'கண்டறிதல் இயங்குகிறது…',
        'fetch_failed' => 'கண்டறிதலைப் பெற முடியவில்லை: {message}',
        'input_required' => 'இந்தக் கருவியை இயக்கும் முன் ஒரு மதிப்பை உள்ளிடவும்.',
        'search_placeholder' => 'பிழைத்திருத்தக் கருவிகளைத் தேடு…',
        'no_results' => 'உங்கள் தேடலுக்குப் பொருந்தும் பிழைத்திருத்தக் கருவிகள் இல்லை.',
