    'demo' => [
        'heading' => 'டெமோ தரவு',
        'subtitle' => 'உண்மைக்கு நெருக்கமான மாதிரித் தரவை தொகுதி வாரியாக இறக்குமதி செய்யவும். முதலில் Core-ஐ இறக்குமதி செய்து, பிறகு எந்தத் தொகுதிகளை நிரப்ப வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும்.',
        'warning_strong' => 'டெமோ தரவு FreeITSM-ஐ முயன்று பார்ப்பதற்கானது.',
        'warning_text' => 'ஒரு தொகுதியை இறக்குமதி செய்வது, அது கடந்த முறை உருவாக்கிய மாதிரிப் பதிவுகளை அகற்றி புதிய தொகுப்பைச் சேர்க்கும். உங்கள் சொந்தப் பதிவுகள் தொடப்படாது — இந்த இறக்குமதியாளர் உருவாக்கிய வரிசைகள் மட்டுமே அகற்றப்படும்.',
        'untagged_strong' => 'இந்த நிறுவலில் முந்தைய பதிப்பிலிருந்து டெமோ தரவு உள்ளது.',
        'untagged_text' => 'மாதிரி வரிசைகளுக்கு அடையாளமிடும் வசதி வருவதற்கு முன் இது இறக்குமதி செய்யப்பட்டது, எனவே இங்கிருந்து இதை அடையாளம் காணவோ அகற்றவோ முடியாது. மீண்டும் இறக்குமதி செய்தால் அதை மாற்றாமல் அதனுடன் இரண்டாவது நகலைச் சேர்க்கும். சுத்தமான தொகுப்பு வேண்டுமென்றால் முதலில் பழைய மாதிரிப் பதிவுகளைக் கையால் அகற்றவும்.',
        'tip_text_prefix' => 'இரண்டையும் இறக்குமதி செய்யவும்:',
        'tip_text_and' => 'மற்றும்',
        'tip_text_suffix' => 'நிறுவப்பட்ட மென்பொருளை கணினிகளுடன் இணைக்கும் கூடுதல் விருப்பத்தைத் திறக்க.',
        'tip_assets' => 'சொத்துகள்',
        'tip_software' => 'மென்பொருள்',
        'step1' => 'படி 1 — தேவையானது',
        'step2' => 'படி 2 — தொகுதிகளைத் தேர்ந்தெடுக்கவும்',
        'step3_cross' => 'படி 3 — தொகுதிகளுக்கிடையேயான தரவு',
        'step3_dashboards' => 'படி 3 — டாஷ்போர்டுகள்',
        'import' => 'இறக்குமதி',
        'importing' => 'இறக்குமதி செய்கிறது...',
        'imported_count' => '{total} இறக்குமதி செய்யப்பட்டன',
        'already_imported' => 'ஏற்கனவே இறக்குமதி செய்யப்பட்டது',
        'import_title' => 'டெமோ தரவை இறக்குமதி செய்',
        'import_confirm' => '{module} டெமோ தரவை இறக்குமதி செய்யவா? மாதிரிப் பதிவுகள் இந்த நிறுவலில் சேர்க்கப்படும். உங்கள் சொந்தப் பதிவுகள் பாதிக்கப்படாது.',
        'reimport_title' => 'டெமோ தரவை மாற்று',
        'reimport_confirm' => '{module} டெமோ தரவை மாற்றவா? கடந்த இறக்குமதியின் மாதிரிப் பதிவுகள் அகற்றப்பட்டு புதிய தொகுப்பு சேர்க்கப்படும். உங்கள் சொந்தப் பதிவுகள் பாதிக்கப்படாது.',
        'connection_failed' => 'இணைப்பு தோல்வியடைந்தது: {message}',
    ],
    'encryption' => [
        'title' => 'குறியாக்கம்',
        'subtitle' => 'ஓய்வில் உள்ள முக்கியத் தரவைப் பாதுகாக்கப் பயன்படும் குறியாக்க விசையை நிர்வகிக்கவும்',
        'checking' => 'குறியாக்க நிலையைச் சரிபார்க்கிறது...',
        'how_heading' => 'குறியாக்கம் எவ்வாறு செயல்படுகிறது',
        'how_point1' => 'API keys, vCenter சான்றுகள் மற்றும் அஞ்சல் பெட்டி இணைப்பு விவரங்கள் போன்ற தரவுத்தளத்தில் சேமிக்கப்படும் முக்கியத் தரவைப் பாதுகாக்க FreeITSM {strong} அங்கீகரிக்கப்பட்ட குறியாக்கத்தைப் பயன்படுத்துகிறது.',
        'how_point1_strong' => 'AES-256-GCM',
        'how_point2' => 'குறியாக்க விசை என்பது 64-எழுத்து ஹெக்ஸ் சரம் (256 பிட்கள்), உலாவி வழியாக அணுக முடியாதபடி {strong} ஒரு கோப்பில் சேமிக்கப்படுகிறது.',
        'how_point2_strong' => 'வெப் ரூட்டுக்கு வெளியே',
        'how_point3' => 'விசைக் கோப்பின் இடம்:',
        'how_point4' => 'தரவுத்தளத்தில் உள்ள குறியாக்கம் செய்யப்பட்ட மதிப்புகளுக்கு முன்னால் {enc} இருக்கும், அதைத் தொடர்ந்து base64-குறியாக்கப்பட்ட சைபர்டெக்ஸ்ட் இருக்கும். குறியாக்கம் செய்யப்படாத மதிப்புகள் அப்படியே விடப்படும், இது படிப்படியான இடமாற்றத்தை அனுமதிக்கிறது.',
        'backup_strong' => 'உங்கள் குறியாக்க விசையைக் காப்புப்பிரதி எடுங்கள்.',
        'backup_text' => 'விசை தொலைந்துவிட்டால், அதைக் கொண்டு குறியாக்கம் செய்யப்பட்ட எந்தத் தரவையும் மீட்க முடியாது. இந்தச் சர்வருக்கு வெளியே பாதுகாப்பான இடத்தில் ஒரு நகலை வைத்திருங்கள்.',
        'whats_heading' => 'எவை குறியாக்கம் செய்யப்படுகின்றன',
        'group_settings' => 'கணினி அமைப்புகள்',
        'group_mailbox' => 'அஞ்சல் பெட்டி இணைப்புகள்',
        'status_ok_title' => 'குறியாக்கம் அமைக்கப்பட்டுள்ளது',
        'status_ok_detail' => 'குறியாக்க விசை {path} இடத்தில் உள்ளது, செல்லுபடியாகும். முக்கியத் தரவு AES-256-GCM மூலம் ஓய்வில் குறியாக்கம் செய்யப்படுகிறது.',
        'status_invalid_title' => 'தவறான குறியாக்க விசை',
        'status_invalid_detail' => '{path} இடத்தில் விசைக் கோப்பு காணப்பட்டது, ஆனால் அது செல்லுபடியாகும் 64-எழுத்து ஹெக்ஸ் சரம் அல்ல. விசை சரியாக 64 ஹெக்சாடெசிமல் எழுத்துகளாக (256 பிட்கள்) இருக்க வேண்டும்.',
        'generate_valid' => 'செல்லுபடியாகும் விசையை உருவாக்கு',
        'status_missing_title' => 'குறியாக்க விசை கிடைக்கவில்லை',
        'status_missing_detail' => '{path} இடத்தில் குறியாக்க விசைக் கோப்பு இல்லை. விசை உருவாக்கப்படும் வரை முக்கியத் தரவைக் குறியாக்கம் செய்ய முடியாது. தானாக உருவாக்க கீழே உள்ள பொத்தானைக் கிளிக் செய்யவும்.',
        'generate' => 'குறியாக்க விசையை உருவாக்கு',
        'generating' => 'உருவாக்குகிறது...',
        'check_failed' => 'குறியாக்க நிலையைச் சரிபார்க்க முடியவில்லை',
        'error' => 'பிழை: {error}',
        'generate_failed' => 'விசையை உருவாக்க முடியவில்லை',
        'error_prefix' => 'பிழை: {message}',
    ],
    'docker' => [
        'title' => 'Docker',
        'subtitle' => 'Docker-இல் இயங்கும் FreeITSM-க்கு HTTPS-ஐ இயக்கவும்',
        'not_container' => 'இந்தப் பக்கம் Docker இமேஜில் இயங்கும் FreeITSM-க்கானது; இந்த நிறுவல் அப்படியில்லை. அதற்குப் பதிலாக உங்கள் வலை சேவையகத்தில் (Apache, IIS அல்லது nginx) HTTPS-ஐ அமைக்கவும்.',
        'no_openssl' => 'PHP-யின் openssl நீட்டிப்பு ஏற்றப்படவில்லை, எனவே சான்றிதழை உருவாக்க முடியாது.',
        'old_image_title' => 'இந்த கண்டெய்னர் HTTPS ஆதரவுக்கு முந்தைய பதிப்பு',
        'old_image_body' => 'முதலில் சமீபத்திய FreeITSM இமேஜுக்குப் புதுப்பித்து, பிறகு இந்தப் பக்கத்துக்குத் திரும்பவும். மூலக் குறியீட்டிலிருந்து உருவாக்கினால், FreeITSM கோப்புறையில் {cmd} ஐ இயக்கவும்.',
        'proxy_note' => 'இந்த கண்டெய்னர் ஒரு reverse proxy-க்குப் பின்னால் அமைக்கப்பட்டுள்ளது (TRUST_PROXY_HTTPS இயக்கத்தில் உள்ளது). HTTPS-ஐ பொதுவாக proxy கையாளும், எனவே இந்தப் பக்கம் உங்களுக்குத் தேவைப்படாமல் இருக்கலாம்.',
        'not_persisted_title' => 'முதலில் உங்கள் Docker அமைப்பில் ஒரு மாற்றம்',
        'not_persisted_body' => 'இந்த கண்டெய்னரில் சான்றிதழைப் பாதுகாப்பாக வைத்திருக்க இடமில்லை: அடுத்த புதுப்பிப்பு அதை நீக்கிவிடும். உங்கள் docker-compose.yml உள்ள கோப்புறையில், கீழே உள்ள உரையுடன் {file} என்ற கோப்பை உருவாக்கவும். அந்தக் கோப்பு ஏற்கனவே இருந்தால், இந்த வரிகளை அதில் சேர்க்கவும்.',
        'not_persisted_then' => 'பிறகு அதே கோப்புறையில் {cmd} ஐ இயக்கி, இந்தப் பக்கத்தை மீண்டும் ஏற்றவும்.',
        'status_off_title' => 'HTTPS அணைக்கப்பட்டுள்ளது',
        'status_off_body' => 'FreeITSM சாதாரண HTTP வழியாக மட்டுமே அணுகக்கூடியது. HTTPS-ஐ இயக்க கீழே ஒரு சான்றிதழை உருவாக்கவும்.',
        'status_on_title' => 'HTTPS இயக்கத்தில் உள்ளது',
        'status_on_body' => '{host}-க்கான சான்றிதழ் பயன்பாட்டில் உள்ளது; அது {date} வரை செல்லுபடியாகும்.',
        'status_broken_title' => 'சான்றிதழ் கோப்புகள் பொருந்தவில்லை',
        'status_broken_body' => 'வட்டில் உள்ள சான்றிதழும் அதன் விசையும் ஒன்றுக்கொன்று உரியவை அல்ல, எனவே கண்டெய்னர் சாதாரண HTTP-யிலேயே இருக்கிறது. புதிய ஜோடியை உருவாக்க கீழே உள்ள உருவாக்கு என்பதை அழுத்தவும்.',
        'status_restart_title' => 'முடிக்க கண்டெய்னரை மறுதொடக்கம் செய்யவும்',
        'status_restart_body' => '{host}-க்கான சான்றிதழ் தயாராக உள்ளது, ஆனால் கண்டெய்னர் இன்னும் அது இல்லாமல் இயங்குகிறது. உங்கள் docker-compose.yml உள்ள கோப்புறையில் {cmd} ஐ இயக்கவும்.',
        'form_heading' => 'சான்றிதழ்',
        'browsing_at' => 'நீங்கள் FreeITSM-ஐ {address} வழியாக அணுகுகிறீர்கள்.',
        'host_label' => 'மக்கள் தட்டச்சு செய்யும் பெயர்',
        'host_help' => 'எடுத்துக்காட்டு: freeitsm.internal. .internal என முடியும் பெயர் நிறுவன நெட்வொர்க்கினுள் பயன்படுத்த பாதுகாப்பானது. சில PC-கள் வேறு பயன்பாடுகளுக்காக ஒதுக்கி வைத்திருக்கும் .local ஐத் தவிர்க்கவும்.',
        'ip_label' => 'சேவையகத்தின் IP முகவரி',
        'ip_help' => 'Docker இயங்கும் கணினியின் முகவரி, PC-கள் பார்ப்பது போல. இந்தப் பக்கத்தை IP மூலம் அணுகினால் உங்கள் முகவரிப் பட்டியிலிருந்து நிரப்பப்படும். விருப்பத்தேர்வு, ஆனால் இது IP மூலமும் HTTPS வேலை செய்ய உதவும்.',
        'generate' => 'உருவாக்கு',
        'generating' => 'உருவாக்குகிறது...',
        'local_warning' => '.local என முடியும் பெயர்கள் நெட்வொர்க்கில் உள்ள பிற சாதனங்களுடன் முரண்படலாம். அதற்குப் பதிலாக .internal ஐப் பரிசீலிக்கவும்.',
        'confirm_new_ca' => 'பெயரை அல்லது IP-ஐ மாற்றினால் புதிய authority சான்றிதழ் உருவாகும். பழையதை நம்பிய ஒவ்வொரு PC-யிலும் புதியதை நிறுவ வேண்டும். தொடரவா?',
        'err_invalid_host' => 'இது சரியான பெயர் அல்ல. எழுத்துகள், எண்கள், ஹைபன்கள், புள்ளிகளை மட்டும் பயன்படுத்தவும், எடுத்துக்காட்டு: freeitsm.internal.',
        'err_invalid_ip' => 'இது சரியான IP முகவரி அல்ல.',
        'err_not_persisted' => 'முதலில் இந்தப் பக்கத்தின் மேலே உள்ள Docker மாற்றத்தைச் செய்யவும்.',
        'err_generic' => 'சான்றிதழை உருவாக்க முடியவில்லை: {error}',
        'steps_heading' => 'அடுத்து செய்ய வேண்டியவை',
        'step_dns_title' => 'பெயரை சேவையகத்துடன் இணைக்கவும்',
        'step_dns_body' => '{host} என்பது {ip} ஐக் குறிக்கிறது என்பதை PC-கள் அறிய வேண்டும். சிறந்த வழி உங்கள் நெட்வொர்க்கின் DNS சேவையகத்தில் ஒரு DNS பதிவு (Windows டொமைனில் DNS Manager-இல்; சிறிய நெட்வொர்க்கில் பெரும்பாலும் ரூட்டரில்):',
        'step_dns_record' => 'வகை A, பெயர் {host}, முகவரி {ip}',
        'step_dns_hosts' => 'DNS சேவையகம் இல்லையெனில், ஒவ்வொரு PC-யின் hosts கோப்பிலும் இந்த வரியைச் சேர்க்கவும் (Windows-இல் {path}, Mac-இல் {path_mac}):',
        'step_dns_no_ip' => 'உருவாக்க வேண்டிய சரியான பதிவைக் காண மேலே சேவையகத்தின் IP முகவரியை நிரப்பவும்.',
        'step_ca_title' => 'ஒவ்வொரு PC-யிலும் authority சான்றிதழை நிறுவவும்',
        'step_ca_body' => 'இது சான்றிதழை நம்பும்படி PC-களுக்குச் சொல்கிறது. ஒரு PC-க்கு ஒருமுறை மட்டும் செய்தால் போதும்; பெயரையோ IP-ஐயோ மாற்றினால் மட்டுமே மீண்டும் செய்ய வேண்டும்.',
        'download' => 'பதிவிறக்கு',
        'step_ca_windows' => 'Windows: கோப்பை இருமுறை கிளிக் செய்து, Install Certificate ஐத் தேர்ந்தெடுத்து, Local Machine ஐ எடுத்து, Place all certificates in the following store ஐத் தேர்ந்தெடுத்து, Trusted Root Certification Authorities ஐத் தேர்வு செய்யவும்.',
        'step_ca_gpo' => 'டொமைனில் உள்ள பல Windows PC-கள்: கோப்பை Group Policy-இல் ஒருமுறை இறக்குமதி செய்யவும், Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities என்பதன் கீழ். Intune இதை Trusted certificate profile ஆக அனுப்ப முடியும்.',
        'step_ca_mac' => 'Mac: கோப்பை இருமுறை கிளிக் செய்து Keychain Access-இல் சேர்த்து, அங்கே திறந்து, When using this certificate என்பதை Always Trust என அமைக்கவும்.',
        'step_ca_firefox' => 'Windows-இல் Firefox, Windows சான்றிதழ்களைத் தானாகப் பயன்படுத்துகிறது. அப்போதும் எச்சரித்தால், about:config-இல் security.enterprise_roots.enabled ஐ true என அமைக்கவும்.',
        'step_ca_safe' => 'இந்த authority {host}-க்கு மட்டுமே உறுதியளிக்க முடியும், வேறு எதற்கும் அல்ல, எனவே இதை நிறுவுவதால் அது வேறு எந்த இணையதளத்தையும் போலியாகக் காட்ட முடியாது.',
        'step_restart_title' => 'கண்டெய்னரை மறுதொடக்கம் செய்யவும்',
        'step_restart_body' => 'உங்கள் docker-compose.yml உள்ள கோப்புறையில் {cmd} ஐ இயக்கவும்.',
        'step_restart_done' => 'முடிந்தது: கண்டெய்னர் இந்தச் சான்றிதழைப் பயன்படுத்துகிறது.',
        'step_open_title' => 'FreeITSM-ஐ HTTPS வழியாகத் திறக்கவும்',
        'step_open_body' => '{url} க்குச் செல்லவும். ஏற்றப்படவில்லை என்றால், உங்கள் docker-compose.yml போர்ட் 443-ஐ வெளியிடுகிறதா எனச் சரிபார்க்கவும் (நிலையான கோப்பு அதை 8443-க்கு இணைக்கிறது). அதை மாற்றியிருந்தால், உங்கள் போர்ட்டைப் பயன்படுத்தவும்.',
    ],
    'modules' => [
        'title' => 'தொகுதி அணுகல்',
        'subtitle' => 'முகப்புத் திரையிலும் வழிசெலுத்தலிலும் ஒவ்வொரு பகுப்பாய்வாளரும் எந்தத் தொகுதிகளைக் காணலாம் என்பதைக் கட்டுப்படுத்தவும்',
        'info_text' => 'இயல்பாக அனைத்து பகுப்பாய்வாளர்களுக்கும் ஒவ்வொரு தொகுதிக்கும் அணுகல் உண்டு. ஒரு பகுப்பாய்வாளரை குறிப்பிட்ட தொகுதிகளுக்கு மட்டுப்படுத்த {all_access} ஐ அணைக்கவும். System தொகுதியை முடக்க முடியாது.',
        'all_access_strong' => 'முழு அணுகல்',
        'loading' => 'பகுப்பாய்வாளர்கள் ஏற்றப்படுகிறார்கள்...',
        'empty_heading' => 'பகுப்பாய்வாளர்கள் எவரும் இல்லை',
        'empty_text' => 'முதலில் Tickets தொகுதி அமைப்புகளில் பகுப்பாய்வாளர்களைச் சேர்க்கவும்.',
        'col_analyst' => 'பகுப்பாய்வாளர்',
        'col_all_access' => 'முழு அணுகல்',
        'load_failed' => 'தரவை ஏற்ற முடியவில்லை',
        'save_failed' => 'சேமிக்க முடியவில்லை',
    ],
    'calsync' => [
        'title' => 'நாட்காட்டி ஒத்திசைவு',
        'subtitle' => 'பகுப்பாய்வாளர்களின் திட்டமிடப்பட்ட டிக்கெட்டுகளை அவர்கள் உண்மையில் பயன்படுத்தும் நாட்காட்டிகளில் வைக்கவும், சந்தா இணைப்பை வெளியிட அவர்களை அனுமதிக்கலாமா என்பதையும் தீர்மானிக்கவும்.',
        'needs_db' => 'முதலில் தரவுத்தளப் புதுப்பிப்பு தேவை',
        'needs_db_desc' => 'System → Database Verification ஐ இயக்கி, பிறகு இந்தப் பக்கத்துக்குத் திரும்பவும்.',
        'conn_heading' => 'இணைப்பு',
        'conns_heading' => 'இணைப்புகள்',
        'conns_desc' => 'பகுப்பாய்வாளர்களின் சொந்த நாட்காட்டிகளில் FreeITSM நிகழ்வுகளை எவ்வாறு எழுதுகிறது என்பது. தேவையான அளவு சேர்க்கலாம் - Microsoft 365, ஒன்று அல்லது அதற்கு மேற்பட்ட CalDAV சேவையகங்கள், அல்லது இரண்டும். ஒவ்வொரு பகுப்பாய்வாளரும் தங்கள் பணி எதற்குச் செல்லும் என்பதை <strong>விருப்பத்தேர்வுகள் &rarr; எனது பணி நாட்காட்டி</strong> என்பதன் கீழ் தேர்ந்தெடுக்கிறார்.',
        'conns_none' => 'இன்னும் இணைப்புகள் இல்லை. இணைப்பு இல்லாமலும் சந்தா இணைப்புகள் வேலை செய்யும்.',
        'conn_add' => 'சேர்',
        'conn_edit' => 'திருத்து',
        'conn_new' => 'புதிய இணைப்பு',
        'conn_editing' => '“{name}” ஐத் திருத்து',
        'conn_users' => '{n} பகுப்பாய்வாளர்(கள்) பயன்படுத்துகின்றனர்',
        'conn_borrowed' => 'ஒரு அஞ்சல் பெட்டியிலிருந்து app பதிவை இரவல் பெறுகிறது',
        'conn_own' => 'அதன் சொந்த app பதிவு',
        'conn_failing' => 'தோல்வியடைகிறது',
        'col_connection' => 'இணைப்பு',
        'col_calendar' => 'நாட்காட்டி',
        'not_chosen' => 'இன்னும் தேர்ந்தெடுக்கப்படவில்லை',
        'provider_label' => 'நாட்காட்டி அமைப்பு',
        'provider_microsoft' => 'Microsoft 365 / Exchange',
        'provider_caldav_short' => 'CalDAV',
        'provider_caldav' => 'ஒரு CalDAV சேவையகம் (Nextcloud, Baïkal, Radicale, iCloud, Fastmail…)',
        'caldav_desc' => 'FreeITSM ஒவ்வொரு பகுப்பாய்வாளரின் திட்டமிடப்பட்ட பணியையும் உங்கள் CalDAV சேவையகத்தில் ஒரு நாட்காட்டியில் எழுதுகிறது, <strong>அந்தப் பகுப்பாய்வாளராக உள்நுழைந்து</strong>. ஒரு கணக்கு அனைவரின் நாட்காட்டியிலும் எழுத CalDAV சேவையகத்தில் வழி இல்லை, எனவே இங்கே கடவுச்சொல் இல்லை: ஒவ்வொரு பகுப்பாய்வாளரும் உள்நுழைந்து <strong>விருப்பத்தேர்வுகள் &rarr; எனது பணி நாட்காட்டி</strong> என்பதன் கீழ் தங்கள் நாட்காட்டியைத் தேர்ந்தெடுக்கிறார்.',
        'server_url' => 'சேவையக முகவரி',
        'server_url_hint' => 'சேவையகத்தின் DAV முகவரி, அதன் வலைப்பக்கம் அல்ல. Baïkal: <code>https://server/dav.php/</code> &middot; Nextcloud: <code>https://server/remote.php/dav/</code> &middot; Radicale: <code>https://server/</code>. பகுப்பாய்வாளர்கள் இந்தச் சேவையகத்தில் உள்ள நாட்காட்டிகளை மட்டுமே தேர்ந்தெடுக்க முடியும்.',
        'caldav_auth' => 'உள்நுழைவு முறை',
        'auth_auto' => 'தானியங்கி (பரிந்துரைக்கப்படுகிறது)',
        'auth_digest' => 'Digest',
        'auth_basic' => 'Basic',
        'caldav_auth_hint' => 'வேறு காரணம் இல்லாவிட்டால் இதைத் தானியங்கி என்றே விடவும். நிலையான Baïkal Basic-ஐ அல்ல Digest-ஐ விரும்புகிறது; தானியங்கி என்பது சேவையகம் எதை வழங்குகிறது என்று அதனிடமே கேட்கிறது.',
        'caldav_probe' => 'ஒரு உள்நுழைவை முயற்சிக்கவும் (விருப்பத்தேர்வு, இந்தச் சோதனைக்கு மட்டும் பயன்படும், சேமிக்கப்படாது)',
        'probe_user' => 'பயனர்பெயர்',
        'probe_pass' => 'கடவுச்சொல்',
        'caldav_test_ok' => 'இணைக்கப்பட்டது. அந்த முகவரி ஒரு நாட்காட்டி சேவையகம்.',
        'caldav_test_failed_hint' => 'முகவரி சேவையகத்தின் DAV பாதையா (வலைப்பக்கம் அல்ல) என்பதையும், FreeITSM நெட்வொர்க் வழியாக அதை அடைய முடியுமா என்பதையும் சரிபார்க்கவும்.',
        'caldav_probe_ok' => '{user} உள்நுழைந்தார், இவற்றில் எழுத முடியும்: {list}.',
        'caldav_probe_none' => '{user} உள்நுழைந்தார், ஆனால் நிகழ்வுகளை வைத்திருக்கக்கூடிய நாட்காட்டி எதுவும் இல்லை.',
        'caldav_probe_bad' => '{user} ஆக உள்நுழைவது வேலை செய்யவில்லை: {error}',
        'caldav_probe_auth' => 'சேவையகம் {auth} அங்கீகாரத்தை வழங்கியது.',
        'caldav_no_notify' => 'CalDAV சேவையகங்கள் மாற்ற அறிவிப்புகளை அனுப்புவதில்லை, எனவே நாட்காட்டியில் செய்த மாற்றங்கள் திட்டமிடப்பட்ட பணி இயங்கும்போது வந்து சேரும்.',
        'people_desc_caldav' => 'ஒவ்வொரு பகுப்பாய்வாளரும் CalDAV சேவையகத்தில் உள்நுழைந்து விருப்பத்தேர்வுகளின் கீழ் தங்கள் சொந்த நாட்காட்டியைத் தேர்ந்தெடுக்கிறார். அதை அடையும் கடவுச்சொல் பகுப்பாய்வாளரிடம் மட்டுமே இருப்பதால், நிர்வாகியால் அவருக்காகத் தேர்ந்தெடுக்க முடியாது.',
        'no_account' => 'உள்நுழையவில்லை',
        'switch_title' => 'இந்த இணைப்பு எங்கே எழுதுகிறது என்பதை மாற்றவா?',
        'switch_confirm' => 'இது இந்த இணைப்பு பகுப்பாய்வாளர்களின் நாட்காட்டிகளில் வைத்த {mapped} நிகழ்வு(களை) திரும்பப் பெற்று, இதைப் பயன்படுத்தும் {pushing} பகுப்பாய்வாளர்(களுக்கு) நாட்காட்டி ஒத்திசைவை அணைக்கும்; ஒவ்வொருவரும் மீண்டும் அமைத்துக்கொள்ளலாம். பிற இணைப்புகளில் உள்ள பகுப்பாய்வாளர்களும் சந்தா இணைப்புகளும் பாதிக்கப்படாது.',
        'switch_ok' => 'மாற்று',
        'switch_done' => 'சேமிக்கப்பட்டது. இந்த இணைப்பில் உள்ள பகுப்பாய்வாளர்களுக்கு நாட்காட்டி ஒத்திசைவு மீட்டமைக்கப்பட்டது.',
        'perm_title' => 'இது வேலை செய்வதற்கு முன்',
        'perm_body' => 'app பதிவுக்கு <strong>Calendars.ReadWrite</strong> என்பது <strong>Application</strong> அனுமதியாக (Delegated அல்ல — Azure-இல் அவை தனித்தனிப் பட்டியல்கள்) நிர்வாகி ஒப்புதலுடன் தேவை. இந்த அனுமதி FreeITSM-ஐ <strong>tenant-இல் உள்ள ஒவ்வொரு அஞ்சல் பெட்டியிலும்</strong> எழுத அனுமதிக்கிறது என்பதை நினைவில் கொள்ளவும். அது நீங்கள் வழங்க விரும்பியதை விட அதிகம் என்றால், Exchange Online-இல் Application Access Policy மூலம் உங்கள் பகுப்பாய்வாளர்களின் mail-enabled security group-க்கு app-ஐ வரம்புக்குட்படுத்தவும்.',
        'name' => 'பெயர்',
        'source_mailbox' => 'ஒரு அஞ்சல் பெட்டியிலிருந்து நற்சான்றுகளை இரவல் பெறு',
        'source_own' => 'நற்சான்றுகளை உள்ளிடு',
        'mailbox' => 'அஞ்சல் பெட்டி',
        'no_mailboxes' => 'இந்த அமைப்பில் எந்த Microsoft அஞ்சல் பெட்டியிலும் இரவல் பெறக்கூடிய Azure நற்சான்றுகள் இல்லை, எனவே அவற்றைக் கீழே உள்ளிடவும். உங்கள் பகுப்பாய்வாளர்களின் நாட்காட்டிகள் உங்கள் வரவு அஞ்சல் பெட்டிகளிலிருந்து வேறு tenant-இல் இருந்தால், அல்லது உங்கள் வரவு Microsoft அல்லாததாக இருந்தால் இது இயல்பானதே.',
        'tenant_id' => 'Directory (tenant) ID',
        'client_id' => 'Application (client) ID',
        'client_secret' => 'Client secret',
        'secret_note' => 'ரகசியம் குறியாக்கம் செய்து சேமிக்கப்படும், மீண்டும் காட்டப்படாது. ஏற்கனவே சேமித்ததை வைத்திருக்க, திருத்தும்போது இதை வெறுமையாக விடவும்.',
        'test' => 'சோதி',
        'testing' => 'சோதிக்கிறது…',
        'probe' => 'இந்த அஞ்சல் பெட்டியை அடைய முடியுமா எனவும் சரிபார் (விருப்பத்தேர்வு)',
        'saved' => 'சேமிக்கப்பட்டது',
        'last_error' => 'கடைசி முயற்சி இதனுடன் தோல்வியடைந்தது:',
        'test_ok' => 'இணைக்கப்பட்டது. நற்சான்றுகள் வேலை செய்கின்றன, அனுமதியும் வழங்கப்பட்டுள்ளது.',
        'test_borrowed' => '“{name}” அஞ்சல் பெட்டியின் app பதிவு பயன்படுத்தப்படுகிறது.',
        'test_failed' => 'இணைக்க முடியவில்லை.',
        'test_failed_hint' => 'client secret காலாவதியாகவில்லை என்பதையும், Calendars.ReadWrite நிர்வாகி ஒப்புதலுடன் Application permissions-இன் கீழ் பட்டியலிடப்பட்டுள்ளது என்பதையும் சரிபார்க்கவும்.',
        'probe_ok' => '{addr}-இல் FreeITSM எழுதக்கூடிய நாட்காட்டி உள்ளது.',
        'probe_bad' => '{addr}-க்கு நாட்காட்டி கிடைக்கவில்லை. இந்த tenant-இல் அது உண்மையான அஞ்சல் பெட்டி முகவரியா எனச் சரிபார்க்கவும் — பகுப்பாய்வாளரின் FreeITSM மின்னஞ்சல் முகவரி எப்போதும் அவர் அஞ்சல் பெட்டி முகவரியாக இருக்காது.',
        'conn_delete_confirm' => '“{name}” ஐ நீக்கவா?',
        'conn_delete_title' => 'இந்த இணைப்பை நீக்கவா?',
        'conn_delete_used' => 'இந்த இணைப்பு பகுப்பாய்வாளர்களின் நாட்காட்டிகளில் வைத்த {mapped} நிகழ்வு(களை) FreeITSM திரும்பப் பெற்று, இதைப் பயன்படுத்தும் {pushing} பகுப்பாய்வாளர்(களுக்கு) நாட்காட்டி ஒத்திசைவை அணைக்கும். பிற இணைப்புகளில் உள்ள பகுப்பாய்வாளர்கள் பாதிக்கப்படாது.',
        'conn_deleted' => 'இணைப்பு நீக்கப்பட்டது',
        'people_heading' => 'ஒவ்வொரு பகுப்பாய்வாளரும் எந்த அஞ்சல் பெட்டிக்கு ஒத்திசைக்கிறார்',
        'people_desc' => 'இயல்பாக FreeITSM பகுப்பாய்வாளரின் கணக்கில் உள்ள மின்னஞ்சல் முகவரியைப் பயன்படுத்துகிறது; அது பெரும்பாலும் அவர்களின் அஞ்சல் பெட்டி அல்ல &mdash; உள்ளூர் கணக்கு, அல்லது வேறொன்றை அடிப்படையாகக் கொண்ட directory இறக்குமதி. அதை இங்கே மாற்றவும். தங்கள் பணி ஒத்திசைக்கப்படுமா <em>இல்லையா</em> என்பதைப் பகுப்பாய்வாளர்கள் தேர்ந்தெடுக்கிறார்கள்; அது <em>எங்கே</em> செல்கிறது என்பதை நிர்வாகி மட்டுமே தேர்ந்தெடுக்கிறார்.',
        'col_analyst' => 'பகுப்பாய்வாளர்',
        'col_status' => 'பகுப்பாய்வாளர் தேர்ந்தெடுத்தது',
        'check_save' => 'சரிபார்த்துச் சேமி',
        'mode_off' => 'அணைப்பு',
        'mode_push' => 'ஒத்திசைகிறது',
        'mode_feed' => 'சந்தா செலுத்தியது',
        'mode_error' => 'கடைசி ஒத்திசைவு தோல்வி',
        'tasks_work' => 'பணிகள்: திட்டமிடப்பட்டவை',
        'tasks_due' => 'பணிகள்: காலக்கெடு தேதிகள்',
        'tasks_both' => 'பணிகள்: இரண்டும்',
        'tasks_note' => 'இந்தப் பகுப்பாய்வாளர் தங்கள் பணிகளைச் சேர்க்கத் தேர்ந்தெடுத்துள்ளார். இதை அவர்கள் விருப்பத்தேர்வுகளின் கீழ் தாங்களே தேர்ந்தெடுக்கிறார்கள்; இங்கே அவர்களுக்காக அமைக்க முடியாது.',
        'saved_unverified' => 'சேமிக்கப்பட்டது. இணைப்பு வேலை செய்யாததால் முகவரியைச் சரிபார்க்க முடியவில்லை — மேலே சோதித்துப் பார்க்கவும்.',
        'inbound_heading' => 'நாட்காட்டியில் செய்த மாற்றங்கள்',
        'inbound_desc' => 'இந்த சந்திப்புகளில் ஒன்றை Outlook-இல் நகர்த்தினால் டிக்கெட்டும் அதைப் பின்தொடரும். இதற்கு <code>cron/calendar_sync_pull.php</code> பணி இயங்க வேண்டும் &mdash; ஒவ்வொரு 5 நிமிடமும் பொருத்தமானது. அது இல்லாவிட்டால் ஒத்திசைவு ஒரு வழிதான், இன்றும் அப்படித்தான் செயல்படுகிறது.',
        'accept_deletes' => 'சந்திப்பை நீக்குவது டிக்கெட்டின் திட்டமிடலை நீக்கும்',
        'notify_url' => 'அறிவிப்பு URL (விருப்பத்தேர்வு)',
        'notify_url_note' => 'திட்டமிடப்பட்ட சரிபார்ப்பை மட்டும் நம்ப வெறுமையாக விடவும், அதுவே முழுமையாகப் போதுமானது &mdash; மாற்றங்கள் சில நிமிடங்களுக்குள் வந்துவிடும். இதை நிரப்பினால், ஏதாவது மாறும் கணத்தில் Microsoft FreeITSM-க்குத் தெரிவிக்கும், எனவே அது சில நொடிகளில் வந்துவிடும். இது <strong>இணையத்திலிருந்து Microsoft அடையக்கூடிய HTTPS முகவரி</strong> ஆக இருக்க வேண்டும், <code>/api/calendar/graph_notify.php</code> என முடிய வேண்டும். எப்படியிருந்தாலும் திட்டமிடப்பட்ட பணி இன்னும் தேவை: அது சந்தாக்களைப் புதுப்பிக்கிறது, தவறிய அறிவிப்பால் இழக்கப்படக்கூடியவற்றையும் பிடிக்கிறது.',
        'notify_suggest' => 'இந்த முகவரியைப் பயன்படுத்து',
        'notify_suggest_note' => 'நீங்கள் இப்போது பயன்படுத்தும் முகவரியிலிருந்து நிரப்பப்பட்டது. அது வெளியிலிருந்து அடையக்கூடியதா எனச் சரிபார்க்கவும் — proxy அல்லது tunnel-க்குப் பின்னால் பெரும்பாலும் அடைய முடியாது, தவறான முகவரி முகவரியைப் பற்றியல்ல, சரிபார்ப்பைப் பற்றிய செய்தியுடன் தோல்வியடையும்.',
        'notify_saved' => 'திட்டமிடப்பட்ட பணி தனது அடுத்த இயக்கத்தில் சந்தாக்களை உருவாக்கும் அல்லது புதுப்பிக்கும்.',
        'notify_active' => '{n} சந்தா(க்கள்) செயலில்',
        'health_checked' => 'நாட்காட்டிகள் கடைசியாகச் சரிபார்க்கப்பட்டது {n} முன்பு.',
        'health_never' => 'நாட்காட்டிகள் இதுவரை சரிபார்க்கப்படவில்லை.',
        'health_stale_note' => 'Outlook-இல் செய்த மாற்றங்கள் திட்டமிடப்பட்ட பணி இயங்கும்போது வருகின்றன, எனவே இது பொதுவாக அது நின்றுவிட்டது எனப் பொருள் &mdash; <code>cron/calendar_sync_pull.php</code> தனது அட்டவணையில் இன்னும் இயங்குகிறதா எனச் சரிபார்க்கவும். அதுவே சந்தாக்களையும் புதுப்பிக்கிறது, எனவே அது நின்ற சில நாட்களில் அறிவிப்புகளும் நின்றுவிடும். அதை ஒவ்வொரு அரை மணி நேரத்தை விடக் குறைவாக வேண்டுமென்றே இயக்கினால், இது எதிர்பார்க்கப்படும் ஒன்றே.',
        'health_subs' => 'அறிவிப்புகள்: {total}-இல் {n} சந்தா செலுத்தியுள்ளன.',
        'health_just_now' => 'ஒரு நிமிடத்துக்கும் குறைவு',
        'health_mins' => '{n} நிமிடம்',
        'health_hours' => '{n} மணி நேரம்',
        'health_days' => '{n} நாள்',
        'sub_ok' => 'அறிவிக்கப்படுகிறது',
        'sub_expires' => 'சந்தா {n}-க்குள் புதுப்பிக்கப்படும்',
        'sub_none' => 'சந்தா இல்லை',
        'sub_none_note' => 'அறிவிப்பு முகவரி அமைக்கப்பட்டுள்ளது, ஆனால் இந்த நபருக்கு Microsoft அழைக்க எதுவும் இல்லை, எனவே அவர்களின் மாற்றங்கள் திட்டமிடப்பட்ட பணி இயங்கும்போது மட்டுமே வரும். அடுத்த இயக்கம் அதை உருவாக்க முயலும்; தொடர்ந்து தோல்வியடைந்தால் காரணம் இங்கே தோன்றும்.',
        'sub_lapsed' => 'சந்தா காலாவதியானது',
        'accept_deletes_note' => 'இயல்பாக அணைந்துள்ளது. இயக்கினால், ஒரு பகுப்பாய்வாளர் இவற்றில் ஒன்றைத் தன் தொலைபேசியில் நீக்கும்போது, அவர் அமரும்போது டிக்கெட்டின் திட்டமிடல் ஏற்கனவே நீக்கப்பட்டிருக்கும் &mdash; அதுவே பெரும்பாலும் நோக்கம். அத்தகைய ஒவ்வொரு மாற்றமும் டிக்கெட்டின் வரலாற்றில் எழுதப்படும், ஒரே நேரத்தில் வழக்கத்துக்கு மாறாக அதிக நீக்கங்கள் வந்தால் அவை கட்டளை என்பதை விட பிழையாக இருக்கவே வாய்ப்பு அதிகம் என்பதால் ஏற்கப்படாமல் மறுக்கப்படும். அணைந்திருந்தால், நீக்கப்பட்ட சந்திப்பு டிக்கெட் அடுத்து மாறும்போது மீண்டும் தோன்றும்.',
        'feed_heading' => 'சந்தா இணைப்புகள்',
        'feed_desc' => 'பகுப்பாய்வாளர்கள் தங்கள் திட்டமிடப்பட்ட பணியை எந்த நாட்காட்டி செயலியிலும் வேலை செய்யும் நாட்காட்டி சந்தா இணைப்பாக வெளியிடலாம். இணைப்பு என்பது உள்நுழைவு அல்ல, ஒரு ரகசிய URL, எனவே அதை வைத்திருக்கும் எவரும் அது காட்டுவதைப் படிக்கலாம்.',
        'feed_label' => 'சந்தா இணைப்புகளை அனுமதி',
        'feed_full' => 'ஆம் — டிக்கெட் பொருட்கள் உட்பட',
        'feed_ref' => 'ஆம் — ஆனால் டிக்கெட் எண்கள் மட்டும், பொருட்கள் இல்லை',
        'feed_off' => 'இல்லை',
        'feed_note' => 'பகுப்பாய்வாளர்கள் இதைவிடக் குறைவாக வெளியிடத் தேர்ந்தெடுக்கலாம், ஒருபோதும் அதிகமாக அல்ல. இதை அணைத்தால் ஏற்கனவே வழங்கப்பட்ட இணைப்புகள் உடனடியாக நின்றுவிடும்.',
    ],
    'preferences' => [
        'title' => 'விருப்பத்தேர்வுகள்',
        'subtitle' => 'உங்கள் கணக்கில் சேமிக்கப்படும் தனிப்பட்ட அமைப்புகள் — அவை எல்லா உலாவிகளிலும் உங்களைப் பின்தொடரும்.',
        'tab_general' => 'பொது',
        'tab_notifications' => 'அறிவிப்புகள்',
        'tab_display' => 'காட்சி',
        'tab_details' => 'என் விவரங்கள்',
        'language_heading' => 'இடைமுக மொழி',
        'language_desc' => 'FreeITSM இடைமுகம் முழுவதும் பயன்படுத்தப்படும் மொழி. நீங்கள் தேர்ந்தெடுத்த மொழியில் இன்னும் மொழிபெயர்க்கப்படாத சரங்கள் ஆங்கிலத்திலேயே காட்டப்படும். மாற்றும்போது பக்கம் மீண்டும் ஏற்றப்படும்.',
        'saving' => 'சேமிக்கிறது…',
        'notif_heading' => 'மணியில்',
        'notif_desc' => 'இவற்றில் எவை திரையின் மேலே உள்ள மணியில் ஏதாவது சேர்க்கும். உங்கள் சொந்த செயல்களுக்கு உங்களுக்கு ஒருபோதும் அறிவிப்பு வராது, ஒரே டிக்கெட்டில் ஏற்படும் பல மாற்றங்கள் ஒன்றாகத் தொகுக்கப்படும்.',
        'sound_heading' => 'அறிவிப்பு ஒலி',
        'sound_desc' => 'மணியில் புதிதாக ஏதாவது வரும்போது, அல்லது வார் ரூமில் யாரேனும் உங்களைக் குறிப்பிடும்போது ஒரு சிறிய ஒலியை இயக்கும். நீங்கள் ஒலியைத் தேர்ந்தெடுக்கும் வரை முடக்கத்தில் இருக்கும்.',
        'sound_off' => 'ஒலி இல்லை',
        'sound_chime' => 'சைம்',
        'sound_ping' => 'பிங்',
        'sound_knock' => 'நாக்',
        'sound_play' => 'இயக்கு',
        'sound_note' => 'பக்கத்தில் எங்காவது கிளிக் செய்யும் வரை உங்கள் உலாவி ஒலியை இயக்காது, எனவே ஒரு டேப்பைத் திறந்த பிறகு வரும் முதல் அறிவிப்பு ஒலியின்றி இருக்கலாம். டேப்பைத் திறக்கும்போது ஏற்கனவே காத்திருந்த அறிவிப்புகளுக்கு எந்த ஒலியும் கேட்காது.',
        'cal_subtasks_heading' => 'பணி நாட்காட்டியில் துணைப் பணிகள்',
        'cal_subtasks_desc' => 'நாட்காட்டி பணிகளுடன் சேர்த்து துணைப் பணிகளையும் காட்டுமா என்பது. நாட்காட்டியின் பக்கப்பட்டியிலும் இதே கட்டுப்பாடு உள்ளது, இரண்டும் ஒத்திசைவில் இருக்கும்.',
        'task_view_heading' => 'பணியைத் திறத்தல்',
        'task_view_desc' => 'பணி பலகையின் பக்கத்தில் உள்ள பலகத்தில் திறக்க வேண்டுமா, அல்லது விளக்கம் மற்றும் கருத்துகளுக்கு இடமுள்ள பெரிய சாளரத்தில் திறக்க வேண்டுமா என்பது.',
        'task_view_panel' => 'பக்கப் பலகத்தில்',
        'task_view_modal' => 'பெரிய சாளரத்தில்',
        'desktop_heading' => 'டெஸ்க்டாப் அறிவிப்புகள்',
        'desktop_desc' => 'மணியிலிருந்து வரும் ஒவ்வொரு புதிய அறிவிப்பையும் உங்கள் கணினியில் ஒரு அறிவிப்பாகக் காட்டும் - Windows இல் Edge-இல் இது Windows அறிவிப்பாக வரும் - இதனால் வேறொரு சாளரத்தில் வேலை செய்யும்போதும் நீங்கள் அதைப் பார்க்கலாம். இவை வருவதற்கு FreeITSM ஒரு உலாவி டேப்பில் திறந்திருக்க வேண்டும்.',
        'desktop_label' => 'டெஸ்க்டாப் அறிவிப்புகளைக் காட்டு',
        'desktop_test' => 'சோதி',
        'desktop_test_title' => 'டெஸ்க்டாப் அறிவிப்புகள் இயக்கத்தில் உள்ளன',
        'desktop_test_body' => 'மணியிலிருந்து வரும் புதிய அறிவிப்புகள் இவ்வாறு தோன்றும்.',
        'desktop_ask' => 'இதை இயக்கும்போது, இந்தத் தளத்திலிருந்து அறிவிப்புகளை அனுமதிக்கலாமா என்று உங்கள் உலாவி கேட்கும்.',
        'desktop_allowed' => 'இந்தத் தளத்திலிருந்து அறிவிப்புகளை உங்கள் உலாவி அனுமதிக்கிறது.',
        'desktop_blocked' => 'இந்தத் தளத்திலிருந்து அறிவிப்புகளை உங்கள் உலாவி தடுக்கிறது. உலாவியின் தள அமைப்புகளில் (முகவரிக்கு அருகிலுள்ள பூட்டு குறி) அவற்றை அனுமதித்து, பின்னர் இதை இயக்கவும்.',
        'desktop_unsupported' => 'இந்த உலாவியால் டெஸ்க்டாப் அறிவிப்புகளைக் காட்ட முடியாது.',
        'desktop_insecure' => 'https வழியாகத் திறக்கப்பட்ட தளத்தில் மட்டுமே உலாவிகள் டெஸ்க்டாப் அறிவிப்புகளை அனுமதிக்கின்றன.',
        'task_email_heading' => 'உங்களுக்கு ஒதுக்கப்பட்ட பணிகள்',
        'task_email_desc' => 'உங்களுக்கு ஒரு பணி ஒதுக்கப்படும் போதெல்லாம் மின்னஞ்சல் பெறுங்கள் - உங்களுக்காக ஒன்று உருவாக்கப்படும்போது, அல்லது வேறொருவரிடமிருந்து உங்களுக்குக் கொடுக்கப்படும்போது. நீங்களே உங்களுக்கு ஒதுக்கும் பணிக்கு எதுவும் அனுப்பப்படாது.',
        'task_email_label' => 'எனக்கு ஒரு பணி ஒதுக்கப்படும்போது மின்னஞ்சல் அனுப்பு',
        'board_subtasks_heading' => 'பணி பலகையில் துணைப் பணிகள்',
        'board_subtasks_desc' => 'துணைப் பணிகள் உள்ள பணி, பலகையில் அதன் அட்டைக்குக் கீழே அவற்றைப் பட்டியலிடும். எவற்றைக் காட்டுவது என்பதைத் தேர்ந்தெடுக்கவும் - அட்டை எப்போதும் எண்ணிக்கையைக் காட்டும், எண்ணிக்கையைக் கிளிக் செய்தால் அந்த ஒரு அட்டையின் பட்டியல் காட்டப்படும் அல்லது மறைக்கப்படும். இதே தேர்வு பணிகள் பக்கப்பட்டியிலும் உள்ளது.',
        'board_subtasks_label' => 'அனைத்தும் முடிந்ததும் மறை',
        'board_subtasks_all' => 'அனைத்து துணைப் பணிகள்',
        'board_subtasks_open' => 'இன்னும் செய்ய வேண்டியவை மட்டும்',
        'board_subtasks_none' => 'எதுவுமில்லை - எண்ணிக்கை மட்டும்',
        'search_dismiss_heading' => 'தேடல் பலகத்தை மூடுதல்',
        'search_dismiss_desc' => 'தேடல் பலகத்தை வழியிலிருந்து இழுத்து திறந்தே விடலாம், எனவே இயல்பாக அதன் ✕ அல்லது Escape விசை மட்டுமே அதை மூடும். நீங்கள் வேறு இடத்தில் கிளிக் செய்தவுடன் - கோப்புறைப் பட்டியல், டிக்கெட் பட்டியல் அல்லது கருவிப்பட்டியில் - அது மூட வேண்டுமெனில் இதை இயக்கவும். நீங்கள் இப்போது கண்டறிந்த டிக்கெட்டையோ அதன் பண்புகளையோ கிளிக் செய்தால் பலகம் திறந்தே இருக்கும், இதனால் தேடல் முடிவின் மீது நீங்கள் செயல்படும்போதும் தேடல் நிலைத்திருக்கும்.',
        'search_dismiss_label' => 'நான் வேறிடத்தில் கிளிக் செய்தால் மூடு',
        'landing_heading' => 'தொடக்கப் பக்கம்',
        'workcal_heading' => 'என் பணி நாட்காட்டி',
        'taskcal_heading' => 'இந்த நாட்காட்டியில் பணிகள்',
        'taskcal_off' => 'எதுவுமில்லை',
        'taskcal_work' => 'நான் செய்யத் திட்டமிடும்போது',
        'taskcal_due' => 'காலக்கெடு வரும்போது',
        'taskcal_both' => 'இரண்டும்',
        'taskcal_note' => 'ஒரு பணி உங்கள் நாட்காட்டியில் இரண்டு விஷயங்களைச் சேர்க்கலாம்: அதைச் செய்ய நீங்கள் ஒதுக்கிய நேரத்தை ஒரு சாதாரண சந்திப்பாகவும், அதன் காலக்கெடு தேதியை நாள் முழுவதுக்குமான பதிவாகவும். முடிக்கப்பட்ட பணிகள் நீக்கப்படும், உங்களுக்கு அல்லாமல் ஒரு குழுவுக்கு ஒதுக்கப்பட்ட பணி ஒருபோதும் சேர்க்கப்படாது.',
        'taskcal_failed' => 'அந்தத் தேர்வைச் சேமிக்க முடியவில்லை',
        'workcal_desc' => 'நீங்கள் திட்டமிட்ட டிக்கெட்டுகளை நீங்கள் உண்மையில் பயன்படுத்தும் நாட்காட்டியில் சேர்க்கவும் — Google, Apple, Outlook அல்லது நாட்காட்டியைச் சந்தா செலுத்தக்கூடிய வேறு எதுவும்.',
        'workcal_off' => 'முடக்கம்',
        'workcal_feed' => 'சந்தா இணைப்பு',
        'workcal_push' => 'என் நாட்காட்டியில் சேர்',
        'workcal_push_none' => 'டிக்கெட்டுகளை நேரடியாக உங்கள் நாட்காட்டியில் சேர்ப்பது கிடைக்கவில்லை: இந்த அமைப்பில் நிர்வாகி இன்னும் நாட்காட்டி இணைப்பை அமைக்கவில்லை.',
        'workcal_push_where' => 'நீங்கள் திட்டமிட்ட டிக்கெட்டுகள் {addr}-க்கான நாட்காட்டியில் எழுதப்படும்.',
        'workcal_push_bad' => '{addr}-க்கு எந்த நாட்காட்டியும் கிடைக்கவில்லை. அது உங்கள் FreeITSM கணக்கில் உள்ள முகவரி, அது எப்போதும் உங்கள் அஞ்சல் பெட்டியாக இருக்காது — உங்கள் நாட்காட்டி ஒத்திசைவை சரியான ஒன்றுக்குச் சுட்டுமாறு நிர்வாகியிடம் கேளுங்கள்.',
        'workcal_push_noaddr' => 'உங்களுடையது எந்த அஞ்சல் பெட்டி என்று எங்களுக்குத் தெரியவில்லை. அதை System → Calendar sync இல் அமைக்குமாறு நிர்வாகியிடம் கேளுங்கள்.',
        'workcal_conn' => 'எந்த நாட்காட்டி',
        'workcal_conn_choose' => 'தேர்ந்தெடுக்கவும்…',
        'workcal_conn_needed' => 'நீங்கள் திட்டமிட்ட வேலை எந்த நாட்காட்டியில் சேர வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும்.',
        'workcal_push_caldav_where' => 'நீங்கள் திட்டமிட்ட டிக்கெட்டுகள் உங்கள் நாட்காட்டி “{name}” இல் எழுதப்படும்.',
        'caldav_intro' => '{server} இல் உள்ள உங்கள் நாட்காட்டியில் உள்நுழைந்து, நீங்கள் திட்டமிட்ட வேலை எந்த நாட்காட்டியில் சேர வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும். FreeITSM உங்களாகவே உள்நுழைகிறது, எனவே உங்களால் அணுகக்கூடிய நாட்காட்டிகளை மட்டுமே அதனால் அணுக முடியும்.',
        'caldav_username' => 'பயனர்பெயர்',
        'caldav_password' => 'கடவுச்சொல்',
        'caldav_password_hint' => 'உங்கள் நாட்காட்டி கடவுச்சொல், அல்லது உங்கள் நாட்காட்டி வழங்கினால் ஆப் கடவுச்சொல் - அதுவே பாதுகாப்பான தேர்வு. குறியாக்கம் செய்து சேமிக்கப்படும், மீண்டும் காட்டப்படாது.',
        'caldav_password_saved' => 'சேமிக்கப்பட்டது - அப்படியே வைத்திருக்க காலியாக விடவும்',
        'caldav_find' => 'கண்டுபிடி',
        'caldav_finding' => 'உங்கள் நாட்காட்டிகளைத் தேடுகிறது…',
        'caldav_choose' => 'நாட்காட்டி',
        'caldav_none' => 'அந்த உள்நுழைவு வேலை செய்தது, ஆனால் நிகழ்வுகளை வைத்திருக்கக்கூடிய நாட்காட்டி எதுவும் அதில் இல்லை.',
        'caldav_needs' => 'உள்நுழைந்து ஒரு நாட்காட்டியைத் தேர்ந்தெடுக்கவும். சேமிப்பது இதை இயக்கும்.',
        'caldav_saved' => 'சேமிக்கப்பட்டது. நீங்கள் திட்டமிட்ட வேலை “{name}” இல் சேரும்.',
        'caldav_saved_error' => 'சேமிக்கப்பட்டது, ஆனால் நாட்காட்டியில் எழுதுவது தோல்வியடைந்தது: {error}',
        'caldav_current' => '{user} ஆக உள்நுழைந்துள்ளீர்கள், “{name}” இல் எழுதுகிறது.',
        'caldav_change' => 'மாற்று',
        'caldav_forget' => 'மற',
        'caldav_forget_title' => 'உங்கள் நாட்காட்டி உள்நுழைவை மறக்கவா?',
        'caldav_forget_confirm' => 'FreeITSM தனது நிகழ்வுகளை உங்கள் நாட்காட்டியிலிருந்து திரும்ப எடுத்து, பின்னர் உங்கள் உள்நுழைவை மறந்து இதை முடக்கும்.',
        'workcal_disabled' => 'இந்த அமைப்பில் நாட்காட்டி சந்தா இணைப்புகளை நிர்வாகி முடக்கியுள்ளார்.',
        'workcal_url' => 'உங்கள் தனிப்பட்ட சந்தா இணைப்பு',
        'workcal_show' => 'என் இணைப்பைப் பெறு',
        'workcal_copy' => 'நகலெடு',
        'workcal_reset' => 'மீட்டமை',
        'workcal_copied' => 'இணைப்பு நகலெடுக்கப்பட்டது',
        'workcal_secret_note' => 'இதை ஒரு கடவுச்சொல்லைப் போலக் கருதுங்கள். இணைப்பை வைத்திருக்கும் எவரும் உள்நுழையாமலேயே நீங்கள் திட்டமிட்ட வேலையைப் பார்க்கலாம், எனவே இதை அனுப்பாதீர்கள். இதைத் திரும்பப் பெற வேண்டுமெனில் மீட்டமைக்கவும்.',
        'workcal_insecure' => 'இந்த அமைப்பு HTTPS பயன்படுத்துவதில்லை, எனவே உங்கள் நாட்காட்டி புதுப்பிக்கப்படும் ஒவ்வொரு முறையும் இந்த இணைப்பும் அது காட்டும் அனைத்தும் பாதுகாப்பின்றி நெட்வொர்க் வழியாகப் பயணிக்கும். நம்பகமான நெட்வொர்க்கிற்கு வெளியே இதைப் பயன்படுத்தும் முன் HTTPS ஐ இயக்குமாறு உங்கள் நிர்வாகியிடம் கேளுங்கள்.',
        'workcal_reset_confirm' => 'ஏற்கனவே சந்தா செலுத்திய ஒவ்வொரு சாதனமும், புதிய இணைப்பை அதற்குக் கொடுக்கும் வரை புதுப்பிப்பதை நிறுத்தும். தொடரவா?',
        'workcal_reset_done' => 'இணைப்பு மீட்டமைக்கப்பட்டது — பழையது இனி வேலை செய்யாது',
        'workcal_detail' => 'நாட்காட்டி காட்டுவது',
        'workcal_detail_full' => 'டிக்கெட் எண் மற்றும் பொருள்',
        'workcal_detail_ref' => 'டிக்கெட் எண் மட்டும்',
        'workcal_detail_locked' => 'இந்த அமைப்பில் சந்தா இணைப்புகளை டிக்கெட் எண்களுக்கு மட்டும் நிர்வாகி வரம்பிட்டுள்ளார்.',
        'landing_desc' => 'உள்நுழையாமல் FreeITSM ஐத் திறக்கும்போது நீங்கள் அனுப்பப்படும் இடம்.',
        'landing_default' => 'தள இயல்புநிலையைப் பயன்படுத்து ({name})',
        'landing_analyst' => 'பகுப்பாய்வாளர் உள்நுழைவு',
        'landing_portal' => 'சுய-சேவை போர்டல்',
        'landing_note' => 'உங்கள் மற்ற விருப்பத்தேர்வுகளைப் போலன்றி, இது நீங்கள் உள்நுழைவதற்கு முன்பே படிக்கக்கூடியதாக இருக்க வேண்டும், எனவே இது இந்த உலாவியிலும் சேமிக்கப்படுகிறது. புதிய சாதனத்திலும் உட்பட, நீங்கள் உள்நுழையும் ஒவ்வொரு முறையும் இது தானாக மீண்டும் பயன்படுத்தப்படும்.',
        'timezone_heading' => 'நேர மண்டலம்',
        'timezone_desc' => 'உங்களுக்குக் காட்டப்படுவதற்கு முன் நேரங்கள் எந்த நேர மண்டலத்திற்கு மாற்றப்படுகின்றன என்பது. நீங்கள் ஒன்றைத் தேர்ந்தெடுக்கும் வரை சேவையகத்தின் நேர மண்டலமே இயல்பு. இது நேரத்தையே மாற்றுகிறது, அது எழுதப்படும் விதத்தை அல்ல.',
        'timezone_saved' => 'நேர மண்டலம் சேமிக்கப்பட்டது',
        'dateformat_heading' => 'தேதி வடிவம்',
        'dateformat_desc' => 'ஒரு தேதி எவ்வாறு எழுதப்படுகிறது என்பது. இது அமைப்பு முறை மட்டுமே - தேதி ஒருபோதும் மாறாது, மாதப் பெயர்கள் எப்போதும் உங்கள் இடைமுக மொழியைப் பின்பற்றும்.',
        'timeformat_heading' => 'நேர வடிவம்',
        'timeformat_desc' => '24-மணிநேர கடிகாரம், அல்லது AM மற்றும் PM உடன் 12-மணிநேர கடிகாரம்.',
        'format_follow_default' => 'கணினி இயல்புநிலையைப் பயன்படுத்து ({example})',
        'format_saved' => 'வடிவம் சேமிக்கப்பட்டது',
        'sidebar_heading' => 'பக்கப்பட்டி',
        'sidebar_desc' => 'வாஃபிள் மெனுவைத் திறப்பதற்குப் பதிலாக, ஒவ்வொரு திரையின் இடது பக்கத்திலும் உங்கள் தொகுதிகளை ஒரு கிளிக்கில் வைத்திருக்கவும். வாஃபிள் மெனு எப்படியும் அதே இடத்தில் இருக்கும். தொலைபேசியில் காட்டப்படாது.',
        'sidebar_label' => 'பக்கப்பட்டியைக் காட்டு',
        'sidebar_pick' => 'அதில் வேண்டிய தொகுதிகளைத் தேர்வு செய்யவும். அவை மேலே உள்ள உங்கள் தொகுதி வரிசையில் தோன்றும்.',
        'sidebar_on' => 'பக்கப்பட்டி இயக்கத்தில் - நீங்கள் திறக்கும் அடுத்த பக்கத்தில் அதைப் பார்ப்பீர்கள்',
        'sidebar_off' => 'பக்கப்பட்டி முடக்கத்தில்',
        'sidebar_saved' => 'பக்கப்பட்டி சேமிக்கப்பட்டது',
        'modorder_heading' => 'தொகுதி வரிசை',
        'modorder_desc' => 'உங்கள் வாஃபிள் மெனு, முகப்புப் பக்கம் மற்றும் Ctrl+K "Go to" பட்டியலில் உள்ள தொகுதிகளின் வரிசை. ஒரு தொகுதியை அதன் கைப்பிடியால் இழுக்கவும், அம்புகளைப் பயன்படுத்தவும், அல்லது ஒன்றைத் தேர்ந்தெடுத்து Alt உடன் மேல் அல்லது கீழ் அம்புக்குறியை அழுத்தவும். இந்த வரிசையை நீங்கள் மட்டுமே பார்ப்பீர்கள்.',
        'modorder_note' => 'நீங்கள் மாற்றும்போதே சேமிக்கப்படும், நீங்கள் திறக்கும் அடுத்த பக்கத்திலிருந்து பயன்படுத்தப்படும். பிந்தைய புதுப்பிப்பில் சேர்க்கப்படும் தொகுதி தானாகவே பட்டியலில் இணையும்.',
        'modorder_reset' => 'மீட்டமை',
        'modorder_reset_done' => 'தொகுதிகள் இயல்பு வரிசைக்குத் திரும்பிவிட்டன',
        'modorder_saved' => 'தொகுதி வரிசை சேமிக்கப்பட்டது',
        'modorder_label' => 'தொகுதி வரிசை',
        'money_heading' => 'பணம்',
        'money_desc' => 'பணத் தொகைகள் உங்களுக்கு எவ்வாறு எழுதப்படுகின்றன என்பது. ஒவ்வொரு பதிவின் நாணயமும் ஒருபோதும் மாறாது - உங்கள் திரையில் அதன் தொகை தோன்றும் விதம் மட்டுமே மாறும்.',
        'money_follow' => 'கணினி இயல்புநிலையைப் பயன்படுத்து ({example})',
        'money_own' => 'என் சொந்தத்தைத் தேர்ந்தெடு',
        'money_exc_heading' => 'குறிப்பிட்ட நாணயங்கள்',
        'money_exc_desc' => 'ஒரு நாணயத்திற்கு வேறு வடிவம் - எடுத்துக்காட்டாக, மற்றவை மேலே உள்ளபடி இருக்கும்போது யூரோவை ஜெர்மனியில் எழுதப்படுவது போல.',
        'money_exc_none' => 'எதுவுமில்லை. ஒவ்வொரு நாணயமும் மேலே உள்ள தேர்வைப் பின்பற்றுகிறது.',
        'money_add' => 'சேர்',
        'money_remove' => 'அகற்று',
        'position_heading' => 'அறிவிப்பு நிலை',
        'position_desc' => 'டோஸ்ட் அறிவிப்புகள் திரையில் எங்கே தோன்றும் என்பது.',
        'animation_heading' => 'அறிவிப்பு அனிமேஷன்',
