        'anim_slide' => 'நழுவல்',
        'anim_fade' => 'மங்கல்',
        'panels_heading' => 'இடது பலகங்கள்',
        'panels_desc' => 'ஒவ்வொரு தொகுதிக்கும், இடது பலகம் திறந்தே பொருத்தப்பட்டிருக்குமா அல்லது மேலே வைக்கும்போது விரியும் மெல்லிய பட்டையாகச் சுருங்குமா என்பதைத் தேர்ந்தெடுக்கவும். அமைப்புகள் பக்கம் உள்ள தொகுதிகள் தங்கள் சொந்த இடது பலகம் தாவலிலும் இதை வழங்குகின்றன.',
