        'multiselect_heading' => 'பல டிக்கெட்டுகளைத் தேர்ந்தெடுத்தல்',
        'multiselect_desc' => 'டிக்கெட் இன்பாக்ஸில் ஒரே நேரத்தில் பல டிக்கெட்டுகளைத் தேர்ந்தெடுக்கலாம் — ஒவ்வொன்றாகத் தேர்வுசெய்ய Ctrl+கிளிக், ஒரு தொகுதிக்கு Shift+கிளிக். ஒன்றுக்கு மேற்பட்டவை தேர்ந்தெடுக்கப்பட்டிருக்கும்போது திரை என்ன காட்டும் என்பதை இது தீர்மானிக்கிறது.',
        'multiselect_summary' => 'சுருக்கப் பலகம்',
        'multiselect_keep' => 'டிக்கெட்டைத் திறந்தே வை',
        'multiselect_bar' => 'பட்டியலுக்கு மேலே பட்டை',
        'multiselect_summary_hint' => 'வாசிப்புப் பலகம் நீங்கள் தேர்ந்தெடுத்தவற்றை, மொத்தச் செயல்களுடன் பட்டியலிடுகிறது.',
        'multiselect_keep_hint' => 'வாசிப்புப் பலகம் நீங்கள் திறந்த டிக்கெட்டைத் தொடர்ந்து காட்டும், ஒரு செயல் அனைத்தையும் பாதிக்கும் என்ற நினைவூட்டலுடன்.',
        'multiselect_bar_hint' => 'டிக்கெட் பட்டியலுக்கு மேலே எண்ணிக்கை மற்றும் செயல்களுடன் ஒரு சிறிய பட்டை தோன்றும்.',
        'details_heading' => 'என் விவரங்கள்',
        'details_desc' => 'உங்கள் மின்னஞ்சல் கையொப்பங்களால் பயன்படுத்தப்படுகிறது. உங்கள் பெயரும் மின்னஞ்சல் முகவரியும் உங்கள் கணக்கிலிருந்து வருகின்றன, இங்கே திருத்த முடியாது.',
        'details_managed_note' => 'உங்கள் சுயவிவர விவரங்கள் உங்கள் அடையாள வழங்குநரால் நிர்வகிக்கப்படுகின்றன, இங்கே மாற்ற முடியாது.',
        'details_job_title' => 'பணிப் பெயர்',
        'details_department' => 'துறை',
        'details_phone' => 'தொலைபேசி',
        'details_mobile' => 'மொபைல்',
        'sig_heading' => 'மின்னஞ்சல் கையொப்பங்கள்',
        'sig_desc' => 'கையொப்பங்கள் உங்களுக்கு மட்டுமே உரியவை — வேறு யாரும் அவற்றைப் பார்க்கவோ மாற்றவோ முடியாது. இயல்புநிலை எனக் குறிக்கப்பட்டது உங்கள் பதில்களில் தானாகச் சேர்க்கப்படும், மேலும் சக ஊழியர்களுக்கு ஒரு குறுகிய குறிப்பு அல்லது வேறொரு மொழியில் ஒன்று போன்ற வேறு முடிவுரை பொருத்தமாக இருக்கும்போது பயன்படுத்த ஒன்றுக்கு மேற்பட்டவற்றை வைத்திருக்கலாம்.',
        'sig_empty' => 'உங்களிடம் இன்னும் கையொப்பங்கள் இல்லை.',
        'sig_load_failed' => 'உங்கள் கையொப்பங்களை ஏற்ற முடியவில்லை, எனவே எதுவும் காட்டப்படவில்லை. இது எதுவும் இல்லாததற்குச் சமமல்ல — ஒன்றைச் சேர்க்கும் முன் மீண்டும் ஏற்றவும், இல்லையெனில் நகல் உருவாகலாம்.',
        'sig_save_failed' => 'அதைச் சேமிக்க முடியவில்லை.',
        'sig_delete_confirm' => 'இந்தக் கையொப்பத்தை நீக்கவா?',
        'sig_default' => 'இயல்புநிலை',
        'sig_is_default' => 'இதை என் பதில்களில் தானாகச் சேர்',
