        'sig_preview' => 'முன்னோட்டம்',
        'mc_heading' => 'காலை சரிபார்ப்புகள் பட்டை நிரப்பல்',
        'mc_desc' => 'காலை சரிபார்ப்புகளின் 30-நாள் போக்கு வரைபடத்திற்கான திடமான அல்லது சாய்வு நிரப்பல். காலை சரிபார்ப்புகள் அமைப்புகள் பக்கத்திலும் கிடைக்கும்.',
