    'dateformat' => [
        'title' => 'தேதி மற்றும் நேர வடிவங்கள்',
        'subtitle' => 'FreeITSM முழுவதும் தேதிகளும் நேரங்களும் எவ்வாறு எழுதப்படுகின்றன என்பது. இது அனைவருக்குமான இயல்புநிலை; எந்தப் பகுப்பாய்வாளரும் விருப்பத்தேர்வுகளில் தனக்கு வேறொன்றைத் தேர்ந்தெடுக்கலாம்.',
        'date_heading' => 'தேதி வடிவம்',
        'date_desc' => 'ஒரு தேதி எவ்வாறு எழுதப்படுகிறது என்பதைத் தேர்ந்தெடுக்கவும். இது அமைப்பு முறை பற்றியது மட்டுமே - நாள், மாதம், ஆண்டு ஆகியவை ஒருபோதும் மாறாது, மாதப் பெயர்கள் எப்போதும் இடைமுக மொழியைப் பின்பற்றும்.',
        'time_heading' => 'நேர வடிவம்',
        'time_desc' => '24-மணிநேர கடிகாரத்துக்கும் AM மற்றும் PM உடன் 12-மணிநேர கடிகாரத்துக்கும் இடையே தேர்ந்தெடுக்கவும். இது நேரத்தையே மாற்றாது, அது எழுதப்படும் விதத்தை மட்டுமே மாற்றும்.',
        'preview_heading' => 'முன்னோட்டம்',
        'preview_desc' => 'நீங்கள் சேமித்த பிறகு தோன்றும் விதத்தில் ஒரு மாதிரி தேதியும் நேரமும்.',
        'preview_label' => 'தேதிகள் இவ்வாறு இருக்கும்',
        'scope_heading' => 'இது எதை மாற்றாது.',
        'scope_note' => 'நேரங்களில் எதையும் மாற்றாது. ஒரு நேரம் எந்த நேர மண்டலத்தில் காட்டப்படுகிறது என்பது விருப்பத்தேர்வுகளில் ஒவ்வொரு பகுப்பாய்வாளருக்கும் தனியாக அமைக்கப்படுகிறது - மேலும் எப்படியிருந்தாலும் தேதிகள் மாற்றமின்றி சேமிக்கப்படுவதால், சேவை நிலை இலக்குகள், அறிக்கைகள் மற்றும் ஏற்றுமதிகள் பாதிக்கப்படாது.',
        'saved' => 'தேதி மற்றும் நேர வடிவங்கள் சேமிக்கப்பட்டன',
        'error' => 'சேமிக்க முடியவில்லை: {error}',
        'save_failed' => 'தேதி மற்றும் நேர வடிவங்களைச் சேமிக்க முடியவில்லை',
    ],
    'currencies' => [
        'title' => 'நாணயங்கள்',
        'subtitle' => 'உலகில் பயன்பாட்டில் உள்ள ஒவ்வொரு நாணயமும் FreeITSM பணத்தைப் பதிவு செய்யும் எல்லா இடங்களிலும் கிடைக்கும். எவை முதலில் வர வேண்டும், புதிய பதிவுகள் எதில் தொடங்க வேண்டும், தொகைகள் எவ்வாறு எழுதப்பட வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும். எந்தப் பகுப்பாய்வாளரும் விருப்பத்தேர்வுகளில் தனக்கு வேறு வடிவத்தைத் தேர்ந்தெடுக்கலாம்.',
        'fav_heading' => 'பிடித்தவை',
        'fav_desc' => 'ஒவ்வொரு நாணயப் பட்டியலின் மேலேயும் காட்டப்படும் {max} நாணயங்கள் வரை. இயல்புநிலை எனக் குறிக்கப்பட்டது, புதிய ஒப்பந்தம், உரிமம், டொமைன், குத்தகை அல்லது திட்டம் தொடங்கும் நாணயம்.',
        'fav_default' => 'இயல்புநிலை',
        'fav_remove' => '{code} ஐ அகற்று',
        'fav_add' => 'சேர்',
        'fav_full' => 'பிடித்தவையின் அதிகபட்ச எண்ணிக்கை இதுவே. மற்றொன்றைச் சேர்க்க ஒன்றை அகற்றவும்.',
        'fav_existing' => 'இயல்புநிலையை மாற்றுவது ஏற்கனவே நாணயம் உள்ள பதிவை ஒருபோதும் மாற்றாது.',
        'format_heading' => 'தொகைகள் எவ்வாறு எழுதப்படுகின்றன',
        'format_desc' => 'கீழே உள்ள விதிவிலக்கு வேறுவிதமாகக் கூறினால் தவிர, ஒவ்வொரு நாணயத்துக்கும் உரிய வடிவம். தசம இடங்களில் "As the currency" என்பது நாணயத்தையே பின்பற்றும்: யென்னுக்கு எதுவுமில்லை, பவுண்டுக்கு இரண்டு, குவைத் தினாருக்கு மூன்று.',
        'preview_label' => 'உங்கள் பிடித்தவை இவ்வாறு இருக்கும்',
        'exc_heading' => 'குறிப்பிட்ட நாணயங்களுக்கான விதிவிலக்குகள்',
        'exc_desc' => 'ஒரு நாணயத்திற்கு வேறு வடிவம் - எடுத்துக்காட்டாக, மற்றவை மேலே உள்ளபடி இருக்கும்போது ரூபியாவை இந்தோனேசிய முறையில், Rp 1.500.000 என எழுதுவது.',
        'exc_none' => 'விதிவிலக்குகள் இல்லை. ஒவ்வொரு நாணயமும் மேலே உள்ள வடிவத்தைப் பயன்படுத்துகிறது.',
        'exc_add' => 'சேர்',
        'exc_remove' => 'அகற்று',
        'unknown_heading' => 'உங்கள் பதிவுகளில் உள்ள அடையாளம் காணப்படாத குறியீடுகள்',
        'unknown_desc' => 'நாணயங்கள் பட்டியலாக மாறுவதற்கு முன் இவை தட்டச்சு செய்யப்பட்டவை. அவை இன்னும் உள்ளபடியே காட்டப்படுகின்றன, ஆனால் பட்டியலிலிருந்து ஒரு நாணயம் தேர்ந்தெடுக்கப்படும் வரை அந்தப் பதிவைச் சேமிக்க முடியாது.',
        'unknown_row' => '{code} - {where} இல் {count}',
        'saved' => 'நாணயங்கள் சேமிக்கப்பட்டன',
        'error' => 'சேமிக்க முடியவில்லை: {error}',
        'save_failed' => 'நாணயங்களைச் சேமிக்க முடியவில்லை',
    ],
    'security' => [
        'title' => 'பாதுகாப்பு',
        'subtitle' => 'அங்கீகரிப்புக் கொள்கைகளையும் கணக்குப் பாதுகாப்பையும் அமைக்கவும்',
        'selfreg_heading' => 'சுய-சேவை பதிவு',
        'selfreg_desc' => 'உள்நுழைவுப் பக்கத்திலிருந்து மக்கள் தங்களுக்கான சுய-சேவை போர்டல் கணக்கை உருவாக்கலாமா என்பது. இயல்பாக முடக்கத்தில் உள்ளது. இயக்கப்பட்டால், கடவுச்சொல் அமைக்கப்படுவதற்கு முன் பதிவு ஒரு மின்னஞ்சல் இணைப்பால் உறுதிப்படுத்தப்படும்.',
        'selfreg_label' => 'சுய-பதிவை அனுமதி',
        'selfreg_hint' => 'முடக்கம் = யாரும் தங்கள் சொந்தக் கணக்கை உருவாக்க முடியாது. நீங்கள் சேர்க்கும் நபர்கள் இன்னும் உள்நுழையலாம் — போர்டல் உள்நுழைவுப் பக்கத்தில் “Forgot your password?” என்பதைப் பயன்படுத்தி தங்கள் முதல் கடவுச்சொல்லை அமைப்பார்கள்.',
        'trusted_heading' => 'நம்பகமான சாதனம்',
        'trusted_desc' => 'நம்பகமான உலாவிகளில் OTP சரிபார்ப்பைத் தவிர்க்க பயனர்களை அனுமதிக்கவும். பயனர்கள் தங்கள் அவதார் மெனு வழியாக தனித்தனியாகத் தேர்வு செய்கிறார்கள். இந்த அம்சத்தை முழுவதுமாக முடக்க 0 என அமைக்கவும்.',
        'trust_duration' => 'நம்பிக்கைக் காலம்',
        'trust_duration_hint' => 'OTP சரிபார்ப்புக்குப் பிறகு ஒரு சாதனம் எவ்வளவு காலம் நம்பகமானதாக இருக்கும்',
        'password_heading' => 'கடவுச்சொல் கொள்கை',
        'password_desc' => 'பயனர்கள் அவ்வப்போது தங்கள் கடவுச்சொல்லை மாற்ற வேண்டும் என்று கோரவும். கடவுச்சொல் காலாவதியானால், அடுத்த உள்நுழைவில் பயனர் கட்டாயக் கடவுச்சொல் மாற்றத் திரைக்கு அனுப்பப்படுவார். முடக்க 0 என அமைக்கவும்.',
        'password_expiry' => 'கடவுச்சொல் காலாவதி',
        'password_expiry_hint' => 'கடவுச்சொல் மாற்றப்பட வேண்டிய அதிகபட்ச வயது',
        'lockout_heading' => 'கணக்குப் பூட்டு',
        'lockout_desc' => 'brute-force தாக்குதல்களைத் தடுக்க, மீண்டும் மீண்டும் தோல்வியடைந்த உள்நுழைவு முயற்சிகளுக்குப் பிறகு கணக்குகளைப் பூட்டவும். பூட்டை முடக்க அதிகபட்ச முயற்சிகளை 0 என அமைக்கவும்.',
        'max_attempts' => 'அதிகபட்ச தோல்வி முயற்சிகள்',
        'max_attempts_hint' => 'கணக்கு பூட்டப்படுவதற்கு முன் அனுமதிக்கப்படும் தவறான கடவுச்சொற்களின் எண்ணிக்கை',
        'lockout_duration' => 'பூட்டு காலம்',
        'lockout_duration_hint' => 'கணக்கு எவ்வளவு காலம் பூட்டப்பட்டிருக்கும் (திறந்த பிறகு எண்ணிக்கை மீட்டமைக்கப்படும்)',
        'ipban_heading' => 'IP தடை',
        'ipban_desc' => 'இல்லாத அல்லது பூட்டப்பட்ட கணக்குகளுக்கு எதிராக மீண்டும் மீண்டும் உள்நுழைய முயற்சிக்கும் IP முகவரிகளைத் தானாகத் தடை செய்யவும். ஒவ்வொரு தடையும் 24 மணி நேரம் நீடிக்கும். ஒவ்வொரு தடைக்குப் பிறகும் வரம்பு 1 குறைகிறது (குறைந்தபட்சம் வரை), மீண்டும் மீண்டும் தவறு செய்பவர்களை முறைகேடு செய்வது கடினமாகிறது. முடக்க அதிகபட்ச முயற்சிகளை 0 என அமைக்கவும்.',
        'first_ban' => 'முதல் தடை வரம்பு',
        'first_ban_hint' => 'IP முதன்முறையாகத் தடை செய்யப்படுவதற்கு முன் தோல்வி முயற்சிகள்',
        'min_threshold' => 'குறைந்தபட்ச வரம்பு',
        'min_threshold_hint' => 'வரம்பு இந்த அடித்தளத்தை அடைந்ததும் குறைவது நின்றுவிடும்',
        'ipban_example_strong' => 'எடுத்துக்காட்டு:',
        'ipban_example_text' => 'அதிகபட்சம் 5 மற்றும் குறைந்தபட்சம் 2 எனில், முதல் தடை 5 தோல்வி முயற்சிகளுக்குப் பிறகு, இரண்டாவது 4க்குப் பிறகு, பின்னர் 3, பின்னர் 2. அதன் பிறகு ஒவ்வொரு தடைக்கும் அது 2-இலேயே இருக்கும். இல்லாத பயனர்பெயர்கள் அல்லது ஏற்கனவே பூட்டப்பட்ட கணக்குகளுக்கு எதிரான முயற்சிகள் மட்டுமே கணக்கில் வரும்.',
        'attachments_heading' => 'இணைப்புகள்',
        'attachments_desc' => 'FreeITSM தான் அடையாளம் காணும் இணைப்பு வகைகளை மட்டுமே ஏற்கிறது. மற்றவை — நிரல், ஸ்கிரிப்ட், வலைப்பக்கம் — அவற்றின் சொந்தப் பெயரில் ஒருபோதும் சேமிக்கப்படுவதில்லை, எனவே அவற்றை இயக்க முடியாது.',
        'rejected_behaviour' => 'ஒரு கோப்பு வகை ஏற்கப்படாதபோது',
        'rejected_behaviour_hint' => 'மின்னஞ்சல், போர்டல் மற்றும் அரட்டை சேனல்களுக்குப் பொருந்தும்.',
        'rejected_store' => 'வைத்துக்கொள், பதிவிறக்கம் மட்டும்',
        'rejected_drop' => 'வைத்துக்கொள்ளாதே',
        'allowed_extensions' => 'ஏற்கப்படும் கோப்பு வகைகள்',
        'allowed_extensions_hint' => 'FreeITSM பாதுகாப்பானது எனக் கருதும் அனைத்தையும், எதிர்கால புதுப்பிப்புகளில் சேர்க்கப்படும் புதிய வகைகள் உட்பட, ஏற்க இதை வெறுமையாக விடவும். குறைவாக ஏற்க, நீங்கள் விரும்பும் நீட்டிப்புகளை மட்டும் கமாவால் பிரித்துப் பட்டியலிடவும்.',
        'allowed_extensions_ph' => 'எ.கா. pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'இந்தப் பட்டியலை நீங்கள் சுருக்க மட்டுமே முடியும். FreeITSM ஏற்கனவே பாதுகாப்பானது எனக் கருதாத நீட்டிப்பு புறக்கணிக்கப்படும், எனவே இங்கே தட்டச்சு செய்யும் எதுவும் ஒரு நிரலையோ ஸ்கிரிப்டையோ ஏற்கத்தக்கதாக்க முடியாது.',
        'rejected_note' => 'எப்படியிருந்தாலும் டிக்கெட் என்ன நடந்தது, ஏன் என்று சொல்லும், எனவே தங்கள் கோப்பு எங்கே போனது என்று யாரும் யோசிக்க வேண்டியதில்லை.',
        'max_attachment' => 'மிகப் பெரிய இணைப்பு',
        'max_attachment_hint' => 'மின்னஞ்சல், போர்டல், அரட்டை சேனல்கள், பதில்கள் மற்றும் இணைக்கப்பட்ட ஆவணங்கள் என எந்த ஒரு இணைப்பும் இதை விடப் பெரியதாக இருக்க முடியாது. மாற்றாவிட்டால் 10 MB.',
        'max_total' => 'மிகப் பெரிய மின்னஞ்சல்',
        'max_total_hint' => 'ஒரு உள்வரும் மின்னஞ்சலில் உள்ள அனைத்து இணைப்புகளும் சேர்ந்து. 0 என்றால் மேலே உள்ளதைத் தவிர வேறு வரம்பு இல்லை.',
        'php_limits' => 'இந்தச் சேவையகத்தில் உள்ள PHP உலாவி பதிவேற்றங்களை ஒரு கோப்புக்கு {upload} வரையும், ஒரு கோரிக்கைக்கு {post} வரையும் (php.ini-இல் upload_max_filesize மற்றும் post_max_size) ஏற்கிறது, மேலும் அதனிடம் செயல்பட {memory} நினைவகம் உள்ளது. PHP மறுக்கும் கோப்பு FreeITSM-ஐ ஒருபோதும் சென்றடையாது, எனவே இவற்றை விட அதிகமான வரம்பு மின்னஞ்சலுக்கு மட்டுமே உதவும். முன்னால் உள்ள ஒரு web server அல்லது proxy (nginx client_max_body_size, IIS maxAllowedContentLength) தனக்கென குறைந்த வரம்பை அமைக்கலாம்.',
        'php_limits_warn' => 'மிகப் பெரிய இணைப்பு, PHP உலாவியிலிருந்து ஏற்பதை விட அதிகமாக உள்ளது: php.ini-இல் upload_max_filesize மற்றும் post_max_size ஆகியவற்றையும் உயர்த்தவும், இல்லையெனில் FreeITSM வழியாகப் பதிவேற்றப்படும் கோப்புகள் வந்து சேரும் முன்பே மறுக்கப்படும்.',
        'php_unlimited' => 'வரம்பு இல்லை',
        'oversize_signpost' => 'இந்த வரம்புகளை மீறும் உள்வரும் மின்னஞ்சலுக்கு என்ன நடக்கும் - அதை நிராகரிப்பதா, அல்லது மிகப் பெரிய இணைப்புகள் இல்லாமல் வைத்துக்கொள்வதா, மற்றும் யாருக்குத் தெரிவிக்கப்படும் - என்பது {link}-இல் அமைக்கப்படுகிறது. ஒவ்வொரு அஞ்சல் பெட்டியும் அங்கே தனக்கென வரம்புகளையும் அமைக்கலாம்.',
        'oversize_signpost_link' => 'Tickets -> Settings -> Mailboxes',
        'unit_days' => 'நாட்கள்',
        'unit_attempts' => 'முயற்சிகள்',
        'unit_minutes' => 'நிமிடங்கள்',
        'save' => 'சேமி',
        'saved' => 'பாதுகாப்பு அமைப்புகள் சேமிக்கப்பட்டன',
        'error' => 'பிழை: {error}',
        'save_failed' => 'அமைப்புகளைச் சேமிக்க முடியவில்லை',
    ],
    'sso' => [
        'title' => 'அங்கீகாரம்',
        'subtitle' => 'Keycloak, Microsoft Entra, Okta அல்லது Google போன்ற வெளிப்புற அடையாள வழங்குநர் (OpenID Connect) மூலமாகவோ, உங்கள் LDAP / Active Directory மூலமாகவோ — உள்ளூர் கணக்குகளுடன் சேர்த்து — பயனர்கள் உள்நுழைய அனுமதிக்கவும்.',
        'global_heading' => 'பொது அமைப்புகள்',
        'global_desc' => 'முழு அமைப்பிலும் உள்நுழைவுக்கான முதன்மைக் கட்டுப்பாடுகள்.',
        'enable_sso' => 'Single sign-on-ஐ இயக்கு',
        'enable_sso_desc' => 'உள்நுழைவுப் பக்கத்தில் உள்ளமைக்கப்பட்ட வழங்குநர் பொத்தான்களைக் காட்டும். அணைத்தால் எல்லா இடங்களிலும் உடனடியாக உள்ளூர் உள்நுழைவுகளுக்கே திரும்பும் (break-glass).',
        'allow_local' => 'உள்ளூர் உள்நுழைவை அனுமதி',
        'allow_local_desc' => 'பயனர்பெயர் + கடவுச்சொல் படிவத்தை கிடைக்கும்படி வைத்திருக்கும். தவறாக உள்ளமைக்கப்பட்ட அல்லது செயலிழந்த வழங்குநர் யாரையும் வெளியே பூட்டிவிடாதபடி இதை இயக்கத்தில் வைக்கவும்.',
        'global_load_failed' => 'இந்த அமைப்புகளைப் படிக்க முடியவில்லை.',
        'global_load_failed_desc' => 'கீழுள்ள சுவிட்சுகள் உங்கள் உண்மையான அமைப்புகளைக் காட்டவில்லை, எனவே தவறான மதிப்பு மேலே சேமிக்கப்படாதபடி அவை பூட்டப்பட்டுள்ளன. எதுவும் மாறவில்லை.',
        'retry' => 'மீண்டும் முயற்சி',
        'save' => 'சேமி',
        'redirect_heading' => 'Redirect URI',
        'redirect_desc' => 'இந்த URL-ஐ ஒவ்வொரு அடையாள வழங்குநரிலும் அனுமதிக்கப்பட்ட redirect / callback URL ஆகப் பதிவு செய்யவும். பயனர்கள் உள்நுழைந்த பிறகு வழங்குநர் அவர்களை அனுப்பும் இடம் இதுவே.',
        'signout_heading' => 'வெளியேறும் முகவரிகள்',
        'signout_desc' => 'இரண்டையும் ஒவ்வொரு அடையாள வழங்குநரிலும் அனுமதிக்கப்பட்ட வெளியேறும் (post-logout) redirect URL-களாகப் பதிவு செய்யவும். FreeITSM-இலிருந்து வெளியேறுவது வழங்குநரிலிருந்தும் வெளியேற்றும், பின்னர் அது இவற்றில் ஒன்றுக்கு அனுப்பும். பட்டியலிடப்படாத முகவரிகளை Keycloak மற்றும் Okta துல்லியமாக நிராகரிக்கும்.',
        'signout_analyst' => 'பகுப்பாய்வாளர் உள்நுழைவு',
        'signout_portal' => 'சுய-சேவை போர்டல்',
        'copy' => 'நகலெடு',
        'providers_heading' => 'உள்நுழைவு முறைகள்',
        'providers_desc' => 'உங்கள் ஆட்கள் எங்கிருந்து வருகிறார்கள். பெரும்பாலான வரிசைகள் உள்நுழையும் வழி — அடையாள வழங்குநர் (SSO) அல்லது டைரக்டரி (LDAP) — மேலும் சோதனைகளை இணையாக நடத்த வெவ்வேறு பயனர்களை வெவ்வேறு முறைகளுக்கு ஒதுக்கலாம். CardDAV முகவரிப் புத்தகம் விதிவிலக்கு: அது தொடர்புகளை உள்ளே கொண்டுவருகிறது, அதன் வழியாக யாரும் உள்நுழைவதில்லை.',
        'add' => 'சேர்',
        'col_name' => 'பெயர்',
        'col_company' => 'நிறுவனம்',
        'col_issuer' => 'வழங்குபவர்',
        'col_status' => 'நிலை',
        'col_sync' => 'சுயவிவர ஒத்திசைவு',
        'sync_pill_always' => 'எப்போதும்',
        'sync_pill_initial' => 'தொடக்கத்தில்',
        'sync_pill_never' => 'ஒருபோதும் இல்லை',
        'col_auto_create' => 'தானாக உருவாக்கு',
        'col_actions' => 'செயல்கள்',
        'global_badge' => 'பொது',
        'loading' => 'ஏற்றுகிறது…',
        'no_providers' => 'இன்னும் வழங்குநர்கள் இல்லை. ஒன்றை உள்ளமைக்க {add} என்பதைக் கிளிக் செய்யவும்.',
        'add_strong' => 'சேர்',
        'enabled' => 'இயக்கப்பட்டது',
        'disabled' => 'முடக்கப்பட்டது',
        'jit_both' => 'போர்டல் + பகுப்பாய்வாளர்கள்',
        'jit_analyst' => 'பகுப்பாய்வாளர்கள்',
        'jit_user' => 'போர்டல்',
        'jit_off' => 'அணைப்பு',
        'jit_na' => 'பொருந்தாது',
        'edit' => 'திருத்து',
        'delete' => 'நீக்கு',
        'modal_add_title' => 'வழங்குநரைச் சேர்',
        'modal_edit_title' => 'வழங்குநரைத் திருத்து',
        'field_display_name' => 'காட்சிப் பெயர்',
        'field_display_name_hint' => 'உள்நுழைவு பொத்தானில் காட்டப்படும், எ.கா. "Sign in with Keycloak"',
        'field_display_name_hint_carddav' => 'உங்கள் சொந்தக் குறிப்புக்கான பெயர் மட்டுமே, எ.கா. "Customer address book". இது உள்நுழைவுப் பக்கத்தில் ஒருபோதும் தோன்றாது — முகவரிப் புத்தகம் வழியாக யாரும் உள்நுழைவதில்லை.',
        'field_display_name_placeholder' => 'Sign in with Keycloak',
        'field_issuer' => 'Issuer URL',
        'field_issuer_hint' => 'வழங்குநரின் அடிப்படை URL. எ.கா. http://localhost:8080/realms/freeitsm',
        'field_issuer_placeholder' => 'https://your-idp/realms/your-realm',
        'test' => 'சோதி',
        'field_client_id' => 'Client ID',
        'field_client_id_hint' => 'வழங்குநரில் உருவாக்கப்பட்ட client/app அடையாளங்காட்டி, எ.கா. freeitsm-app',
        'field_client_secret' => 'Client secret',
        'field_client_secret_hint' => 'வழங்குநரிடமிருந்து பெற்ற client-இன் secret. குறியாக்கம் செய்து சேமிக்கப்படும்.',
        'field_scopes' => 'Scopes',
        'field_scopes_hint' => 'இடைவெளியால் பிரிக்கப்பட்ட OIDC scopes. உங்கள் வழங்குநருக்கு கூடுதலாகத் தேவையென்றால் மட்டுமே இயல்புநிலையை மாற்றவும்.',
        'cb_enabled' => 'இயக்கப்பட்டது',
        'cb_enabled_desc' => 'உள்நுழைவுப் பக்கத்தில் இந்த வழங்குநரின் பொத்தானைக் காட்டு',
        'cb_enabled_desc_carddav' => 'இந்த முகவரிப் புத்தகத்தைப் பயன்படுத்து. அமைப்புகளை நீக்காமல் இதிலிருந்து தொடர்புகளைப் படிப்பதை நிறுத்த இதை அணைக்கவும்.',
        'cb_autocreate' => 'முதல் உள்நுழைவில் பயனர்களைத் தானாக உருவாக்கு (JIT)',
        'cb_autocreate_desc' => 'இந்த வழங்குநர் வழியாக ஒருவர் முதல் முறை உள்நுழையும்போது பகுப்பாய்வாளரைத் தானாக உருவாக்கும். முன்கூட்டியே உருவாக்கப்பட்ட பயனர்கள் மட்டுமே நுழையக்கூடிய கடுமையான சோதனைகளுக்கு அணைத்து வைக்கவும்.',
        'cb_autocreate_users' => 'முதல் உள்நுழைவில் போர்டல் கோரிக்கையாளர்களைத் தானாக உருவாக்கு (JIT)',
        'cb_autocreate_users_desc' => 'இந்த வழங்குநர் வழியாக இறுதிப் பயனர் முதல் முறை உள்நுழையும்போது சுய-சேவை போர்டல் கணக்கைத் தானாக உருவாக்கும்.',
        'cb_autocreate_analysts' => 'முதல் உள்நுழைவில் IT பகுப்பாய்வாளர்களைத் தானாக உருவாக்கு (JIT)',
        'cb_autocreate_analysts_desc' => 'பகுப்பாய்வாளர் உள்நுழைவுத் திரையில் முதல் முறை உள்நுழைபவர்கள் பகுப்பாய்வாளர் கணக்குகளை உருவாக்க அனுமதிக்கும். பகுப்பாய்வாளர்களைக் கைமுறையாக உருவாக்க வேண்டும் என்றால் முடக்கி வைக்கவும்.',
        'field_fallback_mode' => 'பகுப்பாய்வாளர் அல்லாதவர் உள்நுழையும் செயல்',
        'field_fallback_mode_hint' => 'IT பகுப்பாய்வாளர் கணக்கு இல்லாத ஒருவர் பகுப்பாய்வாளர் உள்நுழைவுத் திரையில் உள்நுழையும்போது எடுக்கப்படும் செயல்.',
        'fallback_mode_confirm' => 'சுய-சேவை போர்டலுக்கு மாறுவதற்கு முன் எச்சரித்து உறுதிப்படுத்து',
        'fallback_mode_redirect' => 'சுய-சேவை போர்டலுக்குத் தானாக மாறு',
        'fallback_mode_block' => 'அணுகல் மறுக்கப்பட்டது என்ற பிழையுடன் உள்நுழைவைத் தடு',
        'cb_verified' => 'சரிபார்க்கப்பட்ட மின்னஞ்சல் claim தேவை',
        'cb_verified_desc' => 'வழங்குநர் {claim} அனுப்பாவிட்டால் உள்நுழைவை மறுக்கும். claim-ஐ முழுமையாகத் தவிர்க்கும் வழங்குநர்களுக்கு (எ.கா. Okta-வின் org server) அணைத்து வைக்கவும். வெளிப்படையான {claim_false} இந்த அமைப்பைப் பொருட்படுத்தாமல் எப்போதும் மறுக்கப்படும். பயனர்கள் சரிபார்க்கப்படாத முகவரிகளுடன் தாங்களே பதிவு செய்யக்கூடிய IdP-களுக்கு மட்டுமே இயக்கவும்.',
        'field_profile_sync_mode' => 'சுயவிவரப் பண்பு ஒத்திசைவு',
        'field_profile_sync_mode_hint' => 'உள்நுழையும்போது IdP claims-இலிருந்து பயனர் சுயவிவரப் பண்புகள் (பெயர், பதவி, துறை, அலுவலகம், தொலைபேசி) எவ்வாறு புதுப்பிக்கப்படுகின்றன.',
        'profile_sync_always' => 'ஒவ்வொரு உள்நுழைவிலும் IdP-இலிருந்து ஒத்திசை',
        'profile_sync_initial' => 'கணக்கு உருவாக்கும்போது ஒத்திசை, பின்னர் உள்ளூர்த் திருத்தங்களை அனுமதி',
        'profile_sync_never' => 'பண்புகளை ஒருபோதும் ஒத்திசைக்காதே (சுயவிவரத்தை உள்ளூரில் நிர்வகி)',
        'field_default_modules' => 'தானாக உருவாக்கப்பட்ட பகுப்பாய்வாளர்களுக்கான இயல்புநிலை தொகுதி அணுகல்',
        'field_jit_company' => 'தானாக உருவாக்கப்பட்ட பகுப்பாய்வாளர்களுக்கான நிறுவன அணுகல்',
        'field_jit_company_hint' => 'இந்த வழங்குநரால் உருவாக்கப்படும் பகுப்பாய்வாளர் எந்த நிறுவனங்களைப் பார்க்கலாம். கணக்கு உருவாக்கப்படும்போது மட்டுமே பொருந்தும்; பின்னர் System → Analysts-இல் மாற்றவும்.',
        'jit_company_all' => 'ஒவ்வொரு நிறுவனமும் (முன்பு போல)',
        'jit_company_provider' => 'இந்த வழங்குநரின் நிறுவனம் மட்டும் (பொது வழங்குநருக்கு இயல்புநிலை நிறுவனம்)',
        'jit_company_none' => 'நிர்வாகி சிலவற்றை வழங்கும் வரை எதுவுமில்லை',
        'tab_groups' => 'குழுக்களும் அணிகளும்',
        'tab_portal' => 'போர்டலும் நிறுவனமும்',
        'claims_intro' => 'விருப்பத்தேர்வு. யார் பகுப்பாய்வாளராக இருக்கலாம், யார் நிர்வாகி, மக்கள் எந்தக் குழுக்களில் இருக்கிறார்கள் என்பதை முடிவு செய்ய உங்கள் அடையாள வழங்குநர் அனுப்பும் குழுக்களைப் பயன்படுத்தவும். ஒவ்வொரு உள்நுழைவிலும் மீண்டும் சரிபார்க்கப்படும், எனவே அணுகல் அடையாள வழங்குநரைப் பின்தொடரும். ஒரு குழு என்ன செய்யலாம் என்பது System → Teams-இல் அமைக்கப்படுகிறது.',
        'field_group_claim' => 'குழுக்கள் எங்கிருந்து வருகின்றன',
        'field_group_claim_hint' => 'குழுக்களைப் பட்டியலிடும் உள்நுழைவின் பகுதி. பெரும்பாலான வழங்குநர்கள் இதை groups என்று அழைக்கிறார்கள்; Keycloak realm_access.roles பயன்படுத்துகிறது. இதை அனுப்ப உங்கள் வழங்குநரை அமைக்க வேண்டியிருக்கலாம் - உதவியைப் பார்க்கவும்.',
        'claims_guide' => 'படிப்படியான அமைவு வழிகாட்டி',
        'claims_guide_hint' => 'Microsoft Entra, Okta மற்றும் Keycloak-க்கான சரிபார்ப்புப் பட்டியலுடன். புதிய தாவலில் திறக்கும்.',
        'claims_off' => 'பயன்படுத்தப்படவில்லை',
        'claims_other' => 'வேறொன்று…',
        'claims_other_ph' => 'உங்கள் வழங்குநர் பயன்படுத்தும் பெயர்',
        'group_pick_ph' => 'ஒரு குழுவைத் தேர்ந்தெடுக்கவும் அல்லது தட்டச்சு செய்யவும்',
        'group_none' => '- எதுவுமில்லை -',
        'group_type' => 'ஒரு குழுவைத் தட்டச்சு செய்யவும்…',
        'group_type_ph' => 'உங்கள் வழங்குநர் அனுப்புவது போலவே குழுவின் பெயர்',
        'group_unseen_tag' => 'இன்னும் எந்த உள்நுழைவிலும் காணப்படவில்லை',
        'group_name_ph' => 'ஒரு பெயர் கொடுக்கவும், எ.கா. IT staff',
        'field_groups_seen' => 'காணப்பட்ட குழுக்கள்',
        'field_groups_seen_hint' => 'இந்த வழங்குநர் ஏதேனும் உள்நுழைவில் அனுப்பிய ஒவ்வொரு குழுவும். Microsoft போன்ற சில வழங்குநர்கள் பெயர்களுக்குப் பதிலாக குறியீடுகளை அனுப்புகிறார்கள் - ஒவ்வொன்றுக்கும் இங்கே ஒரு பெயர் கொடுங்கள், கீழுள்ள கீழ்விரிகள் அந்தப் பெயரைக் காட்டும். உங்கள் வழங்குநரில் குழுவின் பெயருக்கு அருகில் குறியீட்டைக் காணலாம் (Microsoft Entra-வில்: Groups, அந்தக் குழு, Object ID).',
        'col_code' => 'குறியீடு',
        'col_group_name' => 'பெயர்',
        'col_last_seen' => 'கடைசியாகக் காணப்பட்டது',
        'group_not_seen' => 'இந்தக் குழுவுடன் இதுவரை யாரும் உள்நுழையவில்லை - உங்கள் வழங்குநர் அனுப்புவது போலவே துல்லியமாக எழுதப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.',
        'field_claim_analyst_group' => 'பகுப்பாய்வாளர் குழு',
        'field_claim_analyst_group_hint' => 'இந்தக் குழுவில் உள்ளவர்கள் மட்டுமே பகுப்பாய்வாளர்களாக உள்நுழையலாம், அவர்கள் மட்டுமே தானாக உருவாக்கப்படுவார்கள். குழுவிலிருந்து விலகுபவர் அடுத்த உள்நுழைவில் மறுக்கப்படுவார். காலியாக விட்டால், இந்த வழங்குநர் உள்நுழைவிக்கும் எவரும் இப்போது இருப்பது போலவே பகுப்பாய்வாளராக இருக்கலாம்.',
        'field_claim_admin_group' => 'நிர்வாகி குழு',
        'field_claim_admin_group_hint' => 'இந்தக் குழுவில் உள்ளவர்கள் நிர்வாகிகள்; இல்லாதவர்கள் இல்லை. நிர்வாகிகளைக் கைமுறையாக நிர்வகிக்க காலியாக விடவும். கடைசி நிர்வாகி ஒருபோதும் அகற்றப்பட மாட்டார்.',
        'field_group_teams' => 'குழுக்கள்',
        'field_group_teams_hint' => 'ஒவ்வொரு உள்நுழைவிலும், மக்கள் தங்கள் குழுக்கள் சுட்டும் அணிகளில் சேர்க்கப்படுவார்கள், குழுவிலிருந்து விலகும்போது இந்த அணிகளிலிருந்து நீக்கப்படுவார்கள். இங்கே பட்டியலிடப்படாத அணிகள் ஒருபோதும் மாற்றப்படாது. இந்த வழங்குநர் உருவாக்கும் பகுப்பாய்வாளர்கள் தங்கள் தொகுதிகளை இந்த அணிகளிலிருந்து பெறுகிறார்கள்.',
        'col_group' => 'குழு',
        'col_team' => 'அணி',
        'map_add' => 'சேர்',
        'map_remove' => 'அகற்று',
        'choose_team' => 'ஒரு அணியைத் தேர்ந்தெடுக்கவும்',
        'inactive' => 'செயலற்றது',
        'no_teams' => 'இன்னும் அணிகள் இல்லை. System → Teams-இல் அவற்றை உருவாக்கி, பின்னர் குழுக்களை இணைக்க இங்கே திரும்பி வாருங்கள்.',
        'go_teams' => 'அணிகளைத் திற',
        'claims_last_seen' => 'கடைசி உள்நுழைவு ({who}, {at}) அனுப்பியது: {groups}',
        'claims_none_sent' => 'அந்தப் பகுதியில் எதுவுமில்லை',
        'claims_not_yet' => 'இது அமைக்கப்பட்ட பிறகு யாரும் உள்நுழையவில்லை, எனவே தேர்ந்தெடுக்க இன்னும் குழுக்கள் இல்லை. இந்த வழங்குநர் வழியாக ஒருமுறை உள்நுழைந்து, பின்னர் திரும்பி வாருங்கள்.',
        'field_default_modules_hint' => 'JIT மூலம் உருவாக்கப்பட்ட பகுப்பாய்வாளர்களுக்கு வழங்கப்படும் காற்புள்ளியால் பிரிக்கப்பட்ட தொகுதி விசைகள் (எ.கா. {example}). {strong} — தானாக உருவாக்கப்பட்ட பகுப்பாய்வாளர்கள் நிர்வாகிகளாக இருக்காதபடி சோதனைகளுக்கு இதை அமைக்கவும்.',
        'field_default_modules_strong' => 'காலியாக விட்டால் அவர்களுக்கு ஒவ்வொரு தொகுதிக்கும் முழு அணுகல் கிடைக்கும்',
        'field_default_modules_placeholder' => 'tickets, knowledge',
        'field_company' => 'நிறுவனம்',
        'field_company_hint' => 'இந்த அடையாள வழங்குநர் எந்த வாடிக்கையாளர் நிறுவனத்துக்குச் சொந்தம் — சுய-சேவை போர்டலில் அதன் கோரிக்கையாளர்கள் இங்கே அனுப்பப்படுவார்கள். MSP-உள் வழங்குநருக்கு (எ.கா. பகுப்பாய்வாளர் உள்நுழைவு) பொது என்றே விடவும்.',
        'field_company_global' => 'பொது (உள் / அனைத்தும்)',
        'field_portal_domains' => 'மின்னஞ்சல் டொமைன்கள்',
        'field_portal_domains_hint' => 'ஒரு வரிக்கு ஒன்று, எ.கா. company.com. போர்டலில், இந்த டொமைன்களில் ஒன்றிலுள்ள மின்னஞ்சல் முகவரி முதல் முறையிலேயே நேராக இந்த வழங்குநருக்குச் செல்லும். இன்று கடவுச்சொல்லுடன் உள்நுழைபவர்களும் இதில் அடங்குவர். மற்றவர்களுக்கு வழக்கம்போல் கடவுச்சொல் பெட்டி கிடைக்கும். துணை டொமைனுக்குத் தனி வரி தேவை. யாரையும் அனுப்பாமல் இருக்க காலியாக விடவும்.',
        'cb_portal_show_button' => 'போர்டல் உள்நுழைவில் பொத்தானைக் காட்டு',
        'cb_portal_show_button_desc' => 'மின்னஞ்சல் பெட்டி மட்டும் உள்ள பக்கத்துக்கு தேர்வை நீக்கவும். மேலுள்ள டொமைன்களில் உள்ளவர்கள் அதன் வழியாக இன்னும் இந்த வழங்குநரை அடைவார்கள். பகுப்பாய்வாளர் உள்நுழைவு பாதிக்கப்படாது.',
        'cancel' => 'ரத்து',
        'field_protocol' => 'வகை',
        'field_protocol_hint' => 'இந்த வழங்குநருடன் மக்கள் எவ்வாறு உள்நுழைகிறார்கள்.',
        'protocol_oidc' => 'OpenID Connect (single sign-on)',
        'protocol_ldap' => 'LDAP / Active Directory',
        'protocol_carddav' => 'CardDAV முகவரிப் புத்தகம் (தொடர்புகள் மட்டும், உள்நுழைவு இல்லை)',
        'field_carddav_url' => 'சேவையகத்தின் முகவரி',
        'field_carddav_url_hint' => 'CardDAV பாதை, இணையப் பக்கம் அல்ல. Baïkal, Nextcloud அல்லது வேறொரு sabre/dav சேவையகத்தில் இது பொதுவாக https://dav.example.com/dav.php/addressbooks/jsmith/ போல இருக்கும் — உங்கள் முகவரிப் புத்தகங்களை வைத்திருக்கும் நிலைக்குச் சுட்டவும், இணைப்பைச் சோதி கண்டுபிடிப்பவற்றைப் பட்டியலிடும்.',
        'field_carddav_username' => 'பயனர்பெயர்',
        'field_carddav_username_hint' => 'தொடர்புகளைப் படிக்கக்கூடிய முகவரிப் புத்தக சேவையகத்தில் உள்ள கணக்கு. இப்போதைக்கு படிக்க-மட்டும் கணக்கே போதும்.',
        'field_carddav_password' => 'கடவுச்சொல்',
        'field_carddav_password_hint' => 'குறியாக்கம் செய்து சேமிக்கப்படும், சேமித்த பிறகு மீண்டும் காட்டப்படாது.',
        'carddav_password_stored_hint' => 'கடவுச்சொல் சேமிக்கப்பட்டுள்ளது. வைத்திருக்க காலியாக விடவும்.',
        'field_carddav_auth' => 'அங்கீகாரம்',
        'field_carddav_auth_hint' => 'காரணம் இல்லாவிட்டால் இதை தானியங்கி என்றே விடவும். நிலையான Baïkal உட்பட பெரும்பாலான சேவையகங்கள் Basic-ஐ விட Digest-ஐ விரும்புகின்றன — தானியங்கி சேவையகத்திடம் கேட்டு அது வழங்குவதைப் பயன்படுத்தும்.',
        'carddav_auth_auto' => 'தானியங்கி (பரிந்துரைக்கப்படுகிறது)',
        'carddav_auth_digest' => 'Digest',
        'carddav_auth_basic' => 'Basic',
        'field_carddav_book' => 'முகவரிப் புத்தகம்',
        'field_carddav_book_hint' => 'தொடர்புகளை எந்த முகவரிப் புத்தகத்திலிருந்து படிப்பது. இணைப்பைச் சோதி அழுத்தினால், உங்கள் கணக்கு பார்க்கக்கூடிய புத்தகங்களால் இது நிரம்பும்.',
        'carddav_book_untested' => 'உங்கள் முகவரிப் புத்தகங்களைக் காண இணைப்பைச் சோதி அழுத்தவும்',
        'carddav_book_required' => 'ஒரு முகவரிப் புத்தகத்தைத் தேர்ந்தெடுக்கவும். அவற்றைப் பட்டியலிட முதலில் இணைப்பைச் சோதி அழுத்தவும்.',
        'carddav_url_required' => 'முதலில் உங்கள் CardDAV சேவையகத்தின் முகவரியை உள்ளிடவும்.',
        'carddav_test' => 'இணைப்பைச் சோதி',
        'carddav_test_desc' => 'FreeITSM சேவையகத்தை அடைந்து உள்நுழைய முடிகிறதா எனச் சரிபார்த்து, அது பார்க்கக்கூடிய முகவரிப் புத்தகங்களைப் பட்டியலிடும்.',
        'carddav_test_desc_create' => 'இந்த விவரங்களுடன் FreeITSM சேவையகத்தை அடைந்து உள்நுழைய முடிகிறதா எனச் சரிபார்க்கும்.',
        'carddav_test_next' => 'இதைச் சேமித்து, பின்னர் அதன் வரிசையிலுள்ள அமைப்புகள் ஐகானைப் பயன்படுத்தி ஒரு முகவரிப் புத்தகத்தையும் எந்தத் தொடர்புகளை உள்ளே கொண்டுவருவது என்பதையும் தேர்ந்தெடுக்கவும்.',
        'carddav_page_sub' => 'ஒரு CardDAV முகவரிப் புத்தகம். இதன் வழியாக யாரும் உள்நுழைவதில்லை — இது உங்கள் service desk-க்குத் தொடர்புகளைக் கொண்டுவருகிறது.',
        'tab_contacts' => 'தொடர்புகள்',
        'field_carddav_groups' => 'உள்ளே கொண்டுவர வேண்டிய குழுக்கள்',
        'field_carddav_categories' => 'உள்ளே கொண்டுவர வேண்டிய குறிச்சொற்கள்',
        'carddav_pick_all' => 'அனைத்தையும் தேர்ந்தெடு',
        'carddav_pick_none' => 'அழி',
        'carddav_pick_summary' => 'தேர்ந்தெடுக்கப்பட்டவை: {n}',
        'carddav_pick_summary_none' => 'இன்னும் எதுவும் தேர்ந்தெடுக்கப்படவில்லை.',
        'carddav_write_heading' => 'மாற்றங்களைத் திருப்பி அனுப்புதல்',
        'carddav_write_hint' => 'பொதுவாக FreeITSM இந்த முகவரிப் புத்தகத்தை படிக்க மட்டுமே செய்யும். இதை இயக்கினால், பகுப்பாய்வாளர் ஒரு தொடர்பின் பதவி, துறை, அலுவலகம், தொலைபேசி அல்லது கைப்பேசியில் செய்யும் மாற்றம் அவர்களின் கார்டிலும் எழுதப்படும். அவர்களின் employee ID மற்றும் மேலாளர் FreeITSM-இலேயே இருக்கும், ஏனெனில் தொடர்பு கார்டில் அவற்றை வைக்க இடமில்லை.',
        'carddav_write_back' => 'FreeITSM-இல் செய்யப்படும் மாற்றங்களை முகவரிப் புத்தகத்துக்கு எழுது',
        'carddav_allow_create' => 'இந்த முகவரிப் புத்தகத்தில் ஆட்களைச் சேர்க்க பகுப்பாய்வாளர்களை அனுமதி',
        'carddav_allow_create_hint' => 'இயல்பாக அணைந்திருக்கும். இயக்கினால், எந்த முகவரிப் புத்தகத்திலும் இல்லாத ஒருவருக்கு Tickets மற்றும் Assets-இல் Add to address book பொத்தான் கிடைக்கும்; அது இங்கே அவர்களின் கார்டை உருவாக்கி அவர்களை இணைக்கும். எதையும் எழுதுவதற்கு முன், புத்தகத்தில் ஏற்கனவே அவர்களின் மின்னஞ்சல் முகவரி உள்ளவர் இல்லை என FreeITSM சரிபார்க்கும்; பின்னர் புதிய கார்டு இந்த மூலம் இறக்குமதி செய்யும் ஒன்றா எனச் சரிபார்க்கும் - இறக்குமதிக்குப் பயன்படும் குறிச்சொல் அல்லது குழுவைச் சேர்த்து - இல்லையெனில் அதை மீண்டும் நீக்கும்.',
        'carddav_write_warning' => 'மேலே பட்டியலிடப்பட்ட விவரங்கள் மட்டுமே, திருத்தப்படும் தொடர்பில் மட்டுமே மாற்றப்படும். கார்டிலுள்ள மற்ற அனைத்தும் — புகைப்படம், குறிப்புகள், பிறந்தநாள், முழு முகவரி, குழுக்கள் — அப்படியே விடப்படும். FreeITSM கடைசியாக இறக்குமதி செய்த பிறகு யாராவது முகவரிப் புத்தகத்தில் அதே விவரத்தை மாற்றியிருந்தால், அவர்களுடையதை மேலெழுதாமல் மாற்றம் நிராகரிக்கப்படும்.',
        'carddav_write_check' => 'அனுமதியைச் சரிபார்',
        'carddav_write_checking' => 'சேவையகத்திடம் கேட்கிறது…',
        'carddav_write_check_failed' => 'அனுமதிச் சரிபார்ப்பை முடிக்க முடியவில்லை.',
        'carddav_writelog_heading' => 'திருப்பி அனுப்பப்பட்ட மாற்றங்கள்',
        'carddav_writelog_hint' => 'FreeITSM ஒரு தொடர்பு கார்டைப் புதுப்பிக்க முயன்ற ஒவ்வொரு முறையும், என்ன நடந்தது என்பதும். நிராகரிக்கப்பட்ட மாற்றம் பிழை அல்ல — முகவரிப் புத்தகத்தில் யாரோ ஏற்கனவே அதே விவரத்தை மாற்றியிருந்தார்கள், FreeITSM அதை மேலெழுதவில்லை என்று பொருள்.',
        'carddav_writelog_none' => 'இந்த முகவரிப் புத்தகத்துக்கு இதுவரை எந்த மாற்றமும் அனுப்பப்படவில்லை.',
        'carddav_writelog_failed' => 'பதிவை ஏற்ற முடியவில்லை.',
        'wl_when' => 'எப்போது',
        'wl_person' => 'நபர்',
        'wl_outcome' => 'முடிவு',
        'wl_fields' => 'மாற்றப்பட்டவை',
        'wl_detail' => 'விவரம்',
        'wl_out_ok' => 'எழுதப்பட்டது',
        'wl_out_conflict' => 'நிராகரிக்கப்பட்டது',
        'wl_out_failed' => 'தோல்வி',
        'wl_out_skipped' => 'அனுப்ப எதுவுமில்லை',
        'wl_out_created' => 'சேர்க்கப்பட்டது',
        'wl_raw' => 'சேவையகம் கூறியது (HTTP {status})',
        'wl_no_body' => 'சேவையகம் தனது பதிலுடன் எந்தச் செய்தியையும் அனுப்பவில்லை.',
        'carddav_run_heading' => 'தொடர்புகளை உள்ளே கொண்டுவரு',
        'carddav_run_hint' => 'முன்னோட்டம் முகவரிப் புத்தகத்தைப் படித்து, எதையும் மாற்றாமல் அது என்ன செய்யும் என்பதைத் துல்லியமாகச் சொல்லும். இயக்கு அதையே உண்மையாகச் செய்யும்.',
        'carddav_preview' => 'முன்னோட்டம்',
        'carddav_run' => 'இயக்கு',
        'carddav_previewing' => 'முகவரிப் புத்தகத்தைப் படிக்கிறது…',
        'carddav_running' => 'இறக்குமதி செய்கிறது…',
        'carddav_preview_prefix' => 'எதுவும் மாற்றப்படவில்லை. இயக்கினால் இது நடக்கும்:',
        'carddav_run_failed' => 'இறக்குமதியை இயக்க முடியவில்லை.',
        'carddav_run_confirm_all' => 'இது அந்த முகவரிப் புத்தகத்திலுள்ள ஒவ்வொரு தொடர்பையும் உங்கள் service desk-க்குக் கொண்டுவந்து, அதிலிருந்து அவற்றைப் புதுப்பித்த நிலையில் வைக்கும். அதே மின்னஞ்சல் முகவரியுடன் ஏற்கனவே இங்கே உள்ளவர்கள் அதனுடன் இணைக்கப்படுவார்கள். யாரும் ஒருபோதும் நீக்கப்பட மாட்டார்கள்.',
        'carddav_run_confirm_scoped' => 'இது நீங்கள் தேர்ந்தெடுத்த தொடர்புகளை உங்கள் service desk-க்குக் கொண்டுவந்து, முகவரிப் புத்தகத்திலிருந்து அவற்றைப் புதுப்பித்த நிலையில் வைக்கும். அதே மின்னஞ்சல் முகவரியுடன் ஏற்கனவே இங்கே உள்ளவர்கள் அதனுடன் இணைக்கப்படுவார்கள். யாரும் ஒருபோதும் நீக்கப்பட மாட்டார்கள்.',
        'carddav_history_hint' => 'ஒவ்வொரு இறக்குமதியும், அது என்ன செய்தது என்பதும். நிறுத்தப்பட்டது எனக் காட்டப்படும் இயக்கம் பாதுகாப்புச் சரிபார்ப்பால் நிறுத்தப்பட்டது; அதாவது எதுவும் மாற்றப்படவில்லை.',
        'hist_scheduled' => 'திட்டமிடப்பட்டது',
        'carddav_test_running' => 'இணைக்கிறது…',
        'carddav_test_failed' => 'இணைப்பைச் சோதிக்க முடியவில்லை.',
        'carddav_test_auth' => 'சேவையகம் {scheme} அங்கீகாரத்தைப் பயன்படுத்துகிறது.',
        'carddav_test_pick' => 'மேலே முகவரிப் புத்தகத்தில் ஒன்றைத் தேர்ந்தெடுத்து, பின்னர் சேமி.',
        'field_carddav_scope' => 'எந்தத் தொடர்புகளை உள்ளே கொண்டுவருவது',
        'field_carddav_scope_hint' => 'முகவரிப் புத்தகங்களில் பெரும்பாலும் உங்கள் service desk-க்குத் தேவைப்படுவதை விட அதிகம் இருக்கும். இணைப்பைச் சோதி அழுத்தினால், நீங்கள் தேர்ந்தெடுத்த புத்தகத்தின் உள்ளே FreeITSM பார்த்து, கண்டதை — குழுக்கள், குறிச்சொற்கள் அல்லது எல்லாவற்றையும் — வழங்கும்.',
        'carddav_scope_all' => 'இந்த முகவரிப் புத்தகத்திலுள்ள அனைத்தும்',
        'carddav_scope_group' => 'ஒரு குழுவின் உறுப்பினர்கள் மட்டும்',
        'carddav_scope_category' => 'குறிப்பிட்ட குறிச்சொல் உள்ள தொடர்புகள் மட்டும்',
        'carddav_scope_group_none' => 'ஒரு குழுவின் உறுப்பினர்கள் மட்டும் (இந்த முகவரிப் புத்தகத்தில் எதுவுமில்லை)',
        'carddav_scope_category_none' => 'குறிப்பிட்ட குறிச்சொல் உள்ள தொடர்புகள் மட்டும் (இந்த முகவரிப் புத்தகத்தில் எதுவுமில்லை)',
        'field_carddav_scope_value' => 'எது',
        'field_carddav_group' => 'குழு',
        'field_carddav_category' => 'குறிச்சொல்',
        'carddav_group_option' => '{name}  ({n})',
        'carddav_category_option' => '{name}  ({n})',
        'carddav_scope_untested' => 'இந்த முகவரிப் புத்தகத்தில் என்ன உள்ளது எனக் காண இணைப்பைச் சோதி அழுத்தவும்',
        'carddav_scope_untested_hint' => 'முகவரிப் புத்தகத்தில் என்ன உள்ளது என்பதை அறிய FreeITSM அதைப் படிக்கிறது, எனவே சோதித்த பிறகு இது நிரம்பும்.',
        'carddav_scope_none' => 'இந்த முகவரிப் புத்தகத்தில் எதுவும் இல்லை',
        'carddav_scope_none_hint' => 'FreeITSM முகவரிப் புத்தகத்தைப் படித்து இவற்றில் எதுவும் இல்லை எனக் கண்டது, எனவே தேர்ந்தெடுக்க எதுவுமில்லை. அதற்குப் பதிலாக "இந்த முகவரிப் புத்தகத்திலுள்ள அனைத்தும்" என்பதைத் தேர்ந்தெடுக்கவும், அல்லது முதலில் உங்கள் முகவரிப் புத்தக சேவையகத்தில் குழுவாக்கத்தை அமைக்கவும்.',
        'carddav_scope_required' => 'உள்ளே கொண்டுவர வேண்டிய குழு அல்லது குறிச்சொல்லைத் தேர்ந்தெடுக்கவும், அல்லது முகவரிப் புத்தகத்திலுள்ள அனைத்துக்கும் மாறவும்.',
        'carddav_book_changed' => 'முகவரிப் புத்தகம் மாறியது — அதன் உள்ளே என்ன உள்ளது எனக் காண இணைப்பைச் சோதி மீண்டும் அழுத்தவும்.',
        'carddav_test_scan' => 'அந்த முகவரிப் புத்தகத்தின் உள்ளே பார்க்கப்பட்டது — தொடர்புகள்: {contacts}, குழுக்கள்: {groups}, குறிச்சொற்கள்: {categories}.',
        'carddav_scan_failed' => 'இணைக்கப்பட்டது, ஆனால் அந்த முகவரிப் புத்தகத்தின் உள்ளடக்கத்தைப் படிக்க முடியவில்லை: {error}',
        'col_type' => 'வகை',
        'ldap_badge' => 'LDAP',
        'oidc_badge' => 'OIDC',
        'carddav_badge' => 'CardDAV',
        'ldap_preset' => 'முன்னமைவு',
        'ldap_preset_hint' => 'உங்கள் டைரக்டரிக்கான வழக்கமான வடிகட்டி மற்றும் பண்புப் பெயர்களை நிரப்பும். கீழே உள்ள எதையும் நீங்கள் இன்னும் மாற்றலாம்.',
        'ldap_preset_ad' => 'Active Directory',
        'ldap_preset_openldap' => 'OpenLDAP',
        'ldap_preset_applied' => 'முன்னமைவு பயன்படுத்தப்பட்டது',
        'field_ldap_host' => 'சேவையகம்',
        'field_ldap_host_hint' => 'domain controller-இன் ஹோஸ்ட்பெயர் அல்லது IP, எ.கா. dc1.example.local',
        'field_ldap_port' => 'Port',
        'field_ldap_encryption' => 'குறியாக்கம்',
        'ldap_enc_none' => 'எதுவுமில்லை (plain LDAP)',
        'ldap_enc_starttls' => 'STARTTLS',
        'ldap_enc_ldaps' => 'LDAPS (SSL)',
        'ldap_enc_hint' => 'ஒவ்வொரு உள்நுழைவிலும் கடவுச்சொற்கள் நெட்வொர்க் வழியாகச் செல்கின்றன. production-இல் STARTTLS அல்லது LDAPS பயன்படுத்தவும் — பல Active Directory சேவையகங்கள் plain LDAP-இல் கடவுச்சொல் bind-ஐ எப்படியும் மறுக்கின்றன.',
        'field_ldap_bind_dn' => 'சேவைக் கணக்கு',
        'field_ldap_bind_dn_hint' => 'பயனர்களைத் தேட நாங்கள் bind செய்யும் படிக்க-மட்டும் கணக்கு — மக்கள் உள்நுழைவது இதன் மூலம் அல்ல. Active Directory user@domain ஏற்கும்; OpenLDAP cn=svc,dc=example,dc=com போன்ற முழு DN-ஐ விரும்பும். பெயரறியாமல் தேட காலியாக விடவும் (அரிதாகவே அனுமதிக்கப்படும்).',
        'field_ldap_bind_password' => 'சேவைக் கணக்கின் கடவுச்சொல்',
        'field_ldap_bind_password_hint' => 'குறியாக்கம் செய்து சேமிக்கப்படும். இந்தக் கணக்குக்கு டைரக்டரியைப் படிக்க மட்டுமே அனுமதி தேவை — எழுத்து அணுகலை ஒருபோதும் வழங்காதீர்கள்.',
        'bind_password_stored_hint' => 'கடவுச்சொல் சேமிக்கப்பட்டுள்ளது. வைத்திருக்க காலியாக விடவும்.',
        'field_ldap_base_dn' => 'Base DN',
        'field_ldap_base_dn_hint' => 'மரத்தில் எங்கிருந்து தேடத் தொடங்க வேண்டும், எ.கா. DC=example,DC=local. சேவைக் கணக்கு இதைப் படிக்க அனுமதிக்கப்பட வேண்டும் — இல்லையெனில் பெரும்பாலான டைரக்டரிகள் அனுமதிப் பிழைக்குப் பதிலாக "no such object" எனக் காட்டும்.',
        'field_ldap_filter' => 'பயனர் வடிகட்டி',
        'field_ldap_filter_hint' => 'உள்நுழைபவரை நாங்கள் எவ்வாறு கண்டறிகிறோம். {token} என்பது அவர்கள் உள்ளிட்டதால் மாற்றப்படும்; எனவே பல பண்புகளைப் பட்டியலிட்டால் அவர்கள் பயனர்பெயர் அல்லது மின்னஞ்சல் முகவரி இரண்டில் எதையும் பயன்படுத்தலாம்.',
        'ldap_attrs_heading' => 'பண்புகள்',
        'ldap_attrs_desc' => 'டைரக்டரியின் எந்தப் புலங்கள் FreeITSM கணக்குடன் பொருந்துகின்றன. மேலே உள்ள முன்னமைவுகள் பெரும்பாலான தளங்களுக்குச் சரியானவை.',
        'field_ldap_attr_username' => 'பயனர்பெயர்',
        'field_ldap_attr_email' => 'மின்னஞ்சல்',
        'field_ldap_attr_name' => 'முழுப் பெயர்',
        'field_ldap_attr_guid' => 'தனித்துவ ID',
        'field_ldap_attr_guid_hint' => 'ஒருவர் மறுபெயரிடப்படும்போதோ நகர்த்தப்படும்போதோ FreeITSM கணக்குடனான இணைப்பைத் தக்கவைக்கப் பயன்படும், ஒருபோதும் மாறாத பண்பு. Active Directory-இல் {ad}, OpenLDAP-இல் {openldap}.',
        'ldap_groups_heading' => 'குழு மூலம் அணுகல்',
        'ldap_groups_desc' => 'அணுகலை வழங்கும் டைரக்டரி குழுக்களின் பெயரைக் குறிப்பிடவும். {strong} இரண்டு குழுக்களிலும் இல்லாதவர், சரியான கடவுச்சொல் இருந்தாலும் உள்நுழைய முடியாது — தானாக உருவாக்குதல் டைரக்டரியில் உள்ள ஒவ்வொரு ஊழியரையும் பகுப்பாய்வாளராக்குவதை இதுவே தடுக்கிறது.',
        'ldap_groups_desc_strong' => 'இரண்டையும் வெறுமையாக விட்டால், டைரக்டரி அறிந்த எவரும் பகுப்பாய்வாளராகிவிடுவார்.',
        'field_ldap_analyst_group' => 'பகுப்பாய்வாளர் குழு',
        'field_ldap_user_group' => 'சுய-சேவை பயனர் குழு',
        'field_ldap_group_filter' => 'குழு வடிகட்டி — ஒருவர் இருக்கும் குழுக்களை நாங்கள் எவ்வாறு கண்டறிகிறோம். %s என்பது அவர்களின் DN-ஆல் மாற்றப்படும்.',
        'field_ldap_group_base_dn' => 'குழு base DN (விருப்பத்தேர்வு — இயல்பாக மேலே உள்ள base DN)',
        'field_ldap_group_base_dn_placeholder' => 'OU=Groups,DC=example,DC=local',
        'ldap_test_groups' => 'குழுக்கள்: {groups}',
        'ldap_test_role' => 'அணுகல்: {role}',
        'ldap_role_analyst' => 'பகுப்பாய்வாளர்',
        'ldap_role_user' => 'சுய-சேவை பயனர்',
        'ldap_role_none' => 'மறுக்கப்பட்டது — எந்தக் குழுவிலும் இல்லை',
        'ldap_test_heading' => 'சோதனை',
        'ldap_test_desc' => 'சேமிப்பதற்கு முன் அமைப்புகளைச் சரிபார்க்கவும். சேவைக் கணக்கு இணைந்து base DN-ஐப் படிக்க முடிகிறதா என்பதை மட்டும் சோதிக்க, பயனரை வெறுமையாக விடவும்.',
        'tab_connection' => 'இணைப்பு',
        'tab_signin' => 'உள்நுழைவு',
        'tab_import' => 'நபர்களை இறக்குமதி செய்தல்',
        'tab_mapping' => 'புல இணைப்பு',
        'tab_history' => 'வரலாறு',
        'back_to_list' => 'அங்கீகாரத்துக்குத் திரும்பு',
        'configure' => 'உள்ளமை',
        'provider_page_sub' => 'இந்த டைரக்டரியுடன் FreeITSM எவ்வாறு இணைகிறது, இதன் மூலம் யார் உள்நுழையலாம், எந்த நபர்களை இறக்குமதி செய்வது என்பது.',
        'field_enabled' => 'இயக்கப்பட்டது',
        'field_auto_create' => 'நபர்கள் முதன்முறை உள்நுழையும்போது தானாக உருவாக்கு',
        'field_tenant' => 'நிறுவனம்',
        'tenant_all' => 'அனைத்து நிறுவனங்கள்',
        'field_ldap_user_filter' => 'பயனர் வடிகட்டி',
        'attrs_moved' => 'பண்புப் பெயர்கள் அனைத்தும் ஒன்றாக இங்கே உள்ளன:',
        'field_ldap_groups' => 'குழு அணுகல்',
        'field_ldap_groups_hint' => 'இந்தக் குழுக்களில் உள்ளவர்கள் மட்டுமே உள்நுழையலாம். டைரக்டரி அறிந்த எவரையும் அனுமதிக்க இரண்டையும் வெறுமையாக விடவும்.',
        'testing' => 'சோதிக்கிறது…',
        'history_heading' => 'இறக்குமதி வரலாறு',
        'history_hint' => 'முன்னோட்டங்கள் உட்பட ஒவ்வொரு இறக்குமதியும். பொத்தானை அழுத்துவதற்கு முன் ஒருவருக்குக் காட்டப்பட்டதை பின்னர் சரிபார்க்க முடிவது மதிப்புமிக்கது.',
        'history_none' => 'இந்த டைரக்டரியிலிருந்து இன்னும் எதுவும் இறக்குமதி செய்யப்படவில்லை.',
        'sync_scope' => 'எதை இறக்குமதி செய்வது',
        'hist_when' => 'எப்போது',
        'hist_mode' => 'வகை',
        'hist_result' => 'முடிவு',
        'hist_found' => 'கண்டறிந்தவை',
        'hist_added' => 'சேர்க்கப்பட்டவை',
        'hist_changed' => 'மாற்றப்பட்டவை',
        'hist_left' => 'விலகியவர்கள்',
        'hist_issues' => 'சிக்கல்கள்',
        'hist_by' => 'செய்தவர்',
        'sync_heading' => 'இந்த டைரக்டரியிலிருந்து நபர்களை இறக்குமதி செய்',
        'sync_desc' => 'உள்நுழைவு, ஒருவர் முதன்முறை உள்நுழையும்போது மட்டுமே அவரை உருவாக்கும். இறக்குமதி அனைவரையும் முன்கூட்டியே கொண்டுவரும்; எனவே ஒருபோதும் உள்நுழையாத நபர்களுக்கும் உபகரணங்களை ஒதுக்கலாம்.',
        'sync_enabled' => 'இந்த டைரக்டரியிலிருந்து நபர்களை இறக்குமதி செய்',
        'sync_base_dn_hint' => 'டைரக்டரியின் எந்தப் பகுதியிலிருந்து இறக்குமதி செய்வது. உள்நுழைவு தேடும் அதே இடத்தைப் பயன்படுத்த வெறுமையாக விடவும் — முழு டைரக்டரிக்கும் எதிராக அங்கீகரித்து, ஆனால் ஒரு பகுதியை மட்டும் இறக்குமதி செய்ய விரும்பினால் இதை அமைக்கவும்.',
        'sync_base_dn_placeholder' => 'OU=Staff,OU=Company,DC=example,DC=com',
        'sync_filter_hint' => 'எந்த உள்ளீடுகள் நபர்களாகக் கருதப்படும். இயல்புநிலை சாதாரண பயனர் கணக்குகளைக் கண்டறியும், கிட்டத்தட்ட எப்போதும் சரியானது.',
        'sync_conflict' => 'ஒருவர் ஏற்கனவே இங்கே இருக்கும்போது',
        'sync_conflict_hint' => 'டைரக்டரியில் உள்ள ஒருவர் அதே மின்னஞ்சல் முகவரியுடன் FreeITSM-இல் ஏற்கனவே இருந்தால். இணைத்தால் அவர்கள் டைரக்டரியுடன் இணைக்கப்படுவர் — அதன் பிறகு அவர்களின் FreeITSM போர்டல் கடவுச்சொல் வேலை செய்யாது; டைரக்டரி மூலம் உள்நுழைவர்.',
        'sync_conflict_adopt' => 'இந்த டைரக்டரியுடன் இணை',
        'sync_conflict_flag' => 'அவர்களைத் தொடாமல் விட்டு, எனக்குக் குறியிட்டுக் காட்டு',
        'sync_safety' => 'பாதுகாப்பு',
        'sync_deactivate_hint' => 'தொடர்ந்து இத்தனை இறக்குமதிகளில் டைரக்டரியில் காணப்படாத ஒருவரை விலகியவராகக் குறி. யாரும் ஒருபோதும் நீக்கப்படுவதில்லை. நபர்களைத் தானாக விலகியவராகக் குறிக்காமல் இருக்க 0 என அமைக்கவும்.',
        'sync_brake_hint' => 'கடந்த முறையை விட இத்தனை சதவீதம் குறைவான நபர்களை இறக்குமதி கண்டால், எதையும் மாற்றாமல் நிறுத்து. தவறான அமைப்போ டைரக்டரிச் சிக்கலோ அனைவரும் ஒரே நேரத்தில் விலகியது போலவே தோன்றும்; உங்கள் பட்டியல் காலியாவதை இதுவே தடுக்கிறது. சோதனையை அணைக்க 0 என அமைக்கவும்.',
        'sync_run_heading' => 'இப்போது இறக்குமதி செய்',
        'sync_run_hint' => 'முன்னோட்டம் என்ன நடக்கும் என்பதை சரியாகக் காட்டும், எதையும் மாற்றாது. ஒவ்வொரு முறையும் முதலில் இதைச் செய்வது நல்லது.',
        'sync_preview' => 'முன்னோட்டம்',
        'sync_run' => 'இப்போது இறக்குமதி செய்',
        'sync_preview_prefix' => 'முன்னோட்டம் மட்டுமே — எதுவும் மாற்றப்படவில்லை.',
        'sync_running' => 'செயல்படுகிறது…',
        'sync_save_first' => 'முதலில் இந்த டைரக்டரியைச் சேமித்து, பிறகு இறக்குமதி செய்யவும்.',
        'sync_confirm' => 'இந்த டைரக்டரியிலிருந்து இப்போது நபர்களை இறக்குமதி செய்யவா? இது நபர்களைச் சேர்த்து புதுப்பிக்கும், மேலும் சிலரை விலகியவராகக் குறிக்கக்கூடும். யாரும் ஒருபோதும் நீக்கப்படுவதில்லை.',
        'sync_found' => '{n} கண்டறியப்பட்டன',
        'sync_created' => '{n} சேர்க்கப்பட்டன',
        'sync_updated' => '{n} புதுப்பிக்கப்பட்டன',
        'sync_left' => '{n} விலகியவராகக் குறிக்கப்பட்டன',
        'ou_tree_hint' => 'இறக்குமதி செய்ய வேண்டிய டைரக்டரிப் பகுதிகளைத் தேர்ந்தெடுக்கவும். ஒரு கிளையைத் தேர்ந்தெடுத்தால் அதில் உள்ள அனைத்தும், பின்னர் சேர்க்கப்படுபவையும் உட்பட, எடுத்துக்கொள்ளப்படும் — எனவே அடுத்த ஆண்டு உருவாக்கப்படும் துறை தானாகவே வந்துவிடும். தேர்ந்தெடுத்த கிளைக்குள் உள்ள ஒன்றை விலக்க, அதன் தேர்வை நீக்கவும்.',
        'ou_browse' => 'டைரக்டரியை உலாவு',
        'ou_reading' => 'டைரக்டரியைப் படிக்கிறது…',
        'ou_read' => '{n} இடங்களும் {people} நபர்களும் கண்டறியப்பட்டன.',
        'ou_capped' => 'இந்த டைரக்டரி பெரியது. {n} நபர்களில் எண்ணிக்கை நிறுத்தப்பட்டது; எனவே கீழே உள்ள எண்கள் மொத்தமல்ல, குறைந்தபட்ச அளவே. இறக்குமதி பாதிக்கப்படவில்லை.',
        'ou_none_found' => 'பைண்ட் கணக்கு டைரக்டரியை அடைய முடிகிறது, ஆனால் base DN-க்குக் கீழே பட்டியலிட எதுவும் கிடைக்கவில்லை. உள்நுழைவு தாவலில் base DN-ஐச் சரிபார்க்கவும்.',
        'ou_selected' => '{n} நபர்கள் தேர்ந்தெடுக்கப்பட்டனர்.',
        'ou_none_selected' => 'இன்னும் எதுவும் தேர்ந்தெடுக்கப்படவில்லை.',
        'ou_count' => 'இங்கே {here} · கிளையில் {total}',
        'ou_count_empty' => 'காலி',
        'ou_manual' => 'அதற்குப் பதிலாக தொடக்கப் புள்ளியை உள்ளிடு',
        'ou_manual_ignored' => 'பயன்பாட்டில் இல்லை: மேலே இடங்களைத் தேர்ந்தெடுத்துள்ளீர்கள், அவையே முன்னுரிமை பெறும். இந்தப் பெட்டியைப் பயன்படுத்த அனைத்தின் தேர்வையும் நீக்கவும்.',
        'run_modal_preview' => 'இந்த இறக்குமதி என்ன செய்யும்',
        'run_modal_live' => 'இந்த இறக்குமதி என்ன செய்தது',
