        'run_none' => 'இந்த ஓட்டம் எதையும் பதிவு செய்யவில்லை.',
        'run_none_stopped' => 'பாதுகாப்புத் தடை எதையும் மாற்றும் முன் இந்த ஓட்டத்தை நிறுத்தியது; எனவே காட்ட எதுவும் இல்லை. எதை எதிர்த்தது என்பதை நபர்களை இறக்குமதி செய்தல் தாவலில் உள்ள முடிவு கூறுகிறது.',
