        'act_did_error' => 'சிக்கல்',
        'map_desc' => 'டைரக்டரியில் உள்ள எந்த விவரம் FreeITSM-இல் எந்த விவரமாகும். உங்கள் டைரக்டரி வகைக்கான நிலையான பெயரைப் பயன்படுத்த ஒரு பெட்டியை வெறுமையாக விடவும், அல்லது அந்த விவரத்தை இறக்குமதி செய்வதையே நிறுத்த அதை அழிக்கவும்.',
