        'map_hint_username' => 'உள்நுழைய அவர்கள் உள்ளிடுவது.',
        'map_field_email' => 'மின்னஞ்சல்',
        'map_hint_email' => 'ஏற்கனவே உள்ள FreeITSM நபரை டைரக்டரி நபருடன் பொருத்தும் முறையும் இதுவே.',
        'map_field_guid' => 'தனித்துவ id',
        'map_hint_guid' => 'ஒருவர் மறுபெயரிடப்படும்போதோ நகர்த்தப்படும்போதோ மாறாமல் இருக்கும் மதிப்பு. இறக்குமதிக்குப் பிறகு இதை மாற்றினால் அனைவரும் மறு-அடையாளம் காணப்படுவர்; எனவே ஒருமுறை அமைத்து விட்டுவிடுங்கள்.',
        'map_field_job_title' => 'பணிப் பெயர்',
