        'map_field_mobile' => 'மொபைல்',
        'map_hint_mobile' => '',
        'map_field_employee_id' => 'பணியாளர் எண்',
        'map_hint_employee_id' => 'டைரக்டரியில் இருந்தால், உங்கள் சம்பளப்பட்டியல் அல்லது HR குறிப்பு எண்.',
        'map_field_manager' => 'மேலாளர்',
        'map_hint_manager' => 'டைரக்டரி உள்ளீடாகப் படிக்கப்பட்டு, மற்ற அனைவரும் இறக்குமதி செய்யப்பட்ட பிறகு அது சுட்டும் நபருடன் பொருத்தப்படும்.',
        'map_test_heading' => 'இணைப்பைச் சரிபார்',
        'map_test_hint' => 'ஒரு உண்மையான நபரைப் படித்து, ஒவ்வொரு புலமும் உண்மையில் எதை இறக்குமதி செய்யும் என்பதைக் காட்டுகிறது. எதுவும் சேமிக்கப்படாது, எதுவும் மாற்றப்படாது. உங்களுக்குத் தெரிந்த ஒருவரைச் சரிபார்க்க அவர் பெயரை உள்ளிடவும், அல்லது முதலில் வருபவருக்கு வெறுமையாக விடவும்.',
        'map_test_sample' => 'சரிபார்க்க வேண்டியவரின் உள்நுழைவுப் பெயர் (விருப்பத்தேர்வு)',
        'map_test' => 'சோதனை',
        'map_testing' => 'டைரக்டரியிலிருந்து ஒரு நபரைப் படிக்கிறது…',
        'map_not_mapped' => 'இறக்குமதி செய்யப்படாது',
        'map_empty' => 'எதுவும் இல்லை',
        'map_result_ok' => '{name} படிக்கப்பட்டது. இணைக்கப்பட்ட ஒவ்வொரு புலத்திலும் மதிப்பு கிடைத்தது.',
        'map_result_skipped' => '{name} படிக்கப்பட்டது, ஆனால் இறக்குமதி அவர்களைத் தவிர்க்கும்: உள்நுழைவுப் பெயருக்கும் தனித்துவ id-க்கும் மதிப்பு கிடைக்கவில்லை. முதலில் அந்த இரண்டையும் சரிசெய்யவும் — அவை தீரும் வரை வேறெதுவும் முக்கியமில்லை.',
        'map_result_gaps' => '{name} படிக்கப்பட்டது. இணைக்கப்பட்ட {n} புலம்(புலங்கள்) எதுவும் கண்டறியவில்லை — பண்புப் பெயர் தவறாக இருக்கலாம், அல்லது இந்த நபருக்கு அது நிரப்பப்படாமல் இருக்கலாம். அவர்களிடம் என்ன உள்ளது என்பதைக் காண கீழே உள்ள பட்டியலைத் திறக்கவும்.',
        'map_available' => 'இந்த நபரிடம் உள்ள அனைத்து {n} பண்புகள்',
        'ldap_test_user' => 'சோதனைப் பயனர்பெயர் (விருப்பத்தேர்வு)',
        'ldap_test_pass' => 'சோதனைக் கடவுச்சொல்',
