        'ldap_required_fields' => 'சர்வர், base DN மற்றும் பயனர் வடிகட்டி தேவை',
        'ldap_ext_missing' => 'இந்த சர்வரில் PHP "ldap" நீட்டிப்பு இயக்கப்படவில்லை; எனவே LDAP வழங்குநர்களை இன்னும் பயன்படுத்த முடியாது. php.ini-இல் extension=ldap-ஐ இயக்கி, வெப் சர்வரை மறுதொடக்கம் செய்யவும்.',
        'global_saved' => 'பொது அமைப்புகள் சேமிக்கப்பட்டன',
