        'secret_stored_hint' => 'ஒரு secret ஏற்கனவே சேமிக்கப்பட்டுள்ளது. அதை வைத்திருக்க வெறுமையாக விடவும், அல்லது மாற்ற புதியதை உள்ளிடவும்.',
