    'api' => [
        'browser_title' => 'API',
        'title' => 'API',
        'subtitle' => 'FreeITSM REST API-க்கான keys-ஐ உருவாக்கி நிர்வகிக்கவும்; ஒவ்வொரு key-க்கும் நுணுக்கமான அனுமதிகள் உண்டு.',
        'base_url' => 'அடிப்படை URL',
        'base_url_desc' => 'அனைத்து v1 endpoints-உம் இந்த URL-க்கு கீழ் உள்ளன. <strong>Authorization: Bearer &lt;key&gt;</strong> மூலம் அங்கீகரிக்கவும்.',
        'documentation' => 'ஆவணம்',
        'docs_desc' => '<strong>ஆவணம்</strong> என்பது ஊடாடும் குறிப்பு — ஒவ்வொரு endpoint-ஐயும் உலாவவும், நேரடி அழைப்புகளை முயற்சிக்கவும், ஏழு மொழிகளில் தயாரான குறியீட்டை நகலெடுக்கவும்.',
        'openapi' => 'OpenAPI விவரக்குறிப்பு',
        'mcp' => 'AI உதவியாளரை இணைக்கவும் (MCP)',
        'mcp_desc' => 'FreeITSM <strong>Model Context Protocol</strong> பேசுகிறது, எனவே Claude Code அல்லது Claude Desktop போன்ற AI உதவியாளர் இதைப் படிக்கலாம் - projects, திறந்த சம்பவங்கள், சேவை நிலை, மாற்றங்கள், சொத்துகள் மற்றும் பல. இது <strong>படிக்க-மட்டும்</strong>; key-யின் பகுப்பாய்வாளர் பார்க்கக்கூடியதை மட்டுமே காணும்: அவர்களின் தொகுதிகள் மற்றும் key-யின் நிறுவனங்கள். கீழே <strong>MCP server</strong> அனுமதியுடன் ஒரு key-ஐ உருவாக்கி, உதவியாளருக்கு இந்த முகவரியைக் கொடுக்கவும். <a href="https://github.com/edmozley/freeitsm/wiki/MCP-Server" target="_blank" rel="noopener">வழிகாட்டியைப்</a> பார்க்கவும்.',
        'mcp_claude_code' => 'Claude Code-க்கு, இதை ஒரு terminal-இல் இயக்கவும் (YOUR_KEY இடத்தில் உங்கள் key-ஐ இடவும்):',
        'openapi_desc' => 'முழு API-யின் இயந்திரம் படிக்கக்கூடிய விளக்கம். இதை <strong>Postman</strong> அல்லது <strong>Insomnia</strong>-இல் இறக்குமதி செய்யவும், client library-ஐ உருவாக்கவும், அல்லது எந்த OpenAPI கருவிக்கும் கொடுக்கவும் &mdash; ஒவ்வொரு endpoint-ஐயும் கையால் இணைக்க வேண்டியதில்லை. புதியவரா? <a href="https://github.com/edmozley/freeitsm/wiki/REST-API-OpenAPI" target="_blank" rel="noopener">வழிகாட்டியைப்</a> பார்க்கவும்.',
        'view_json' => 'JSON பார்',
        'view_yaml' => 'YAML பார்',
        'keys' => 'API keys',
        'keys_desc' => 'ஒரு key ஒரு பகுப்பாய்வாளராகச் செயல்படுகிறது; அதன் அனுமதிகள் அனுமதிப்பதை மட்டுமே செய்ய முடியும். முழு key உருவாக்கும்போது ஒருமுறை மட்டுமே காட்டப்படும்.',
        'not_ready' => 'API key அட்டவணைகள் இன்னும் உருவாக்கப்படவில்லை — <a href="../db-verify/">தரவுத்தள சரிபார்ப்பை</a> ஒருமுறை இயக்கி, பின்னர் இந்தப் பக்கத்தை மீண்டும் ஏற்றவும்.',
        'col_name' => 'பெயர்',
        'col_key' => 'Key',
        'col_acts_as' => 'செயல்படுபவர்',
        'col_permissions' => 'அனுமதிகள்',
        'col_companies' => 'நிறுவனங்கள்',
        'col_status' => 'நிலை',
        'col_last_used' => 'கடைசியாகப் பயன்படுத்தியது',
        'col_actions' => 'செயல்கள்',
        'new_key' => 'புதிய API key',
        'edit_key' => 'API key-ஐத் திருத்து',
        'name_hint' => 'இந்த key எதற்காக, எ.கா. "Monitoring integration".',
        'name_ph' => 'Monitoring integration',
        'acts_as_hint' => 'டிக்கெட்டுகள், குறிப்புகள் மற்றும் தணிக்கை பதிவுகள் இந்தப் பகுப்பாய்வாளருக்குக் காரணமாக்கப்படும்.',
        'perms_hint' => 'ஒருங்கிணைப்புக்குத் தேவையானதை மட்டும் வழங்கவும் — மற்றவை அனைத்தும் மறுக்கப்படும்.',
        'select_all' => 'அனைத்தையும் தேர்ந்தெடு',
        'clear_all' => 'அனைத்தையும் அழி',
        'scope' => 'நிறுவன அணுகல்',
        'scope_all' => 'பகுப்பாய்வாளர் பார்க்கக்கூடிய அனைத்து நிறுவனங்கள்',
        'scope_specific' => 'குறிப்பிட்ட நிறுவனங்கள் மட்டும்',
        'expires' => 'காலாவதியாகும் தேதி',
        'expires_hint' => 'விருப்பத்தேர்வு. இந்தத் தேதிக்குப் பிறகு key வேலை செய்யாது.',
        'rate_limit' => 'கோரிக்கை வரம்பு',
        'rate_limit_hint' => 'நிமிடத்திற்கான கோரிக்கைகள். வெறுமையாக விட்டால் கணினி இயல்புநிலை (60) பயன்படுத்தப்படும்.',
        'created' => 'Key உருவாக்கப்பட்டது',
        'your_new_key' => 'உங்கள் புதிய API key:',
        'copy_now' => 'இப்போதே நகலெடுக்கவும் — இது hash செய்து சேமிக்கப்படுகிறது, மீண்டும் காட்டப்படாது.',
        'empty' => 'இன்னும் API keys இல்லை — ஒன்றை உருவாக்க சேர் என்பதைக் கிளிக் செய்யவும்.',
        'all' => 'அனைத்தும்',
        'never' => 'ஒருபோதும் இல்லை',
        'status_expired' => 'காலாவதியானது',
        'status_active' => 'செயலில்',
        'status_disabled' => 'முடக்கப்பட்டது',
        'perm_granted' => '{n} வழங்கப்பட்டன',
        'disable' => 'முடக்கு',
        'enable' => 'இயக்கு',
        'update_failed' => 'புதுப்பிப்பு தோல்வியடைந்தது',
        'delete_failed' => 'நீக்குதல் தோல்வியடைந்தது',
        'save_failed' => 'சேமிப்பு தோல்வியடைந்தது',
        'confirm_delete' => 'API key "{name}"-ஐ நீக்கவா? இதைப் பயன்படுத்தும் ஒருங்கிணைப்புகள் உடனடியாக வேலை செய்வதை நிறுத்தும்.',
        'need_company' => 'குறைந்தது ஒரு நிறுவனத்தைத் தேர்ந்தெடுக்கவும், அல்லது "அனைத்து நிறுவனங்களும்" என்பதைத் தேர்ந்தெடுக்கவும்.',
        'need_name' => 'key பெயர் தேவை.',
        'need_permission' => 'key-க்கு குறைந்தது ஒரு அனுமதியை வழங்கவும்.',
        'copy_failed' => 'நகலெடுக்க முடியவில்லை',
        'copy_key_failed' => 'key-ஐ தானாக நகலெடுக்க முடியவில்லை. அதைத் தேர்ந்தெடுத்து கையால் நகலெடுக்கவும் - அது மீண்டும் காட்டப்படாது.',
        'confirm_copied' => 'key-ஐ நகலெடுத்துவிட்டீர்களா? அது மீண்டும் காட்டப்படாது.',
    ],
    'webhooks' => [
        'browser_title' => 'Webhooks',
        'title' => 'Webhooks',
        'subtitle' => 'வெளிச்செல்லும் webhooks &mdash; <em>Send a webhook</em> பணிப்பாய்வு செயலால் வரிசையில் சேர்க்கப்படுபவை &mdash; தானியங்கி மறுமுயற்சிகளுடன் பின்னணியில் அனுப்பப்படுகின்றன, எனவே மெதுவான அல்லது செயலற்ற endpoint ஒரு டிக்கெட்டையும் தாமதப்படுத்தாது. இந்தப் பக்கம் அனுப்புதல் அமைக்கப்பட்டுள்ளதா, அனுப்புதலின் ஆரோக்கிய மேலோட்டம், மற்றும் ஒவ்வொரு கோரிக்கையையும் அதன் பதிலையும் பரிசோதித்து எதையும் மீண்டும் அனுப்பக்கூடிய முழுப் பதிவையும் காட்டுகிறது.',
        'pill_running' => 'அனுப்பும் worker இயங்குகிறது',
        'pill_stale' => 'அனுப்பும் worker தாமதமாகிறது',
        'pill_down' => 'அனுப்பும் worker நின்றுவிட்டது',
        'pill_never' => 'இன்னும் அமைக்கப்படவில்லை',
        'last_ran' => 'கடைசியாக இயங்கியது {when}',
        'running_ok' => 'பின்னணி worker இயங்கி வரிசையை அனுப்பிக்கொண்டிருக்கிறது.',
        'waiting_one' => '<strong>1</strong> webhook காத்திருக்கிறது &mdash; ஒரு நிமிடத்திற்குள் அனுப்பப்படும்.',
        'waiting_many' => '<strong>{n}</strong> webhooks காத்திருக்கின்றன &mdash; ஒரு நிமிடத்திற்குள் அனுப்பப்படும்.',
        'nothing_waiting' => 'தற்போது எதுவும் காத்திருக்கவில்லை.',
        'never_explain' => 'பின்னணி அனுப்பும் worker இயங்கத் திட்டமிடப்படும் வரை <strong>Webhooks அனுப்பப்படாது</strong>.',
        'down_explain' => '<strong>Webhooks இனி அனுப்பப்படுவதில்லை</strong> &mdash; worker கடைசியாக {when} இயங்கியது, அது நின்றுவிட்டதாகத் தெரிகிறது.',
        'stale_explain' => 'Worker இயங்குகிறது ஆனால் அட்டவணையை விட பின்தங்கியுள்ளது (கடைசி இயக்கம் {when}). இது ஒவ்வொரு நிமிடமும் இயங்க வேண்டும்.',
        'queued_one' => '<strong>1</strong> webhook வரிசையில் காத்திருக்கிறது.',
        'queued_many' => '<strong>{n}</strong> webhooks வரிசையில் காத்திருக்கின்றன.',
        'step1' => '<strong>அனுப்பும் worker-ஐ ஒவ்வொரு நிமிடமும் இயங்கும்படி திட்டமிடவும்.</strong> சேவையகத்தில், இந்தக் கட்டளையை ஒரு திட்டமிட்ட பணியிலிருந்து (Windows Task Scheduler) அல்லது cron-இலிருந்து (Linux) இயக்கவும்:',
        'step1_http' => 'Shell-இலிருந்து PHP-ஐ இயக்க முடியவில்லையா? அதற்குப் பதிலாக HTTP வழியாக அழைக்கவும் (எ.கா. ஒரு hosted cron சேவையிலிருந்து):',
        'step2' => 'நிகழ்வுகள் வரிசையை நிரப்பத் தொடங்க, ஒரு பணிப்பாய்வில் <strong><em>Send a webhook</em> செயலைச் சேர்க்கவும்</strong> &mdash; <a href="{url}">பணிப்பாய்வுகள்</a> பகுதியில்.',
        'step3' => '<strong>இந்தப் பக்கத்தைக் கவனியுங்கள்.</strong> Worker இயங்கியதும், மேலே உள்ள நிலை பச்சையாக மாறி, அனுப்புதல்கள் கீழே தோன்றும். முழு அமைப்புக் குறிப்புகள் (Windows &amp; Linux, கையொப்பச் சரிபார்ப்பு) <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">Workflows wiki-யில்</a> உள்ளன.',
        'fact_worker' => 'Worker ஸ்கிரிப்ட்',
        'fact_retry' => 'மறுமுயற்சி அட்டவணை',
        'fact_retention' => 'பதிவு வைத்திருப்பு',
        'fact_queued' => 'இப்போது வரிசையில்',
        'days' => '{n} நாட்கள்',
        'dp_title' => 'தரவுப் பாதுகாப்பு',
        'dp_desc' => 'உங்கள் webhooks பற்றி FreeITSM வட்டில் எதைச் சேமிக்கிறது, எவ்வளவு காலம்.',
        'enc_on_title' => 'Webhook URLகள் மற்றும் கையொப்ப ரகசியங்கள் சேமிப்பில் குறியாக்கம் செய்யப்படுகின்றன',
        'enc_on_body' => 'AES-256-GCM மூலம் சேமிக்கப்படுகிறது, பணிப்பாய்விலும் அனுப்புதல் வரிசையிலும். Webhook URL என்பது தனக்குத்தானே ஒரு சான்றுரு &mdash; அதை வைத்திருக்கும் எவரும் உங்கள் சேனலில் இடுகையிடலாம் &mdash; கையொப்ப ரகசியம் ஒரு செய்தி உண்மையில் உங்களிடமிருந்தே வந்தது என்பதை நிரூபிக்கிறது.',
        'enc_off_title' => 'குறியாக்க key எதுவும் அமைக்கப்படவில்லை &mdash; webhook URLகள் மற்றும் கையொப்ப ரகசியங்கள் எளிய உரையாகச் சேமிக்கப்படுகின்றன',
        'enc_off_body' => 'குறியாக்க key கோப்பு இருக்கும்போது FreeITSM இவற்றை குறியாக்கம் செய்கிறது, ஆனால் இந்த நிறுவலில் அது இல்லை; எனவே உங்கள் webhooks முற்றிலும் தோல்வியடைவதற்குப் பதிலாக அவை அப்படியே சேமிக்கப்படுகின்றன. தரவுத்தளத்தை அல்லது அதன் காப்புப்பிரதியைப் படிக்கக்கூடிய எவரும் உங்கள் சேனல்களில் இடுகையிடவும் உங்கள் கையொப்பங்களைப் போலியாக உருவாக்கவும் முடியும். குறியாக்க key-ஐ (<code>ENCRYPTION_KEY_PATH</code>) அமைத்து, சேமிக்கப்பட்ட மதிப்புகளை குறியாக்கம் செய்ய ஒவ்வொரு webhook பணிப்பாய்வையும் மீண்டும் சேமிக்கவும்.',
        'ret_label' => 'அனுப்பிய payloads-ஐ வைத்திருக்கும் காலம்',
        'ret_none' => 'அவற்றைச் சேமிக்கவே வேண்டாம்',
        'ret_1' => '1 நாள்',
        'ret_7' => '7 நாட்கள் (பரிந்துரைக்கப்படுகிறது)',
        'ret_30' => '30 நாட்கள்',
        'ret_forever' => 'அனுப்புதல் பதிவு இருக்கும் வரை',
        'ret_help' => 'அனுப்புதல் பதிவு அனுப்பப்பட்ட சரியான payload-ஐச் சேமிக்கிறது. <strong>முழுப் பதிவு</strong> வடிவத்தில் அது ஒரு <strong>முழு டிக்கெட்</strong> &mdash; பொருள், கோரிக்கையாளர், அனைத்தும் &mdash; எளிய உரையில் இங்கே நகலெடுக்கப்படுகிறது. இத்தனை நாட்களுக்குப் பிறகு payload மற்றும் பதில் உள்ளடக்கங்கள் அழிக்கப்படும்; அனுப்புதல் <em>பதிவு</em> (endpoint, நிலை, நேரம், பிழைகள்) மேலே உள்ள பதிவு வைத்திருப்பு ({days} நாட்கள்) அந்த வரிசையை முழுவதுமாக நீக்கும் வரை தணிக்கைக்காக வைக்கப்படும்.',
        'ret_tradeoff' => '<strong>சமரசம்:</strong> <em>Replay</em> சேமிக்கப்பட்ட payload-ஐ மீண்டும் அனுப்புகிறது, எனவே payload அழிக்கப்பட்ட அனுப்புதலை இனி மீண்டும் அனுப்ப முடியாது. Replay வழக்கமாக தோல்வியடைந்த சில மணி நேரங்களுக்குள் பயன்படுத்தப்படும், வாரங்கள் கழித்து அல்ல.',
        'ov_title' => 'மேலோட்டம்',
