        'purged_body' => 'அனுப்பப்பட்ட சரியான payload, இந்தப் பக்கத்தில் உள்ள payload வைத்திருப்பு அமைப்பின்படி இனி சேமிக்கப்படவில்லை. இந்த அனுப்புதலை இனி மீண்டும் அனுப்ப முடியாது.',
