    'bingo' => [
        'heading' => 'Feature Bingo',
        'intro' => 'பெரும்பாலானோர் தங்களிடம் உள்ளதில் ஒரு சிறு பகுதியையே பயன்படுத்துகிறார்கள். ஒவ்வொரு அட்டையும் FreeITSM செய்யக்கூடிய ஒன்று, இங்கே அது அமைக்கப்பட்டதும் அதன் நட்சத்திரம் ஒளிரும். அது என்ன, ஏன் செய்யத் தகுந்தது, எங்கே அமைப்பது என்பதைப் பார்க்க ஒன்றைத் திறக்கவும். நீங்கள் ஒருபோதும் பயன்படுத்தாதது எதுவாக இருந்தாலும்: அதை எங்களுக்கு வேண்டாம் என்று குறிக்கவும், அது மதிப்பெண்ணிலிருந்து நீங்கும்.',
        'needs_verify' => 'அட்டைகளை எங்களுக்கு வேண்டாம் என்று குறிக்க System → Database Verification-ஐ இயக்கவும். நட்சத்திரங்கள் ஏற்கனவே வேலை செய்கின்றன.',
        'stars_of' => '{total}-இல் {lit} நட்சத்திரங்கள்',
        'percent' => 'உங்களுக்குப் பொருந்தும் அம்சங்களில் {pct}%',
