    'managers' => [
        'heading' => 'மேலாளர்கள்',
        'intro' => 'மேலாளர் என்பவர் சுய-சேவை போர்டலில் தாம் நிர்வகிப்பவர்கள் உருவாக்கிய டிக்கெட்டுகளைப் பார்க்கக்கூடியவர் - எடுத்துக்காட்டாக ஒரு துறையின் தலைவர். அவர்களுக்கு போர்டலில் <strong>குழு டிக்கெட்டுகள்</strong> தாவல் கிடைக்கும். சேவை மேசைக்கு எந்த மாற்றமும் இல்லை.',
        'needs_verify' => 'முதலில் System → Database Verification (தரவுத்தள சரிபார்ப்பு) இயக்கவும். அது இயங்கும் வரை, இங்கு எதை அமைத்தாலும் மேலாளர்கள் முடக்கத்திலேயே இருப்பார்கள், ஏனெனில் ரகசிய டிக்கெட்டுகளை வேறுபடுத்த முடியாது.',
        'on_heading' => 'போர்டலில் மேலாளர்கள்',
        'enabled' => 'மேலாளர்கள் தங்கள் குழுவின் டிக்கெட்டுகளைப் பார்க்கட்டும்',
        'enabled_desc' => 'நீங்கள் இயக்கும் வரை முடக்கத்தில் இருக்கும். இது முடக்கத்தில் இருக்கும்போது கீழே உள்ள எதுவும் செயல்படாது.',
        'source_heading' => 'மேலாளர்கள் எங்கிருந்து வருகிறார்கள்',
        'source_desc' => 'இரண்டு மூலங்கள், இரண்டும் ஒரே நேரத்தில். மேலாண்மை வரிகள் ஒவ்வொரு மேலாளருக்கும் Tickets → Users அல்லது Assets → Users என்பதில் உள்ள மேலாளர் அணுகல் பொத்தானால் அமைக்கப்படுகின்றன.',
        'directory' => 'ஒவ்வொருவரின் மேலாளர் புலத்தைப் பயன்படுத்து',
        'directory_desc' => 'ஒருவரின் மேலாளராக - கையால் அல்லது உங்கள் டைரக்டரியிலிருந்து - அமைக்கப்பட்டவர் அவர்களின் டிக்கெட்டுகளைப் பார்க்கலாம்.',
        'depth' => 'எவ்வளவு கீழ்மட்டம் வரை',
        'depth_direct' => 'அவர்களுக்கு நேரடியாகப் புகாரளிப்பவர்கள்',
        'depth_all' => 'அவர்களுக்குக் கீழுள்ள அனைவரும், கடைசி மட்டம் வரை',
        'can_heading' => 'மேலாளர்கள் என்ன செய்யலாம்',
        'can_desc' => 'மேலாளர்கள் எப்போதும் தங்கள் குழுவின் டிக்கெட்டுகளைப் படிக்கலாம். வேறு என்ன செய்யலாம் என்பது ஒவ்வொரு டிக்கெட்டிலும் அவர்களுக்குத் தெரிவிக்கப்படும்.',
        'can_reply' => 'தங்கள் குழுவின் டிக்கெட்டுகளுக்குப் பதிலளிக்கலாம்',
        'can_close' => 'தங்கள் குழுவின் டிக்கெட்டுகளை மூடலாம்',
        'conf_heading' => 'ரகசிய டிக்கெட்டுகள்',
        'conf_desc' => 'ரகசியம் எனக் குறிக்கப்பட்ட டிக்கெட்டில் மேலாளர் எதைப் பார்க்கிறார் - HR-க்கு அனுப்பப்பட்ட மருத்துவ நிலை, அல்லது மேலாளரைப் பற்றிய புகார்.',
        'conf_none' => 'எதுவுமே இல்லை (பரிந்துரைக்கப்படுகிறது)',
        'conf_none_desc' => 'டிக்கெட் முழுவதுமாக விலக்கப்படும். அப்படி ஒன்று இருப்பதே மேலாளருக்குத் தெரியாது.',
        'conf_stub' => 'ரகசிய டிக்கெட் ஒன்று உள்ளது என்பது மட்டும்',
        'conf_stub_desc' => '"ரகசிய டிக்கெட்" என அதன் எண் மற்றும் நிலையுடன் பட்டியலிடப்படும், அது கூறும் எதுவும் இல்லாமல். இது மட்டுமே யாரோ ஒரு தனிப்பட்ட விஷயத்தை எழுப்பினார் என்பதை மேலாளருக்குத் தெரிவிக்கக்கூடும் என்பதை அறிந்திருங்கள்.',
        'conf_all' => 'அனைத்தும்',
        'conf_all_desc' => 'ரகசிய டிக்கெட்டுகள் மற்றவற்றைப் போலவே காட்டப்படும். இந்த போர்டல் வழியாக ரகசியமான எதுவும் உருவாக்கப்படாது என்றால் மட்டுமே இதைத் தேர்ந்தெடுக்கவும்.',
        'notify_heading' => 'புதிய டிக்கெட்டுகள் பற்றி மேலாளர்களுக்குத் தெரிவித்தல்',
        'notify_desc' => 'மேலாளரின் குழுவில் ஒருவர் டிக்கெட் உருவாக்கும்போது - ஆனால் ரகசிய டிக்கெட் போன்று மேலாளர் திறக்க அனுமதிக்கப்படாத ஒன்றுக்கு ஒருபோதும் இல்லை.',
        'notify_none' => 'அறிவிக்க வேண்டாம் (இயல்புநிலை)',
        'notify_none_desc' => 'குழு டிக்கெட்டுகளைப் பார்க்கும்போது மேலாளர்கள் புதிய டிக்கெட்டுகளைக் காண்பார்கள்.',
        'notify_email' => 'மின்னஞ்சல் அனுப்பு',
        'notify_email_desc' => 'டிக்கெட்டின் எண், பொருள் மற்றும் அதற்கான இணைப்புடன் கூடிய மின்னஞ்சல், டிக்கெட் அஞ்சல் பெட்டியிலிருந்து மேலாளரின் முகவரிக்கு அனுப்பப்படும். முகவரி இல்லாத மேலாளர்களுக்கு எதுவும் கிடைக்காது. இணைப்புக்கு பொது இணைய முகவரி தேவை (Tickets → Settings → Email Templates) - அது இல்லாமல், மின்னஞ்சல் வழியாக வரும் டிக்கெட் வேலை செய்யாத இணைப்பை அனுப்பும்.',
        'notify_bell' => 'போர்டலின் அறிவிப்பு மணியில்',
        'notify_bell_desc' => 'போர்டல் தலைப்பில் ஒவ்வொரு மேலாளருக்கும் உள்ள மணியில் - பகுப்பாய்வாளர்களுக்கு உள்ள அதே மணி. மின்னஞ்சலை விட அமைதியானது: அவர்கள் அடுத்து உள்நுழையும்போது அங்கே இருக்கும்.',
        'leavers_heading' => 'விலகியவர்கள்',
        'leavers' => 'விலகியவர்களின் டிக்கெட்டுகளைத் தொடர்ந்து காட்டு',
        'leavers_desc' => 'இயல்பாக இயக்கத்தில் உள்ளது, எனவே ஒருவர் விலகும்போது திறந்திருக்கும் டிக்கெட்டின் மேற்பார்வை தொடரும். விலகிய மேலாளர் எப்போதும் அணுகலை இழப்பார்.',
        'edit_heading' => 'மேலாண்மை வரிகளை யார் அமைக்கலாம்',
        'edit_admins' => 'நிர்வாகிகள் மட்டும்',
        'edit_people' => 'நபர்களைத் திருத்தக்கூடிய பகுப்பாய்வாளர்கள்',
        'edit_desc' => 'ஒருவருக்கு மேலாளர் அணுகலை வழங்குவது மற்றவர்களின் டிக்கெட்டுகளைப் படிக்க அனுமதிக்கிறது, எனவே அதைச் சிலருக்கு மட்டும் வைத்திருப்பது நல்லது.',
        'saved' => 'சேமிக்கப்பட்டது',
        'save_failed' => 'சேமிக்க முடியவில்லை: {error}',
        'overview_heading' => 'மேலாளர்கள்',
        'overview_desc' => 'யாரையாவது நிர்வகிக்கும் அனைவரும், அவர்கள் எத்தனை பேரைப் பார்க்க முடியும் என்பதுடன் - மேலாளர்கள் இயக்கப்பட்டிருந்தால் எப்படி இருக்கும் என்று கணக்கிடப்பட்டது, எனவே இயக்கும் முன் சரிபார்க்கலாம்.',
        'search' => 'மேலாளர்களைத் தேடு',
        'col_manager' => 'மேலாளர்',
        'col_company' => 'நிறுவனம்',
        'col_from' => 'மூலம்',
        'col_can_see' => 'பார்க்கக்கூடியவை',
        'from_directory' => '{count} நேரடி கீழ்நிலையினர்',
        'from_directory_one' => '1 நேரடி கீழ்நிலையினர்',
        'from_lines' => '{count} வரிகள்',
        'from_lines_one' => '1 வரி',
        'from_exclusions' => '{count} விலக்குகள்',
        'from_exclusions_one' => '1 விலக்கு',
        'can_see_people' => '{count} நபர்கள்',
        'can_see_people_one' => '1 நபர்',
        'warn_left' => 'விலகிவிட்டார் - எதையும் பார்க்க முடியாது',
        'warn_department' => '"{name}" என்பதில் யாரும் இல்லை - பெயர் மாற்றப்பட்டதா?',
        'none' => 'இன்னும் யாரும் யாரையும் நிர்வகிக்கவில்லை.',
        'none_search' => 'அந்தத் தேடலுக்குப் பொருந்தும் மேலாளர் இல்லை.',
        'page_of' => 'பக்கம் {page} / {pages}',
        'prev' => 'முந்தையது',
        'next' => 'அடுத்தது',
    ],
    'self_service' => [
        'heading' => 'சுய-சேவை போர்டல்',
        'intro' => 'டிக்கெட்டுகளை உருவாக்குபவர்களுக்கு போர்டல் எப்படித் தோன்றுகிறது, அது அவர்களை என்ன செய்ய அனுமதிக்கிறது. பெரும்பாலான நிறுவனங்களில் வாடிக்கையாளர் பார்க்கும் FreeITSM-இன் ஒரே பகுதி போர்டல்தான், எனவே மற்றதிலிருந்து தனியாக பிராண்டிங் செய்யத் தகுந்த திரை இதுவே.',
        'appearance_heading' => 'தோற்றம்',
        'appearance_desc' => 'இவை போர்டலுக்கு மட்டுமே பொருந்தும். <strong>System &rarr; Branding</strong> கீழுள்ள லோகோ தொடர்ந்து செயலி, உள்நுழைவுத் திரை மற்றும் உங்கள் மின்னஞ்சல்களுக்குப் பொருந்தும்.',
        'logo_label' => 'போர்டல் லோகோ',
        'logo_desc' => 'போர்டலுக்கான வேறு லோகோ &mdash; சேவை மேசை வேறு பெயரில் இயங்கும்போது, அல்லது பிரதான லோகோ இருண்ட செயலி தலைப்புக்காக வரையப்பட்டு வெளிர் பக்கத்தில் சரியாகத் தெரியாதபோது பயனுள்ளது. பிரதான லோகோவைப் பயன்படுத்த இதை வெறுமையாக விடவும்.',
        'logo_remove' => 'அகற்று',
        'logo_hint' => 'PNG அல்லது JPG, 2MB வரை. SVG ஏற்கப்படாது: அது ஸ்கிரிப்டைக் கொண்டிருக்கக்கூடிய XML, மேலும் இந்தப் படம் போர்டலுக்கு வரும் அனைவருக்கும் வழங்கப்படுகிறது.',
        'logo_saved' => 'போர்டல் லோகோ புதுப்பிக்கப்பட்டது',
        'logo_position_label' => 'லோகோ எங்கே இருக்கும்',
        'logo_position_desc' => 'பட்டியில் அது போர்டல் பெயருக்கு அருகில், சிறியதாக, எப்போதும் திரையில் இருக்கும். பக்கத்தில் அது மேலே ஒருமுறை, பெரியதாக, பக்கப் பின்னணியில் தோன்றும் - பட்டி அப்போது போர்டல் பெயரை மீண்டும் காட்டாமல் ஒருமுறை மட்டும் காட்டும்.',
        'logo_position_header' => 'மேல் பட்டியில்',
        'logo_position_page' => 'பக்கத்தின் மேலே',
        'header_colour_label' => 'தலைப்புப் பட்டி நிறம்',
        'header_colour_desc' => 'ஒவ்வொரு போர்டல் பக்கத்தின் மேலேயும் உள்ள பட்டி. நிறத் தீமைப் பின்பற்ற இதை வெறுமையாக விடவும்.',
        'table_colour_label' => 'அட்டவணைத் தலைப்பு நிறம்',
        'table_colour_desc' => 'டிக்கெட் மற்றும் சொத்துப் பட்டியல்களின் தலைப்பு வரிசை. நிறத் தீமைப் பின்பற்ற இதை வெறுமையாக விடவும்.',
        'use_theme' => 'தீமைப் பயன்படுத்து',
        'pattern_label' => 'பின்னணி',
        'pattern_desc' => 'பக்கத்தின் பின்னால் ஒரு மெல்லிய வடிவம். படமாக அல்லாமல் CSS-இல் வரையப்பட்டு, தீமிலிருந்து நிறமேற்றப்படுவதால் வெளிர் மற்றும் இருண்ட இரண்டிலும் படிக்கும்படி இருக்கும்.',
        'pattern_none' => 'எதுவுமில்லை',
        'pattern_dots' => 'புள்ளிகள்',
        'pattern_grid' => 'கட்டம்',
        'pattern_diagonal' => 'சாய்வு',
        'pattern_flow' => 'ஓட்டம்',
        'pattern_mesh' => 'வலை',
        'preview_heading' => 'முன்னோட்டம்',
        'preview_desc' => 'வாடிக்கையாளர் பார்ப்பது. மேலே உள்ள அமைப்புகளை மாற்றும்போது புதுப்பிக்கப்படும்; நீங்கள் சேமி என்பதை அழுத்தும் வரை எதுவும் சேமிக்கப்படாது.',
        'preview_portal' => 'ஆதரவு போர்டல்',
        'preview_col_ref' => 'குறிப்பு',
        'preview_col_subject' => 'பொருள்',
        'preview_row' => 'லேப்டாப் இயங்கவில்லை',
        'behaviour_heading' => 'போர்டல் மக்களை என்ன செய்ய அனுமதிக்கிறது',
        'behaviour_desc' => 'இரண்டும் தொடக்கத்தில் முடக்கத்தில் உள்ளன, எனவே இந்த அமைப்புகள் வருவதற்கு முன்பு இருந்தபடியே ஏற்கனவே உள்ள போர்டல் செயல்படும்.',
        'self_close_label' => 'மக்கள் தங்கள் சொந்த டிக்கெட்டை மூட அனுமதி',
        'self_close_desc' => 'போர்டலில் உள்ள டிக்கெட்டில் <strong>இனி தேவையில்லை</strong> பொத்தானைச் சேர்க்கிறது. கோரிக்கையாளர் மூடினார் என்ற குறிப்புடன் டிக்கெட் மூடப்படும், எனவே ஒரு பகுப்பாய்வாளர் தாம் தொடாத ஒன்றைத் தீர்த்தது போலத் தோன்றாமல், யார் செய்தார் என்பதைப் பதிவு காட்டும். யாராவது ஏற்கனவே வேலை செய்யும் டிக்கெட்டை அவர்களால் மூட முடியாது, அது தீர்க்கப்பட்டு அவர்களின் உறுதிப்படுத்தலுக்காகக் காத்திருந்தால் தவிர &mdash; அதை உறுதிப்படுத்துவது ஏற்கனவே அவர்களின் உரிமை.',
        'my_assets_label' => 'தங்களுக்கு ஒதுக்கப்பட்ட உபகரணங்களை மக்களுக்குக் காட்டு',
        'my_assets_desc' => 'அந்த நபருக்கு ஒதுக்கப்பட்ட சொத்துகளைப் பட்டியலிடும் <strong>என் உபகரணங்கள்</strong> பக்கத்தைச் சேர்க்கிறது, எனவே அவர்கள் கேட்க டிக்கெட் உருவாக்காமலே வரிசை எண்ணைச் சரிபார்க்கலாம். படிக்க மட்டும், மேலும் அவர்களுடையது மட்டுமே.',
        'load_failed' => 'அமைப்புகளை ஏற்ற முடியவில்லை. எதுவும் மாற்றப்படவில்லை.',
        'save_failed' => 'அமைப்புகளைச் சேமிக்க முடியவில்லை.',
