        'field_name_placeholder' => 'Acme Ltd',
        'col_ticket_code' => 'டிக்கெட் குறியீடு',
        'code_clash' => 'மற்றொரு நிறுவனம் இந்தக் குறியீட்டைப் பயன்படுத்துகிறது - அவற்றில் ஒன்றுக்கு தனிக் குறியீட்டை வழங்கவும்.',
        'field_code' => 'டிக்கெட் குறியீடு',
        'field_code_hint' => 'டிக்கெட் எண்களில் இந்த நிறுவனத்தைக் குறிக்கும் சிறிய குறியீடு, நீங்கள் எண்ணிடலை அதைப் பயன்படுத்துமாறு அமைத்திருந்தால். எழுத்துகளும் இலக்கங்களும், 12 வரை. வெறுமையாக விட்டால் பெயரிலிருந்து ஒன்று உருவாக்கப்படும்.',
        'field_code_placeholder' => 'ACME',
        'logo_label' => 'லோகோ',
        'logo_hint' => 'இந்த நிறுவனத்தில் பணிபுரிபவர்களுக்கு Files டெஸ்க்டாப்பில் காட்டப்படும். PNG, JPG, GIF அல்லது WebP, 2 MB வரை. இல்லையெனில் அமைப்பின் லோகோ பயன்படுத்தப்படும்.',
        'logo_choose' => 'தேர்ந்தெடு',
