        'logo_none' => 'லோகோ இல்லை',
        'field_code_derived' => 'வெறுமையாக விட்டால், இந்த நிறுவனம் {code} என்பதைப் பயன்படுத்தும்.',
        'field_code_underivable' => 'குறியீட்டை உருவாக்க பெயரில் எழுத்துகள் இல்லை, எனவே ஒன்றை உள்ளிடவும்.',
        'cb_active' => 'செயலில்',
        'cb_active_desc' => 'செயலற்ற நிறுவனங்கள் அன்றாடப் பயன்பாட்டிலிருந்து மறைக்கப்படும். இயல்புநிலை நிறுவனம் எப்போதும் செயலில் இருக்கும்.',
        'cancel' => 'ரத்து',
        'save' => 'சேமி',
        'required_name' => 'பெயர் தேவை',
        'company_saved' => 'நிறுவனம் சேமிக்கப்பட்டது',
        'error' => 'பிழை: {error}',
        'save_failed' => 'சேமிக்க முடியவில்லை',
        'domains_label' => 'மின்னஞ்சல் டொமைன்கள்',
        'domains_hint' => 'பகிரப்பட்ட உள்வரும் அஞ்சல் பெட்டியிலிருந்து வரும் அஞ்சல், அனுப்புநரின் டொமைன் இவற்றில் ஒன்றுடன் பொருந்தும்போது இந்த நிறுவனத்துக்கு அனுப்பப்படும். பொது வழங்குநர்களை (gmail.com போன்றவை) சேர்க்க முடியாது - அந்த அஞ்சல் triage-இலிருந்து கையால் வகைப்படுத்தப்படும்.',
        'domains_save_first' => 'முதலில் நிறுவனத்தைச் சேமிக்கவும், பிறகு அதன் மின்னஞ்சல் டொமைன்களைச் சேர்க்கவும்.',
        'domains_none' => 'இன்னும் டொமைன்கள் இல்லை.',
