        'domain_added' => 'டொமைன் சேர்க்கப்பட்டது',
        'domain_removed' => 'டொமைன் அகற்றப்பட்டது',
        'domain_add_failed' => 'டொமைனைச் சேர்க்க முடியவில்லை',
        'domain_remove_failed' => 'டொமைனை அகற்ற முடியவில்லை',
        'senders_label' => 'குறிப்பிட்ட அனுப்புநர்கள்',
        'senders_hint' => 'இந்த நிறுவனத்துக்கு அனுப்பப்படும் தனிப்பட்ட முகவரிகள், டொமைனுக்கு முன்பே சரிபார்க்கப்படும். டொமைனை இணைக்க முடியாத பொது வழங்குநர்களில் உள்ளவர்களுக்கு (jane@gmail.com) இதைப் பயன்படுத்தவும் - அவர்களின் அஞ்சல் triage-இல் விழாமல் சரியான நிறுவனத்தைச் சென்றடையும்.',
        'senders_none' => 'இன்னும் குறிப்பிட்ட அனுப்புநர்கள் இல்லை.',
