        'sender_remove' => 'அகற்று',
        'sender_added' => 'அனுப்புநர் சேர்க்கப்பட்டார்',
        'sender_removed' => 'அனுப்புநர் அகற்றப்பட்டார்',
        'sender_add_failed' => 'அனுப்புநரைச் சேர்க்க முடியவில்லை',
        'sender_remove_failed' => 'அனுப்புநரை அகற்ற முடியவில்லை',
        'routing_label' => 'இந்த நிறுவனத்துக்கு மின்னஞ்சல் எப்படிச் சென்றடைகிறது',
        'routing_hint' => 'மேலே உள்ள அஞ்சல் பெட்டிகள் மற்றும் டொமைன்களிலிருந்து கணக்கிடப்பட்ட படிக்க-மட்டும் சுருக்கம். பதில்கள் எப்போதும் செய்தி வந்த அதே அஞ்சல் பெட்டியிலிருந்து செல்லும்.',
        'routing_loading' => 'வழித்தடத்தைக் கணக்கிடுகிறது…',
        'routing_pinned' => 'பிரத்யேக அஞ்சல் பெட்டி',
        'routing_pinned_desc' => '{address} முகவரிக்கு வரும் அஞ்சல் எப்போதும் இந்த நிறுவனத்துக்கே சொந்தம். பதில்கள் இந்த முகவரியிலிருந்து செல்லும்.',
        'routing_shared' => 'பகிரப்பட்ட உள்வரவு',
        'routing_shared_desc' => 'அனுப்புநரின் டொமைன் {domains} ஆக இருக்கும்போது {address} முகவரிக்கு வரும் அஞ்சல் இங்கே அனுப்பப்படும். பதில்கள் இந்த முகவரியிலிருந்து செல்லும்.',
        'routing_shared_desc_senders' => 'அனுப்புநர் {senders} ஆக இருக்கும்போது {address} முகவரிக்கு வரும் அஞ்சல் இங்கே அனுப்பப்படும். பதில்கள் இந்த முகவரியிலிருந்து செல்லும்.',
        'routing_shared_desc_both' => 'அனுப்புநரின் டொமைன் {domains} ஆக இருக்கும்போது, அல்லது அனுப்புநர் {senders} ஆக இருக்கும்போது {address} முகவரிக்கு வரும் அஞ்சல் இங்கே அனுப்பப்படும். பதில்கள் இந்த முகவரியிலிருந்து செல்லும்.',
        'routing_reply_from' => 'பதில்கள் {address} முகவரியிலிருந்து',
        'routing_inactive' => 'செயலற்றது',
        'routing_unauth' => 'அங்கீகரிக்கப்படவில்லை',
        'routing_default_note' => 'இயல்புநிலை நிறுவனமாக, வேறு எந்த நிறுவனத்துடனும் பொருந்தாத அனைத்து அஞ்சலையும் (triage வரிசை) இதுவே பெறுகிறது.',
        'routing_warn_no_route' => 'தானியங்கி மின்னஞ்சல் வழித்தடம் இல்லை. இந்த நிறுவனத்துக்கான அஞ்சலை triage வரிசையிலிருந்து கையால் வகைப்படுத்த வேண்டும். ஒரு அஞ்சல் பெட்டியை இதற்குப் பொருத்தவும், அல்லது பகிரப்பட்ட உள்வரவு பொருந்துமாறு ஒரு மின்னஞ்சல் டொமைனைப் பதிவு செய்யவும்.',
        'routing_warn_domains_no_shared' => 'டொமைன்கள் பதிவு செய்யப்பட்டுள்ளன, ஆனால் அவற்றுடன் பொருத்த செயலில் உள்ள பகிரப்பட்ட உள்வரவு அஞ்சல் பெட்டி இல்லை. ஒன்றைச் சேர்க்கவும், அல்லது ஒரு அஞ்சல் பெட்டியை இந்த நிறுவனத்துக்குப் பொருத்தவும்.',
        'routing_warn_unauth' => 'மேலே உள்ள வழித்தடத்தில் உள்ள ஒரு அஞ்சல் பெட்டி அங்கீகரிக்கப்படவில்லை, எனவே அது அமைப்புகளில் மீண்டும் இணைக்கப்படும் வரை அஞ்சல் செல்லாது.',
        'routing_failed' => 'வழித்தட சுருக்கத்தை ஏற்ற முடியவில்லை.',
        'freemail_title' => 'பொது மின்னஞ்சல் டொமைன்கள்',
        'freemail_hint' => 'Gmail மற்றும் Outlook போன்ற பொது வழங்குநர்களிடமிருந்து வரும் அஞ்சல் எந்த நிறுவனத்துக்கும் தானாக அனுப்பப்படாது - இரண்டு வாடிக்கையாளர்கள் ஒரே வழங்குநரைப் பகிரலாம், எனவே அது triage-இல் விழுந்து கையால் வகைப்படுத்தப்படும். பொதுவான வழங்குநர்கள் எப்போதும் சேர்க்கப்பட்டுள்ளனர்; உங்கள் வாடிக்கையாளர்கள் பயன்படுத்தும் மற்றவற்றைச் சேர்க்கவும், அவையும் அதே முறையில் கையாளப்படும்.',
        'freemail_placeholder' => 'example-isp.com',
        'freemail_add' => 'சேர்',
        'freemail_remove' => 'அகற்று',
        'freemail_none' => 'கூடுதல் டொமைன்கள் எதுவும் சேர்க்கப்படவில்லை - கீழே உள்ள உள்ளமைந்த வழங்குநர்கள் மட்டுமே.',
        'freemail_added' => 'டொமைன் சேர்க்கப்பட்டது',
        'freemail_removed' => 'டொமைன் அகற்றப்பட்டது',
        'freemail_add_failed' => 'டொமைனைச் சேர்க்க முடியவில்லை',
        'freemail_remove_failed' => 'டொமைனை அகற்ற முடியவில்லை',
        'freemail_builtin_toggle' => '{count} உள்ளமைந்த வழங்குநர்களைக் காட்டு',
    ],
    'routing_test' => [
        'title' => 'மின்னஞ்சல் வழித்தடச் சோதனை',
        'subtitle' => 'ஒரு மின்னஞ்சல் வந்ததாக வைத்துக்கொண்டு, புதிய டிக்கெட் எங்கே வகைப்படுத்தப்படும் - எந்த நிறுவனம், அல்லது triage வரிசை - மற்றும் எந்த விதி அதை முடிவு செய்தது என்று பாருங்கள். எதுவும் உருவாக்கப்படாது; இது உங்கள் அஞ்சல் பெட்டி மற்றும் டொமைன் அமைப்புகளை மட்டுமே படிக்கும்.',
        'single_company_note' => 'இந்த நிறுவலில் ஒரே ஒரு நிறுவனம் உள்ளது, எனவே ஒவ்வொரு மின்னஞ்சலும் அதற்கே வகைப்படுத்தப்படும். வழித்தடம் முடிவு செய்ய ஏதாவது இருக்க இரண்டாவது நிறுவனத்தைச் சேர்க்கவும்.',
        'from_label' => 'அனுப்புநர் முகவரி',
        'from_hint' => 'மின்னஞ்சல் அனுப்பப்பட்ட முகவரி. பகிரப்பட்ட உள்வரவு வழித்தடம் முதலில் சரியான முகவரியையும், பிறகு அதன் டொமைனையும் பொருத்தும்.',
        'from_placeholder' => 'jane@acme.com',
        'mailbox_label' => 'வந்து சேரும் அஞ்சல் பெட்டி',
        'mailbox_hint' => 'மின்னஞ்சலைப் பெற்ற அஞ்சல் பெட்டி. பொருத்தப்பட்ட அஞ்சல் பெட்டி நிறுவனத்தை முழுமையாக முடிவு செய்யும்; பகிரப்பட்ட உள்வரவு அஞ்சல் பெட்டி அனுப்புநரின் டொமைன் மூலம் வழி நடத்தும்.',
        'mailbox_loading' => 'ஏற்றுகிறது…',
        'mailbox_choose' => 'அஞ்சல் பெட்டியைத் தேர்ந்தெடுக்கவும்…',
        'no_mailboxes' => 'அஞ்சல் பெட்டிகள் எதுவும் உள்ளமைக்கப்படவில்லை',
        'opt_pinned' => '{company} நிறுவனத்துக்குப் பொருத்தப்பட்டது',
        'opt_shared' => 'பகிரப்பட்ட உள்வரவு',
        'run' => 'சோதி',
        'pick_mailbox' => 'முதலில் ஒரு அஞ்சல் பெட்டியைத் தேர்ந்தெடுக்கவும்',
        'failed' => 'வழித்தடச் சோதனை தோல்வியடைந்தது',
        'placeholder' => 'மின்னஞ்சல் எங்கே சேரும் என்பதைக் காண ஒரு சோதனையை இயக்கவும்.',
        'result_company_label' => 'வகைப்படுத்தப்பட்ட நிறுவனம்',
        'result_triage_label' => 'அனுப்பப்பட்ட இடம்',
        'result_triage_value' => 'triage வரிசை (ஒதுக்கப்படவில்லை)',
        'steps_title' => 'இது எப்படி முடிவு செய்யப்பட்டது',
        'step_reply' => 'ஏற்கனவே உள்ள டிக்கெட்டுக்கான பதிலா?',
        'step_reply_detail' => 'நடைமுறையில் முதலில் சரிபார்க்கப்படும் (பதில் தன் டிக்கெட்டின் நிறுவனத்தைப் பெறும்), ஆனால் அது பொருளில் டிக்கெட் குறிப்பு இருப்பதைப் பொறுத்தது - எனவே அனுப்புநர் மற்றும் அஞ்சல் பெட்டியிலிருந்து மட்டும் சோதிக்க முடியாது.',
        'step_single' => 'ஒரே நிறுவனம் உள்ள நிறுவல்',
        'step_single_detail' => 'ஒரே ஒரு நிறுவனம் மட்டுமே உள்ளது, எனவே அனைத்து அஞ்சலும் {company} நிறுவனத்துக்கு வகைப்படுத்தப்படும்.',
        'step_pinned' => 'பொருத்தப்பட்ட அஞ்சல் பெட்டியா?',
        'step_pinned_fired' => '{mailbox} என்பது {company} நிறுவனத்துக்குப் பொருத்தப்பட்டுள்ளது, எனவே மின்னஞ்சல் அங்கே வகைப்படுத்தப்படும். அனுப்புநர் புறக்கணிக்கப்படுவார்.',
        'step_pinned_skipped' => '{mailbox} என்பது பகிரப்பட்ட உள்வரவு அஞ்சல் பெட்டி, எனவே வழித்தடம் அனுப்புநரைச் சோதிக்கச் செல்கிறது.',
        'step_sender' => 'அனுப்புநர் முகவரி ஒரு நிறுவனத்துடன் இணைக்கப்பட்டுள்ளதா?',
        'step_sender_fired' => '{address} முகவரி {company} நிறுவனத்தின் குறிப்பிட்ட அனுப்புநர்கள் பட்டியலில் உள்ளது, எனவே மின்னஞ்சல் அங்கே வகைப்படுத்தப்படும். டொமைனுக்கு முன்பே சரிபார்க்கப்படும்.',
        'step_sender_nomatch' => 'எந்த நிறுவனத்தின் குறிப்பிட்ட அனுப்புநர்கள் பட்டியலிலும் {address} இல்லை, எனவே வழித்தடம் அனுப்புநரின் டொமைனைச் சோதிக்கச் செல்கிறது.',
        'step_sender_noaddress' => 'அனுப்புநர் முகவரி கொடுக்கப்படவில்லை, எனவே பொருத்த எதுவும் இல்லை.',
        'step_domain' => 'அனுப்புநர் டொமைன் ஒரு நிறுவனத்துடன் பொருந்துகிறதா?',
        'step_domain_fired' => '{domain} டொமைன் {company} நிறுவனத்துக்குப் பதிவு செய்யப்பட்டுள்ளது.',
        'step_domain_freemail' => '{domain} ஒரு பொது மின்னஞ்சல் வழங்குநர், அது எந்த நிறுவனத்துக்கும் பதிவு செய்யப்படுவதில்லை - எனவே இங்கே பொருந்தாது, triage-க்குச் செல்லும்.',
        'step_domain_nomatch' => 'எந்த நிறுவனமும் {domain} என்பதைப் பதிவு செய்யவில்லை.',
        'step_domain_nodomain' => 'அனுப்புநர் டொமைன் கொடுக்கப்படவில்லை, எனவே பொருத்த எதுவும் இல்லை.',
        'step_triage' => 'triage வரிசை',
        'step_triage_detail' => 'எதுவும் பொருந்தவில்லை, எனவே டிக்கெட் எந்த நிறுவனத்துக்கும் ஒதுக்கப்படாமல் triage வரிசையில் கையால் வகைப்படுத்தப்படக் காத்திருக்கும். எதுவும் இழக்கப்படவில்லை.',
    ],
    'cost_centres' => [
        'title' => 'செலவு மையங்கள்',
        'intro' => 'ஒவ்வொரு நிறுவனத்திற்கும் உங்கள் நிதித் துறை செலவுகளைப் பதிவு செய்யும் செலவு மையங்கள். அவற்றை கைமுறையாகச் சேர்க்கலாம், அல்லது ஸ்பிரெட்ஷீட்டை இறக்குமதி செய்வதன் மூலம் அல்லது API வழியாக உங்கள் கணக்கியல் அமைப்புடன் ஒத்திசைவில் வைத்திருக்கலாம். இனி பயன்படுத்தப்படாத செலவு மையத்தைச் செயலற்றதாக்கலாம்: ஏற்கனவே அதில் பதிவான செலவுகளில் அது இருக்கும், ஆனால் புதியவற்றுக்கு வழங்கப்படாது.',
        'needs_verify' => 'செலவு மையங்களுக்கு ஒரு புதிய தரவுத்தள அட்டவணை தேவை. System → Database Verification என்பதை இயக்கி, பிறகு இந்தப் பக்கத்திற்குத் திரும்பவும்.',
        'company' => 'நிறுவனம்',
        'search' => 'குறியீடு, பெயர் அல்லது விளக்கத்தைத் தேடு',
