        'empty' => 'இன்னும் செலவு மையங்கள் இல்லை. ஒன்றைச் சேர்க்கவும், அல்லது ஸ்பிரெட்ஷீட்டிலிருந்து உங்கள் பட்டியலை இறக்குமதி செய்யவும்.',
