        'add_title' => 'செலவு மையத்தைச் சேர்',
        'edit_title' => 'செலவு மையம் {code} ஐத் திருத்து',
        'field_code' => 'குறியீடு',
        'field_code_hint' => 'உங்கள் நிதி அமைப்பில் எழுதப்பட்டவாறே - எழுத்துகளும் எண்களும் இரண்டும் செல்லும், முன்னணிப் பூஜ்ஜியங்கள் அப்படியே இருக்கும் (0010 என்பது 0010 ஆகவே இருக்கும்). ஒவ்வொரு குறியீட்டையும் ஒரு நிறுவனத்தில் ஒருமுறை மட்டுமே பயன்படுத்த முடியும்; பெரிய எழுத்து வேறுபாடு கவனிக்கப்படாது, எனவே N1414 மற்றும் n1414 ஒரே குறியீடு.',
        'field_name' => 'பெயர்',
        'field_description' => 'விளக்கம்',
        'field_parent' => 'மேல்நிலை செலவு மையம்',
        'field_parent_hint' => 'விருப்பத்தேர்வு. உங்கள் படிநிலையை உருவாக்க, இந்தச் செலவு மையத்தை மற்றொன்றின் கீழ் வைக்கும்.',
        'parent_none' => 'எதுவுமில்லை - மேல்நிலை',
        'field_active' => 'செயலில்',
        'field_active_hint' => 'இனி பயன்படுத்தப்படாதபோது அணைக்கவும். ஏற்கனவே அதில் பதிவான செலவுகளில் அது இருக்கும், ஆனால் புதியவற்றுக்கு வழங்கப்படாது.',
        'saved' => 'செலவு மையம் சேமிக்கப்பட்டது',
        'save_failed' => 'செலவு மையத்தைச் சேமிக்க முடியவில்லை.',
        'delete_title' => 'செலவு மையத்தை நீக்கு',
        'delete_confirm' => '{code} - {name} ஐ நீக்கவா? அது பயன்படுத்தப்பட்டு இப்போது நிறுத்தப்பட்டிருந்தால், அதற்குப் பதிலாக செயலற்றதாக்குங்கள்.',
        'delete_has_children' => '{code} - {name} இன் கீழ் {count} செலவு மையம்(ங்கள்) உள்ளன, எனவே அவை நகர்த்தப்படும் அல்லது நீக்கப்படும் வரை இதை நீக்க முடியாது. இதைச் செயலற்றதாக்குவதே பொதுவாகத் தேவையானது.',
        'deleted' => 'செலவு மையம் நீக்கப்பட்டது',
        'delete_failed' => 'செலவு மையத்தை நீக்க முடியவில்லை.',
        'import_title' => 'செலவு மையங்களை இறக்குமதி செய்',
        'import_help_html' => 'முதல் வரி தலைப்புகளாக உள்ள Excel பணிப்புத்தகம் (.xlsx) அல்லது CSV கோப்பைப் பயன்படுத்தவும். <strong>குறியீடு</strong> மட்டுமே தேவை; <strong>பெயர்</strong>, <strong>விளக்கம்</strong>, <strong>மேல்நிலைக் குறியீடு</strong> மற்றும் <strong>செயலில்</strong> (ஆம் அல்லது இல்லை) இருந்தால் பயன்படுத்தப்படும், பிற நெடுவரிசைகள் புறக்கணிக்கப்படும். பட்டியலில் ஏற்கனவே உள்ள குறியீடுகள் புதுப்பிக்கப்படும், புதியவை சேர்க்கப்படும், எதுவும் நீக்கப்படாது. அமைப்பைச் சரியாகப் பெற எளிதான வழி, முதலில் ஏற்றுமதி செய்து அந்தக் கோப்பைத் திருத்துவதே.',
        'import_zeros_html' => '<strong>முன்னணிப் பூஜ்ஜியங்கள்:</strong> நீங்கள் CSV ஐ Excel இல் திறந்து மீண்டும் சேமித்தால், கோப்பு FreeITSM ஐ அடையும் முன்பே Excel 0010 ஐ 10 ஆக மாற்றிவிடும். உங்கள் பட்டியலைத் திருத்த Excel ஏற்றுமதியை (.xlsx) பயன்படுத்தவும் - அதன் குறியீடுகள் உரையாகச் சேமிக்கப்படுவதால் பூஜ்ஜியங்கள் அப்படியே இருக்கும்.',
        'import_file' => 'கோப்பு',
        'import_deactivate' => 'கோப்பில் இல்லாத செலவு மையங்களைச் செயலற்றதாக்கு',
        'import_deactivate_hint' => 'உங்கள் நிதி அமைப்பிலிருந்து ஏற்றுமதி செய்த முழுப் பட்டியலுக்கு. எதுவும் நீக்கப்படாது - விடுபட்டவை செயலற்றதாக மட்டுமே ஆக்கப்படும்.',
        'import_choose' => 'இறக்குமதி செய்ய ஒரு கோப்பைத் தேர்ந்தெடுக்கவும்.',
        'import_failed' => 'இறக்குமதி தோல்வியடைந்தது. எதுவும் மாற்றப்படவில்லை.',
        'import_errors' => '{count} சிக்கல்கள் - கோப்பில் அவற்றைச் சரிசெய்து மீண்டும் முன்னோட்டம் பார்க்கவும். எதுவும் இறக்குமதி செய்யப்படவில்லை.',
